def fmt_progress_bar(pct: int) -> str:
    pct = max(0, min(100, pct))
    filled = int(round(pct / 10))
    return "▓" * filled + "░" * (10 - filled) + f" {pct}%"


def fmt_time(seconds: float) -> str:
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = int(seconds % 60)
    if h > 0:
        return f"{h:02d}:{m:02d}:{s:02d}"
    return f"{m:02d}:{s:02d}"


def run_cmd(cmd: list[str], timeout: int = 600) -> subprocess.CompletedProcess:
    proc = subprocess.Popen(
        cmd,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        start_new_session=True,
    )
    try:
        out, err = proc.communicate(timeout=timeout)
        return subprocess.CompletedProcess(cmd, proc.returncode, out, err)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except Exception:
            proc.kill()
        out, err = proc.communicate()
        return subprocess.CompletedProcess(cmd, -9, out, err)


class ProgressTracker:
    def __init__(self, chat_id: int, message_id: int, job_id: str = None):
        self.chat_id = chat_id
        self.message_id = message_id
        self.job_id = job_id
        self.last_ts = 0.0
        self.last_text = ""
        self.anim_frame = 0

    async def update(self, text: str, force: bool = False):
        if not self.message_id or text == self.last_text:
            return
        # Heartbeat the job registry even when the Telegram edit is
        # throttled: the watchdog must know the job is still alive.
        touch_active_job(self.chat_id, text)
        now = time.monotonic()
        if not force and (now - self.last_ts) < 3.0:
            return
        self.last_ts = now
        self.last_text = text
        self.anim_frame += 1
        animated_text = f"{get_anim_emoji(self.anim_frame)} {text}"
        try:
            await tg_api("editMessageText", {
                "chat_id": self.chat_id,
                "message_id": self.message_id,
                "text": animated_text,
                "reply_markup": job_progress_keyboard(),
            })
        except Exception:
            pass


async def tg_api(method: str, data: dict = None, timeout: float = 90.0):
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/{method}"
    for attempt in range(3):
        try:
            async with httpx.AsyncClient(timeout=timeout, http2=False) as client:
                resp = await client.post(url, json=data or {})
                return resp.json()
        except Exception:
            await asyncio.sleep(1.5)
    return {"ok": False}


async def send_text(chat_id: int, text: str, reply_to: int = None, reply_markup: dict = None):
    payload = {
        "chat_id": chat_id,
        "text": text,
        "parse_mode": "HTML",
        "reply_to_message_id": reply_to,
    }
    if reply_markup:
        payload["reply_markup"] = reply_markup
    res = await tg_api("sendMessage", payload)
    if not res.get("ok"):
        # HTML အမှားကြောင့် ပျက်ရင် plain text နဲ့ ပြန်ပို့ (မီနူး မပျောက်အောင်)
        payload.pop("parse_mode", None)
        res = await tg_api("sendMessage", payload)
    return res.get("result", {}).get("message_id")


async def edit_text(chat_id: int, message_id: int, text: str, reply_markup: dict = None):
    if not message_id:
        return
    try:
        payload = {
            "chat_id": chat_id,
            "message_id": message_id,
            "text": text,
            "parse_mode": "HTML",
        }
        if reply_markup:
            payload["reply_markup"] = reply_markup
        res = await tg_api("editMessageText", payload)
        if not (res or {}).get("ok"):
            payload.pop("parse_mode", None)
            await tg_api("editMessageText", payload)
    except Exception:
        pass


async def edit_reply_markup(chat_id: int, message_id: int, reply_markup: dict = None):
    if not message_id:
        return
    try:
        await tg_api(
            "editMessageReplyMarkup",
            {
                "chat_id": chat_id,
                "message_id": message_id,
                "reply_markup": reply_markup or {"inline_keyboard": []},
            },
        )
    except Exception:
        pass


async def answer_callback(callback_id: str, text: str = ""):
    try:
        await tg_api("answerCallbackQuery", {
            "callback_query_id": callback_id,
            "text": text,
            "show_alert": False,
        })
    except Exception:
        pass


async def ensure_persistent_keyboard(
    chat_id,
    reply_to: int = None,
    *,
    force: bool = False,
) -> bool:
    """Install Telegram's bottom reply keyboard for this chat.

    Telegram only shows a reply keyboard after the bot sends a message
    carrying it; registering commands at startup is not enough for an old
    chat.  Send one small installer message the first time a chat talks to
    a newly deployed process, and again whenever ``/start`` forces it.
    """
    try:
        chat_key = int(chat_id)
    except (TypeError, ValueError):
        return False
    if not force and chat_key in PERSISTENT_KEYBOARD_CHATS:
        return False

    PERSISTENT_KEYBOARD_CHATS.add(chat_key)
    version = globals().get("BUILD_VERSION", "")
    text = "⌨️ အောက်ခြေခလုတ်တွေ အဆင်သင့်ဖြစ်ပါပြီ။ Video file သို့မဟုတ် Link ကို ဒီအတိုင်းပို့လိုက်ရုံပါပဲ။"
    if version:
        text += f"\n🆕 <code>{version}</code>"
    try:
        message_id = await send_text(
            chat_key,
            text,
            reply_to=reply_to,
            reply_markup=persistent_menu_keyboard(),
        )
    except Exception as e:
        PERSISTENT_KEYBOARD_CHATS.discard(chat_key)
        logger.warning(f"persistent keyboard send failed for {chat_key}: {e}")
        return False
    if not message_id:
        PERSISTENT_KEYBOARD_CHATS.discard(chat_key)
        return False
    return True


async def send_main_menu(
    chat_id: int,
    reply_to: int = None,
    with_persistent_keyboard: bool = False,
):
    if with_persistent_keyboard:
        await ensure_persistent_keyboard(
            chat_id, reply_to=reply_to, force=True
        )
    # /start and /menu explain the complete current workflow and all 20
    # currently selected features before the user sends a video/link.
    text = start_features_text(chat_id)
    return await send_text(
        chat_id,
        text,
        reply_to=reply_to,
        reply_markup=main_menu_keyboard(chat_id),
    )


async def tg_upload_media(method: str, data: dict, field_name: str, file_name: str, file_path: str, mime_type: str) -> dict:
    """Upload one Telegram media file with bounded, flood-aware retries.

    The file is streamed from disk on every attempt instead of first
    being copied into a 45MB in-memory payload.  A long final can need
    a dozen sequential uploads; holding each whole part (plus httpx's
    multipart body) in RAM on a small free instance risks an OOM or
    restart part-way through delivery -- the user then sees only the
    first N of the announced parts.  Telegram ``retry_after`` values
    are also honoured instead of being discarded: rapid large uploads
    can legitimately receive a 429 whose required wait is longer than
    a fixed 2.5s pause, and ignoring it used to burn every retry while
    the flood window was still closed.
    """
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/{method}"
    last_result: dict = {"ok": False, "description": "Telegram upload failed"}
    for attempt in range(1, 4):
        wait_seconds = 2.5 * attempt
        try:
            with open(file_path, "rb") as media_file:
                async with httpx.AsyncClient(timeout=600.0) as client:
                    resp = await client.post(
                        url,
                        data=data,
                        files={field_name: (file_name, media_file, mime_type)},
                    )
            try:
                res = resp.json()
            except Exception:
                res = {
                    "ok": False,
                    "error_code": int(getattr(resp, "status_code", 0) or 0),
                    "description": f"Telegram HTTP {getattr(resp, 'status_code', '?')}",
                }
            if isinstance(res, dict) and res.get("ok"):
                return res
            if isinstance(res, dict):
                last_result = res
                params = res.get("parameters") or {}
                try:
                    retry_after = float(params.get("retry_after") or 0)
                except (TypeError, ValueError):
                    retry_after = 0.0
                if retry_after > 0:
                    wait_seconds = min(60.0, retry_after + 1.0)
                logger.warning(
                    "Telegram %s upload attempt %s/3 failed for %s: %s",
                    method,
                    attempt,
                    file_name,
                    _safe_error_text(res.get("description") or res, 300),
                )
            else:
                last_result = {
                    "ok": False,
                    "description": "Telegram returned a non-object response",
                }
        except Exception as exc:
            last_result = {
                "ok": False,
                "description": _safe_error_text(exc, 300),
            }
            logger.warning(
                "Telegram %s upload attempt %s/3 raised for %s: %s",
                method,
                attempt,
                file_name,
                _safe_error_text(exc, 300),
            )
        if attempt < 3:
            await asyncio.sleep(wait_seconds)
    gc.collect()
    return last_result


def _safe_video_extension(file_name: str = "", mime_type: str = "") -> str:
    ext = os.path.splitext(str(file_name or ""))[1].lower()
    if ext in TELEGRAM_VIDEO_EXTENSIONS:
        return ext
    mime = str(mime_type or "").lower()
    mime_extensions = {
        "video/mp4": ".mp4",
        "video/quicktime": ".mov",
        "video/x-m4v": ".m4v",
        "video/x-matroska": ".mkv",
        "video/webm": ".webm",
        "video/x-msvideo": ".avi",
        "video/mpeg": ".mpeg",
        "video/3gpp": ".3gp",
        "video/mp2t": ".ts",
    }
    return mime_extensions.get(mime, ".mp4")


def _telegram_video_attachment(msg: dict) -> dict | None:
    """Normalize a video uploaded directly in Telegram.

    Users can send a normal Telegram video, an animation/video note, or a
    video as a document (the latter preserves the original file).  Return
    only safe metadata needed to download it later; never trust a client
    supplied filename as a filesystem path.
    """
    if not isinstance(msg, dict):
        return None

    candidates = []
    for kind in ("video", "animation", "video_note"):
        value = msg.get(kind)
        if isinstance(value, dict) and value.get("file_id"):
            candidates.append((kind, value))

    document = msg.get("document")
    if isinstance(document, dict) and document.get("file_id"):
        mime = str(document.get("mime_type") or "").lower()
        ext = os.path.splitext(str(document.get("file_name") or ""))[1].lower()
        if mime.startswith("video/") or ext in TELEGRAM_VIDEO_EXTENSIONS:
            candidates.append(("document", document))

    if not candidates:
        return None
    kind, value = candidates[0]
    file_name = os.path.basename(str(value.get("file_name") or "telegram-video"))
    return {
        "kind": "telegram_file",
        "telegram_kind": kind,
        "file_id": str(value.get("file_id") or ""),
        "file_unique_id": str(value.get("file_unique_id") or ""),
        "file_name": file_name,
        "mime_type": str(value.get("mime_type") or ""),
        "file_size": int(value.get("file_size") or 0),
        "duration": float(value.get("duration") or 0),
        "extension": _safe_video_extension(
            file_name, str(value.get("mime_type") or "")
        ),
    }


def _telegram_attachment_label(attachment: dict) -> str:
    name = str((attachment or {}).get("file_name") or "Telegram video")
    size = int((attachment or {}).get("file_size") or 0)
    duration = float((attachment or {}).get("duration") or 0)
    details = []
    if duration > 0:
        details.append(fmt_time(duration))
    if size > 0:
        details.append(f"{size / (1024 * 1024):.1f}MB")
    return name + (f" ({', '.join(details)})" if details else "")


def _extract_first_url(text: str) -> str:
    """Extract the first HTTP(S) URL from a bare link or share caption."""
    match = re.search(r"https?://[^\s<>\"'“”‘’]+", str(text or ""), re.IGNORECASE)
    if not match:
        return ""
    value = match.group(0).strip()
    # Share text commonly wraps links in punctuation/brackets.
    while value and value[-1] in ")]}>.,!?;:'\"":
        # Do not strip a balanced closing parenthesis that belongs to a
        # Wikipedia-style URL; share links used here do not need one.
        value = value[:-1]
    return value


def _url_hostname(url: str) -> str:
    try:
        return (urlparse(str(url or "")).hostname or "").lower().strip()
    except Exception:
        return ""


def _is_rednote_url(url: str) -> bool:
    host = _url_hostname(url)
    return bool(
        host == "xiaohongshu.com"
        or host.endswith(".xiaohongshu.com")
        or host == "rednote.com"
        or host.endswith(".rednote.com")
        or host == "xhslink.com"
        or host.endswith(".xhslink.com")
        or host == "xhslink.cn"
        or host.endswith(".xhslink.cn")
        or host.endswith(".xhscdn.com")
    )


def _is_direct_media_url(url: str) -> bool:
    try:
        parsed = urlparse(str(url or ""))
        path = (parsed.path or "").lower()
        host = (parsed.hostname or "").lower()
    except Exception:
        return False
    return bool(
        path.endswith(tuple(TELEGRAM_VIDEO_EXTENSIONS))
        or path.endswith(".m3u8")
        or host.endswith(".xhscdn.com")
        or host.endswith("googlevideo.com")
        or "sns-video" in host
    )


_TELEGRAM_LINK_HOSTS = {"t.me", "telegram.me", "telegram.dog"}
_TELEGRAM_RESERVED_FIRST_SEGMENTS = {
    "addemoji",
    "addstickers",
    "addtheme",
    "auth",
    "blog",
    "confirmphone",
    "contact",
    "download",
    "faq",
    "features",
    "iv",
    "joinchat",
    "login",
    "premium",
    "proxy",
    "setlanguage",
    "share",
    "socks",
    "stickers",
    "themes",
}


def _telegram_link_info(url: str) -> dict | None:
    """Classify a Telegram web link without making a network request.

    A bare ``https://t.me/<name>`` URL identifies a bot/group/channel,
    not a downloadable message.  Only a public URL with a numeric final
    message ID (``https://t.me/<name>/<id>``) can be treated as a
    candidate video post.  Invite and ``/c/...`` links identify private
    material that a Bot API bot cannot fetch from the link alone.
    """
    clean = _extract_first_url(url) or str(url or "").strip()
    try:
        parsed = urlparse(clean)
    except Exception:
        return None
    host = (parsed.hostname or "").lower().strip()
    if not host:
        return None
    is_telegram_host = host in _TELEGRAM_LINK_HOSTS or any(
        host.endswith(f".{candidate}") for candidate in _TELEGRAM_LINK_HOSTS
    )
    if not is_telegram_host:
        return None

    segments = [
        segment.strip()
        for segment in (parsed.path or "").split("/")
        if segment.strip()
    ]
    info = {
        "kind": "profile",
        "username": "",
        "message_id": "",
        "segments": segments,
        "url": clean,
    }
    if not segments:
        return info

    first = segments[0]
    lowered_first = first.lower()
    if first.startswith("+") or lowered_first == "joinchat":
        info["kind"] = "invite"
        return info
    if lowered_first == "c":
        info["kind"] = "private_post" if len(segments) >= 3 else "private"
        if segments[-1].isdigit():
            info["message_id"] = segments[-1]
        return info
    if lowered_first == "s":
        if len(segments) >= 3 and segments[-1].isdigit():
            info.update(
                {
                    "kind": "public_post",
                    "username": segments[1],
                    "message_id": segments[-1],
                }
            )
        elif len(segments) >= 2:
            info["username"] = segments[1]
        return info
    if lowered_first in _TELEGRAM_RESERVED_FIRST_SEGMENTS:
        info["kind"] = "service"
        return info

    info["username"] = first
    if len(segments) >= 2 and segments[-1].isdigit():
        info.update({"kind": "public_post", "message_id": segments[-1]})
    return info


def _telegram_link_error(url: str, info: dict | None = None) -> SourceDownloadError:
    clean = _extract_first_url(url) or str(url or "").strip()
    info = info or _telegram_link_info(clean) or {}
    kind = str(info.get("kind") or "profile")
    if kind in ("invite", "private", "private_post"):
        user_message = (
            "ဒီ Telegram link က private group/channel သို့မဟုတ် invite link ဖြစ်လို့ "
            "bot က link တစ်ခုတည်းနဲ့ video ကို ဝင်ယူလို့မရပါ။ "
            "Video ကိုယ်တိုင်ကို ဒီ bot ထဲ forward သို့မဟုတ် တိုက်ရိုက် send လုပ်ပါ။"
        )
        detail = f"Telegram {kind} URL cannot be fetched by a Bot API bot from the link alone"
    elif kind == "public_post":
        user_message = (
            "ဒီ Telegram post မှာ download လုပ်လို့ရတဲ့ public video မတွေ့ပါ။ "
            "Video ကိုယ်တိုင်ကို ဒီ bot ထဲ forward သို့မဟုတ် တိုက်ရိုက် send လုပ်ပါ။"
        )
        detail = "Telegram public post contains no downloadable public video URL"
    elif kind == "service":
        user_message = (
            "ဒီ Telegram link က video post link မဟုတ်ပါ။ "
            "Video ကိုယ်တိုင်ကို ဒီ bot ထဲ forward/send လုပ်ပါ၊ သို့မဟုတ် "
            "public video post link (ဥပမာ https://t.me/name/123) ကို ပို့ပါ။"
        )
        detail = "Telegram service URL has no downloadable video message"
    else:
        user_message = (
            "ဒီ link က Telegram bot/group/channel ရဲ့ profile link ပါ။ "
            "Video post link မဟုတ်ပါ။ အဲဒီ group/channel ထဲက video ကိုယ်တိုင်ကို "
            "ဒီ bot ထဲ forward သို့မဟုတ် တိုက်ရိုက် send လုပ်ပါ၊ သို့မဟုတ် "
            "video post link (ဥပမာ https://t.me/name/123) ကို ပို့ပါ။"
        )
        detail = "Telegram profile URL has no message/video identifier"
    return SourceDownloadError(user_message, detail=detail, user_message=user_message)



def _configured_cookie_file_path() -> str:
    configured = str(globals().get("YTDLP_COOKIES_FILE") or "").strip()
    candidates = [configured] if configured else []
    candidates.extend(
        ["/etc/secrets/yt-dlp-cookies.txt", "/etc/secrets/cookies.txt"]
    )
    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            return candidate
    return ""


def _normalise_cookie_domain(domain: str = "") -> str:
    value = str(domain or "").strip().lower()
    if not value or "xiaohongshu.com" in value or "rednote.com" in value or "xhslink" in value:
        return ".xiaohongshu.com"
    if "xhscdn.com" in value:
        return ".xhscdn.com"
    return value if value.startswith(".") or "." in value else ".xiaohongshu.com"


def _cookie_records_from_value(value) -> list[tuple[str, str, str, str]]:
    raw = str(value or "").strip()
    if not raw:
        return []

    if raw[:1] in ("[", "{"):
        try:
            data = json.loads(raw)
        except Exception:
            data = None
        if data is not None:
            if isinstance(data, dict) and isinstance(data.get("cookies"), list):
                items = data["cookies"]
            elif isinstance(data, list):
                items = data
            elif isinstance(data, dict):
                return [
                    (str(name), str(cookie_value), ".xiaohongshu.com", "/")
                    for name, cookie_value in data.items()
                    if str(name).strip() and not isinstance(cookie_value, (dict, list))
                ]
            else:
                items = []
            records = []
            for item in items:
                if not isinstance(item, dict):
                    continue
                name = str(item.get("name") or item.get("key") or "").strip()
                cookie_value = item.get("value")
                if name and cookie_value is not None:
                    records.append(
                        (
                            name,
                            str(cookie_value),
                            _normalise_cookie_domain(str(item.get("domain") or "")),
                            str(item.get("path") or "/") or "/",
                        )
                    )
            if records:
                return records

    records = []
    for line in raw.splitlines():
        clean = line.strip()
        if clean.startswith("#HttpOnly_"):
            clean = clean[len("#HttpOnly_") :]
        elif not clean or clean.startswith("#"):
            continue
        fields = clean.split("\t")
        if len(fields) < 7:
            continue
        name = str(fields[5] or "").strip()
        if name:
            records.append(
                (
                    name,
                    "\t".join(fields[6:]),
                    _normalise_cookie_domain(fields[0]),
                    str(fields[2] or "/") or "/",
                )
            )
    if records:
        return records

    return [
        (name, cookie_value, ".xiaohongshu.com", "/")
        for name, cookie_value in _parse_cookie_header(raw).items()
    ]


def _source_cookie_records() -> list[tuple[str, str, str, str]]:
    records = _cookie_records_from_value(globals().get("XHS_COOKIE") or "")
    if records:
        return records
    cookie_file = _configured_cookie_file_path()
    if not cookie_file:
        return []
    try:
        with open(cookie_file, "r", encoding="utf-8", errors="ignore") as fh:
            return _cookie_records_from_value(fh.read(1024 * 1024))
    except OSError:
        return []


def _yt_dlp_cookies_file() -> str:
    configured_file = _configured_cookie_file_path()
    if configured_file:
        return configured_file
    records = _cookie_records_from_value(globals().get("XHS_COOKIE") or "")
    if not records:
        return ""
    lines = ["# Netscape HTTP Cookie File"]
    for name, cookie_value, domain, path in records:
        safe_name = str(name).replace("\t", "").replace("\r", "").replace("\n", "")
        safe_value = (
            str(cookie_value).replace("\t", "").replace("\r", "").replace("\n", "")
        )
        if not safe_name:
            continue
        lines.append(
            "\t".join(
                [
                    domain,
                    "TRUE" if domain.startswith(".") else "FALSE",
                    path or "/",
                    "FALSE",
                    "0",
                    safe_name,
                    safe_value,
                ]
            )
        )
    if len(lines) <= 1:
        return ""
    content = "\n".join(lines) + "\n"
    target = os.path.join(str(globals().get("WORK_ROOT") or "/tmp"), ".yt-dlp-cookies.txt")
    try:
        os.makedirs(os.path.dirname(target) or ".", exist_ok=True)
        existing = ""
        if os.path.isfile(target):
            with open(target, "r", encoding="utf-8", errors="ignore") as fh:
                existing = fh.read()
        if existing != content:
            temp_target = f"{target}.tmp"
            with open(temp_target, "w", encoding="utf-8") as fh:
                fh.write(content)
            try:
                os.chmod(temp_target, 0o600)
            except OSError:
                pass
            os.replace(temp_target, target)
        return target
    except OSError:
        return ""


def _rednote_cookie_configured() -> bool:
    return bool(
        str(globals().get("XHS_COOKIE") or "").strip()
        or _configured_cookie_file_path()
    )


def _parse_cookie_header(value: str) -> dict:
    cookies = {}
    for item in str(value or "").split(";"):
        if "=" not in item:
            continue
        name, cookie_value = item.split("=", 1)
        name = name.strip()
        if name:
            cookies[name] = cookie_value.strip()
    return cookies


def _source_browser_headers(url: str = "", referer: str = "") -> dict:
    headers = {
        "User-Agent": YTDLP_USER_AGENT,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8,my;q=0.7",
    }
    if referer:
        headers["Referer"] = referer
    elif _is_rednote_url(url):
        headers["Referer"] = "https://www.xiaohongshu.com/"
    return headers


def _rednote_httpx_cookies() -> httpx.Cookies:
    jar = httpx.Cookies()
    for name, value, domain, path in _source_cookie_records():
        # xhslink starts on another host and redirects to Xiaohongshu.
        # Bind configured cookies explicitly to the destination domain so
        # they survive that redirect instead of being attached only to the
        # short-link host.
        jar.set(name, value, domain=domain, path=path or "/")
    return jar


async def download_telegram_file(
    file_id: str,
    out_path: str,
    tracker=None,
    *,
    expected_size: int = 0,
    raise_on_error: bool = False,
) -> float:
    """Download an uploaded Telegram file to disk and return its duration.

    The public Telegram Bot API can only download files up to 20MB through
    ``getFile``.  Previously every failure here collapsed to ``0`` and the
    user only saw the generic “source download failed”.  When
    ``raise_on_error`` is set, return the actionable reason instead.
    """

    def fail(message: str, detail: str = "") -> float:
        logger.warning("Telegram file download failed: %s", _safe_error_text(detail or message))
        if raise_on_error:
            raise SourceDownloadError(message, detail=detail or message, user_message=message)
        return 0.0

    try:
        known_size = int(expected_size or 0)
    except (TypeError, ValueError):
        known_size = 0
    if known_size > TELEGRAM_BOT_FILE_DOWNLOAD_LIMIT_BYTES:
        size_mb = known_size / (1024 * 1024)
        return fail(
            "Telegram video file က 20MB ထက်ကြီးလို့ Bot က တိုက်ရိုက် download မလုပ်နိုင်ပါ။ "
            f"ပို့ထားတဲ့ file က {size_mb:.1f}MB ပါ။ Video link အနေနဲ့ပို့ပါ၊ သို့မဟုတ် "
            "20MB အောက် compress/split လုပ်၍ ပြန်ပို့ပါ။",
            f"Telegram Bot API getFile limit exceeded: {known_size} bytes",
        )
    if not file_id:
        return fail("Telegram file_id မရပါ။ Video ကို ပြန်ပို့ကြည့်ပါ။")
    if not BOT_TOKEN:
        return fail("BOT_TOKEN မသတ်မှတ်ရသေးလို့ Telegram file download မလုပ်နိုင်ပါ။")

    result = await tg_api("getFile", {"file_id": file_id}, timeout=120.0)
    if not (result or {}).get("ok"):
        description = _safe_error_text((result or {}).get("description") or "unknown error")
        if "file is too big" in description.lower() or "too big" in description.lower():
            return fail(
                "Telegram video file က 20MB ထက်ကြီးလို့ Bot က တိုက်ရိုက် download မလုပ်နိုင်ပါ။ "
                "Video link အနေနဲ့ပို့ပါ၊ သို့မဟုတ် 20MB အောက် compress/split လုပ်၍ ပြန်ပို့ပါ။",
                description,
            )
        return fail(
            "Telegram file ကို download လုပ်ဖို့ getFile မအောင်မြင်ပါ။ Video ကို ပြန်ပို့ကြည့်ပါ။",
            description,
        )
    result_data = (result or {}).get("result") or {}
    file_path = str(result_data.get("file_path") or "")
    try:
        remote_size = int(result_data.get("file_size") or 0)
    except (TypeError, ValueError):
        remote_size = 0
    if remote_size > TELEGRAM_BOT_FILE_DOWNLOAD_LIMIT_BYTES:
        return fail(
            "Telegram video file က 20MB ထက်ကြီးလို့ Bot က တိုက်ရိုက် download မလုပ်နိုင်ပါ။ "
            f"File အရွယ်က {remote_size / (1024 * 1024):.1f}MB ပါ။ Video link အနေနဲ့ပို့ပါ။",
            f"Telegram Bot API getFile limit exceeded: {remote_size} bytes",
        )
    if not file_path:
        return fail("Telegram getFile က file path မပြန်ပေးပါ။ Video ကို ပြန်ပို့ကြည့်ပါ။")

    # Never log this URL: it contains the bot token.
    download_url = (
        f"https://api.telegram.org/file/bot{BOT_TOKEN}/"
        f"{quote(file_path.lstrip('/'), safe='/')}"
    )
    downloaded = 0
    last_report = time.monotonic()
    try:
        async with httpx.AsyncClient(timeout=1800.0, follow_redirects=True) as client:
            async with client.stream("GET", download_url) as response:
                status_code = int(getattr(response, "status_code", 0) or 0)
                if status_code >= 400:
                    if known_size > TELEGRAM_BOT_FILE_DOWNLOAD_LIMIT_BYTES or status_code == 400:
                        detail = f"Telegram file download HTTP {status_code}; likely over the 20MB Bot API limit"
                    else:
                        detail = f"Telegram file download HTTP {status_code}"
                    return fail(
                        "Telegram file download မအောင်မြင်ပါ။ File က 20MB ထက်ကြီးရင် link အနေနဲ့ပို့ပါ။",
                        detail,
                    )
                with open(out_path, "wb") as fh:
                    async for chunk in response.aiter_bytes(1024 * 1024):
                        if not chunk:
                            continue
                        fh.write(chunk)
                        downloaded += len(chunk)
                        if tracker and time.monotonic() - last_report >= 4.0:
                            last_report = time.monotonic()
                            await tracker.update(
                                "📥 Telegram video ကို လက်ခံနေပါသည်...\n"
                                f"📦 {downloaded / (1024 * 1024):.1f} MB",
                                force=True,
                            )
    except SourceDownloadError:
        raise
    except Exception as e:
        return fail(
            "Telegram file download ကြားဖြတ်ပျက်သွားပါသည်။ ခဏနေမှ ပြန်ပို့ကြည့်ပါ။",
            f"{type(e).__name__}: {_safe_error_text(e)}",
        )

    if not os.path.exists(out_path) or os.path.getsize(out_path) < 10000:
        size = os.path.getsize(out_path) if os.path.exists(out_path) else 0
        return fail(
            "Telegram က ရလာတဲ့ video file က အလွန်သေး/မပြည့်စုံလို့ ဖတ်မရပါ။ ပြန်ပို့ကြည့်ပါ။",
            f"downloaded Telegram file is only {size} bytes",
        )
    duration = float(probe_video_info(out_path)[0] or 0)
    if duration <= 0:
        return fail(
            "Telegram file ကို download ရသော်လည်း video duration ဖတ်မရပါ။ "
            "File ပျက်နေခြင်း သို့မဟုတ် codec/container မထောက်ပံ့ခြင်း ဖြစ်နိုင်ပါတယ်။ MP4 အဖြစ် ပြန်ပို့ကြည့်ပါ။",
            f"ffprobe/ffmpeg could not read a duration from {os.path.getsize(out_path)} bytes",
        )
    return duration


def _parse_video_info_text(out: str) -> tuple[float, int, int]:
    """Parse duration + *display* dimensions from ``ffmpeg -i`` text.

    The stream line reports coded pixels.  An anamorphic source can
    be stored as 720x480 while displaying at 16:9 (SAR 32:27), and a
    phone video can carry a 90-degree display matrix.  Output sizing
    must use the geometry the viewer actually sees; otherwise the
    render filter crops/scales for the wrong aspect ratio and emits
    non-square pixels that some players handle inconsistently.
    """
    text = str(out or "")
    dur = 0.0
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", text)
    if m:
        dur = float(m.group(1)) * 3600.0 + float(m.group(2)) * 60.0 + float(m.group(3))
    w, h = 0, 0
    vm = re.search(
        r"Stream #\d+:\d+.*?Video:\s*([a-zA-Z0-9_]+).*?,\s*(\d{2,5})x(\d{2,5})",
        text,
    )
    if vm:
        w, h = int(vm.group(2)), int(vm.group(3))
        stream_context = text[vm.start():vm.start() + 700]
        ratio_match = re.search(
            r"\[SAR\s+(\d+):(\d+)\s+DAR\s+(\d+):(\d+)\]",
            stream_context,
        )
        if ratio_match:
            sar_num, sar_den, dar_num, dar_den = (
                int(value) for value in ratio_match.groups()
            )
            if sar_num > 0 and sar_den > 0:
                sar = sar_num / sar_den
                if 0.1 <= sar <= 10.0:
                    w = max(1, int(round(w * sar)))
            elif dar_num > 0 and dar_den > 0 and h > 0:
                dar = dar_num / dar_den
                if 0.1 <= dar <= 10.0:
                    w = max(1, int(round(h * dar)))
        rotation_match = re.search(
            r"rotation of\s+(-?\d+(?:\.\d+)?)\s+degrees",
            text,
            flags=re.IGNORECASE,
        ) or re.search(
            r"\brotate\s*:\s*(-?\d+(?:\.\d+)?)",
            text,
            flags=re.IGNORECASE,
        )
        if rotation_match:
            try:
                rotation = int(round(float(rotation_match.group(1)))) % 360
            except (TypeError, ValueError):
                rotation = 0
            if rotation in (90, 270):
                w, h = h, w
    return dur, w, h


def probe_video_info(path: str) -> tuple[float, int, int]:
    proc = run_cmd([FFMPEG_BIN, "-i", path], 30)
    out = proc.stderr.decode(errors="ignore") + proc.stdout.decode(errors="ignore")
    return _parse_video_info_text(out)


def compute_output_dims(src_w: int, src_h: int, long_edge_target: int = 1280) -> tuple[int, int]:
    if src_w <= 0 or src_h <= 0:
        return 1280, 720
    long_edge = max(src_w, src_h)
    scale = float(long_edge_target) / float(long_edge)
    out_w = max(2, int(round(src_w * scale / 2.0)) * 2)
    out_h = max(2, int(round(src_h * scale / 2.0)) * 2)
    return out_w, out_h


def _yt_dlp_command_prefix() -> list[str]:
    try:
        if importlib.util.find_spec("yt_dlp") is not None:
            return [sys.executable, "-m", "yt_dlp"]
    except Exception:
        pass
    return ["yt-dlp"]


def _installed_yt_dlp_version() -> str:
    try:
        return importlib.metadata.version("yt-dlp")
    except Exception:
        return "unknown"


def _yt_dlp_impersonation_available() -> bool:
    try:
        return importlib.util.find_spec("curl_cffi") is not None
    except Exception:
        return False


def _yt_dlp_base_args(url: str, *, impersonate: bool = False) -> list[str]:
    args = [
        "--no-playlist",
        "--no-warnings",
        "--socket-timeout",
        "30",
        "--retries",
        "3",
        "--fragment-retries",
        "3",
        "--user-agent",
        YTDLP_USER_AGENT,
    ]
    cookies_file = _yt_dlp_cookies_file()
    if cookies_file:
        args.extend(["--cookies", cookies_file])
    if _is_rednote_url(url):
        args.extend(["--referer", "https://www.xiaohongshu.com/"])
    if impersonate and _yt_dlp_impersonation_available():
        args.extend(["--impersonate", "chrome"])
    return args


def _download_error_from_detail(detail: str, url: str = "") -> SourceDownloadError:
    raw_lines = [
        _safe_error_text(line, 700)
        for line in str(detail or "").splitlines()
        if str(line or "").strip()
    ]
    error_lines = [
        line
        for line in raw_lines
        if "error" in line.lower() or "unable" in line.lower() or "failed" in line.lower()
    ]
    concise = (error_lines[-1] if error_lines else (raw_lines[-1] if raw_lines else "unknown download error"))
    concise = re.sub(r"^ERROR:\s*", "", concise, flags=re.IGNORECASE).strip()
    lowered = concise.lower()
    telegram_info = _telegram_link_info(url) if url else None
    if telegram_info and (
        telegram_info.get("kind") != "public_post"
        or "unsupported url" in lowered
        or "no suitable extractor" in lowered
    ):
        telegram_error = _telegram_link_error(url, telegram_info)
        telegram_error.detail = _safe_error_text(
            f"{telegram_error.detail}; extractor rejected the Telegram URL", 2000
        )
        return telegram_error
    if "unsupported url" in lowered or "no suitable extractor" in lowered:
        user_message = (
            "ဒီ link ကို download extractor က မဖတ်နိုင်ပါ။ "
            "Video page link အပြည့်အစုံ သို့မဟုတ် direct video link ကို ပြန်ပို့ကြည့်ပါ။"
        )
    elif any(
        token in lowered
        for token in ("http error 403", "403 forbidden", "forbidden", "captcha", "blocked")
    ):
        user_message = (
            "Website က server download ကို ပိတ်ထားပါတယ် (403/anti-bot)။ "
            "Public link အသစ်ပြန်ကူးပို့ကြည့်ပါ။ RedNote ဆိုရင် cookie လိုအပ်နိုင်ပါတယ်။"
        )
    elif any(
        token in lowered
        for token in (
            "login",
            "sign in",
            "cookies",
            "private",
            "http error 401",
            "unauthorized",
            "authentication",
        )
    ):
        user_message = (
            "ဒီ link က private ဖြစ်နေ၍ဖြစ်စေ login/cookie လိုအပ်၍ဖြစ်စေ download မရပါ။ "
            "Public ဖွင့်ထားတဲ့ link ကို ပြန်ပို့ကြည့်ပါ။"
        )
    elif any(
        token in lowered
        for token in ("requested format is not available", "no video formats", "no formats")
    ):
        user_message = "ဒီ link မှာ download လုပ်နိုင်တဲ့ video format မတွေ့ပါ။"
    elif any(
        token in lowered
        for token in ("timed out", "timeout", "connection", "network", "name resolution", "temporary failure")
    ):
        user_message = "Download server/network ကြောင့် အချိန်ကုန်သွားပါတယ်။ ခဏနေမှ ပြန်ပို့ကြည့်ပါ။"
    elif any(
        token in lowered
        for token in ("http error 404", "not found", "removed", "deleted", "unavailable")
    ):
        user_message = "ဒီ video link က မရှိတော့/ဖျက်ခံရ/သက်တမ်းကုန်နေပါတယ်။ Link အသစ်ပြန်ကူးပို့ပါ။"
    else:
        user_message = "မူရင်းဗီဒီယို download မရပါ။"
    return SourceDownloadError(user_message, detail=concise, user_message=user_message)


async def _resolve_source_url(url: str) -> str:
    original = _extract_first_url(url) or str(url or "").strip()
    if not original.startswith(("http://", "https://")):
        return original
    host = _url_hostname(original)
    should_resolve = _is_rednote_url(original) or host in {
        "bit.ly",
        "t.co",
        "tinyurl.com",
        "shorturl.at",
    }
    if not should_resolve:
        return original
    try:
        cookies = _rednote_httpx_cookies() if _is_rednote_url(original) else None
        async with httpx.AsyncClient(
            timeout=30.0,
            follow_redirects=True,
            headers=_source_browser_headers(original),
            cookies=cookies,
        ) as client:
            async with client.stream("GET", original) as response:
                resolved = str(response.url or original)
        return resolved or original
    except Exception as e:
        logger.warning(
            "source URL resolve failed for host=%s: %s",
            host or "unknown",
            _safe_error_text(e),
        )
        return original


def _source_url_candidates(original: str, resolved: str) -> list[str]:
    candidates: list[str] = []

    def add(value: str):
        clean = _extract_first_url(value) or str(value or "").strip()
        if clean.startswith(("http://", "https://")) and clean not in candidates:
            candidates.append(clean)

    add(resolved)
    add(original)
    for value in list(candidates):
        parsed = urlparse(value)
        host = (parsed.hostname or "").lower()
        if host == "rednote.com" or host.endswith(".rednote.com"):
            add(parsed._replace(netloc="www.xiaohongshu.com").geturl())
    return candidates


def _extract_direct_video_urls_from_text(text: str, base_url: str = "") -> list[str]:
    raw = html.unescape(str(text or ""))
    raw = raw.replace("\\/", "/")
    raw = re.sub(r"\\u002[fF]", "/", raw)
    raw = re.sub(r"\\u0026", "&", raw)
    candidates: list[str] = []

    def add(value: str):
        clean = str(value or "").strip().strip("\"'")
        if not clean:
            return
        clean = urljoin(base_url or "", clean)
        if clean.startswith(("http://", "https://")) and clean not in candidates:
            candidates.append(clean)

    for match in re.finditer(
        r"(?:masterUrl|master_url|videoUrl|video_url|playUrl|play_url)"
        r"[\"']?\s*[:=]\s*[\"']([^\"']+)",
        raw,
        re.IGNORECASE,
    ):
        add(match.group(1))
    for match in re.finditer(
        r"originVideoKey[\"']?\s*[:=]\s*[\"']([^\"']+)", raw, re.IGNORECASE
    ):
        key = str(match.group(1) or "").lstrip("/")
        if key:
            add(f"https://sns-video-bd.xhscdn.com/{key}")
    media_suffixes = tuple(TELEGRAM_VIDEO_EXTENSIONS) + (".m3u8",)
    for match in re.finditer(r"https?://[^\s\"'<>\\]+", raw, re.IGNORECASE):
        value = match.group(0).rstrip("),.;")
        path = (urlparse(value).path or "").lower()
        if path.endswith(media_suffixes) or "sns-video" in value.lower():
            add(value)
    return candidates[:10]


async def _extract_rednote_direct_urls(url: str) -> list[str]:
    if not _is_rednote_url(url):
        return []
    try:
        async with httpx.AsyncClient(
            timeout=60.0,
            follow_redirects=True,
            headers=_source_browser_headers(url),
            cookies=_rednote_httpx_cookies(),
        ) as client:
            async with client.stream("GET", url) as response:
                if int(getattr(response, "status_code", 0) or 0) >= 400:
                    logger.warning(
                        "RedNote page fallback HTTP %s host=%s",
                        response.status_code,
                        _url_hostname(url),
                    )
                    return []
                final_url = str(response.url or url)
                content_type = str(response.headers.get("content-type") or "").lower()
                if content_type.startswith("video/"):
                    return [final_url]
                chunks: list[bytes] = []
                total = 0
                async for chunk in response.aiter_bytes(1024 * 256):
                    if not chunk:
                        continue
                    chunks.append(chunk)
                    total += len(chunk)
                    if total >= 4 * 1024 * 1024:
                        break
        text = b"".join(chunks).decode(errors="ignore")
        return _extract_direct_video_urls_from_text(text, final_url)
    except Exception as e:
        logger.warning(
            "RedNote direct URL extraction failed host=%s: %s",
            _url_hostname(url),
            _safe_error_text(e),
        )
        return []



def _extract_telegram_video_urls_from_html(text: str, base_url: str = "") -> list[str]:
    """Find direct video URLs in a Telegram public-post web preview."""
    candidates: list[str] = []

    def add(value: str):
        clean = html.unescape(str(value or "")).strip().strip("\"'")
        clean = clean.replace("\\/", "/")
        clean = re.sub(r"\\u002[fF]", "/", clean)
        clean = re.sub(r"\\u0026", "&", clean)
        if not clean:
            return
        clean = urljoin(base_url or "", clean)
        if not clean.startswith(("http://", "https://")):
            return
        path = (urlparse(clean).path or "").lower()
        if path.endswith((".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg")):
            return
        if clean not in candidates:
            candidates.append(clean)

    raw = html.unescape(str(text or ""))
    attribute_patterns = (
        # <video src="..."> and <source src="..."> in t.me embeds.
        r"<video\b[^>]*\bsrc\s*=\s*[\"']([^\"']+)[\"']",
        r"<source\b[^>]*\bsrc\s*=\s*[\"']([^\"']+)[\"']",
        # Open Graph / Twitter player metadata; attributes may be reversed.
        r"<meta\b[^>]*(?:property|name)\s*=\s*[\"'](?:og:video(?::secure_url)?|twitter:player:stream)[\"'][^>]*\bcontent\s*=\s*[\"']([^\"']+)[\"']",
        r"<meta\b[^>]*\bcontent\s*=\s*[\"']([^\"']+)[\"'][^>]*(?:property|name)\s*=\s*[\"'](?:og:video(?::secure_url)?|twitter:player:stream)[\"']",
        # Telegram widget variants sometimes carry the media in data attrs.
        r"\bdata-(?:video|src|url)\s*=\s*[\"']([^\"']+)[\"']",
    )
    for pattern in attribute_patterns:
        for match in re.finditer(pattern, raw, re.IGNORECASE):
            add(match.group(1))

    # Reuse the generic JSON/direct-media scanner for escaped CDN URLs and
    # .m3u8/.mp4 values embedded in inline scripts.
    for candidate in _extract_direct_video_urls_from_text(raw, base_url):
        add(candidate)
    return candidates[:10]


def _telegram_public_post_page_urls(url: str, info: dict | None = None) -> list[str]:
    clean = _extract_first_url(url) or str(url or "").strip()
    info = info or _telegram_link_info(clean) or {}
    if info.get("kind") != "public_post":
        return []
    parsed = urlparse(clean)
    pages: list[str] = []

    def add(value: str):
        if value and value not in pages:
            pages.append(value)

    add(clean)
    add(parsed._replace(query="embed=1&mode=tme", fragment="").geturl())
    segments = [str(item) for item in (info.get("segments") or []) if str(item)]
    if segments and segments[0].lower() != "s":
        add("https://t.me/s/" + "/".join(segments))
    return pages


async def _extract_telegram_direct_urls(url: str) -> list[str]:
    info = _telegram_link_info(url)
    if not info or info.get("kind") != "public_post":
        return []
    candidates: list[str] = []
    try:
        async with httpx.AsyncClient(
            timeout=60.0,
            follow_redirects=True,
            headers=_source_browser_headers(url),
        ) as client:
            for page_url in _telegram_public_post_page_urls(url, info):
                try:
                    async with client.stream("GET", page_url) as response:
                        if int(getattr(response, "status_code", 0) or 0) >= 400:
                            logger.warning(
                                "Telegram public post fallback HTTP %s",
                                response.status_code,
                            )
                            continue
                        final_url = str(response.url or page_url)
                        content_type = str(
                            response.headers.get("content-type") or ""
                        ).lower()
                        if content_type.startswith("video/"):
                            if final_url not in candidates:
                                candidates.append(final_url)
                            continue
                        chunks: list[bytes] = []
                        total = 0
                        async for chunk in response.aiter_bytes(1024 * 256):
                            if not chunk:
                                continue
                            chunks.append(chunk)
                            total += len(chunk)
                            if total >= 4 * 1024 * 1024:
                                break
                    text = b"".join(chunks).decode(errors="ignore")
                    for candidate in _extract_telegram_video_urls_from_html(
                        text, final_url
                    ):
                        if candidate not in candidates:
                            candidates.append(candidate)
                    if candidates:
                        break
                except Exception as e:
                    logger.warning(
                        "Telegram public post page extraction failed: %s",
                        _safe_error_text(e),
                    )
                    continue
    except Exception as e:
        logger.warning(
            "Telegram direct URL extraction failed: %s",
            _safe_error_text(e),
        )
        return []
    return candidates[:10]


async def _download_direct_media(
    url: str,
    out_path: str,
    tracker=None,
    total_dur: float = 0,
    *,
    referer: str = "",
) -> float:
    clean_url = _extract_first_url(url) or str(url or "").strip()
    path = (urlparse(clean_url).path or "").lower()
    if path.endswith(".m3u8"):
        raise SourceDownloadError(
            "HLS playlist ကို yt-dlp ဖြင့် download လုပ်ရန် လိုအပ်ပါတယ်။",
            detail="direct downloader does not handle .m3u8 playlists",
        )
    downloaded = 0
    last_report = time.monotonic()
    content_type = ""
    try:
        cookies = _rednote_httpx_cookies() if _is_rednote_url(clean_url) else None
        async with httpx.AsyncClient(
            timeout=1800.0,
            follow_redirects=True,
            headers=_source_browser_headers(clean_url, referer=referer),
            cookies=cookies,
        ) as client:
            async with client.stream("GET", clean_url) as response:
                status_code = int(getattr(response, "status_code", 0) or 0)
                if status_code >= 400:
                    raise _download_error_from_detail(
                        f"HTTP Error {status_code} while downloading direct media",
                        clean_url,
                    )
                content_type = str(response.headers.get("content-type") or "").lower()
                is_known_media = bool(
                    content_type.startswith("video/")
                    or "octet-stream" in content_type
                    or _is_direct_media_url(clean_url)
                    or "sns-video" in clean_url.lower()
                )
                if content_type and not is_known_media:
                    raise SourceDownloadError(
                        "Link က video file မဟုတ်ဘဲ web page ပြန်ပေးနေပါတယ်။",
                        detail=f"direct URL returned content-type {content_type}",
                    )
                try:
                    content_length = int(response.headers.get("content-length") or 0)
                except (TypeError, ValueError):
                    content_length = 0
                with open(out_path, "wb") as fh:
                    async for chunk in response.aiter_bytes(1024 * 1024):
                        if not chunk:
                            continue
                        fh.write(chunk)
                        downloaded += len(chunk)
                        if tracker and time.monotonic() - last_report >= 4.0:
                            last_report = time.monotonic()
                            pct = (
                                min(95, int(downloaded * 100 / content_length))
                                if content_length > downloaded
                                else min(95, int(downloaded / (10 * 1024 * 1024)))
                            )
                            await tracker.update(
                                "📥 မူရင်းဗီဒီယို ဒေါင်းနေသည်...\n"
                                f"📦 {downloaded / (1024 * 1024):.0f} MB\n"
                                f"📊 {fmt_progress_bar(pct)}",
                                force=True,
                            )
    except SourceDownloadError:
        raise
    except Exception as e:
        raise _download_error_from_detail(
            f"{type(e).__name__}: {_safe_error_text(e)}", clean_url
        ) from e

    if not os.path.exists(out_path) or os.path.getsize(out_path) < 10000:
        size = os.path.getsize(out_path) if os.path.exists(out_path) else 0
        raise SourceDownloadError(
            "Direct video download က မပြည့်စုံပါ။",
            detail=f"direct download produced only {size} bytes; content-type={content_type}",
        )
    duration = float(probe_video_info(out_path)[0] or 0)
    if duration <= 0:
        raise SourceDownloadError(
            "Download ရလာတဲ့ file ကို video အဖြစ် ဖတ်မရပါ။",
            detail=(
                f"direct download produced unreadable media "
                f"({os.path.getsize(out_path)} bytes, content-type={content_type})"
            ),
        )
    return duration


async def _read_stream_tail(stream, max_bytes: int = 65536) -> bytes:
    if stream is None:
        return b""
    buffer = bytearray()
    while True:
        chunk = await stream.read(8192)
        if not chunk:
            break
        buffer.extend(chunk)
        if len(buffer) > max_bytes:
            del buffer[: len(buffer) - max_bytes]
    return bytes(buffer)


async def _run_ytdlp_info(url: str, *, impersonate: bool = False) -> dict:
    cmd = [*_yt_dlp_command_prefix(), *_yt_dlp_base_args(url, impersonate=impersonate), "-j", url]
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            start_new_session=True,
        )
    except FileNotFoundError as e:
        raise SourceDownloadError(
            "yt-dlp downloader မတွေ့ပါ။",
            detail="yt-dlp executable is not installed",
        ) from e
    try:
        out, err = await asyncio.wait_for(proc.communicate(), timeout=120.0)
    except asyncio.TimeoutError:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
        raise _download_error_from_detail("yt-dlp info timed out", url) from None
    stdout_text = (out or b"").decode(errors="ignore")
    stderr_text = (err or b"").decode(errors="ignore")
    if proc.returncode != 0:
        raise _download_error_from_detail(stderr_text or stdout_text, url)
    for line in stdout_text.splitlines():
        clean = line.strip()
        if not clean.startswith("{"):
            continue
        try:
            data = json.loads(clean)
        except Exception:
            continue
        if isinstance(data, dict):
            return data
    raise SourceDownloadError(
        "Video အချက်အလက်ကို yt-dlp က မပြန်ပေးပါ။",
        detail=_safe_error_text(stderr_text or stdout_text[-1000:]),
    )


def _duration_from_ytdlp_info(data: dict) -> float:
    candidates = [data] if isinstance(data, dict) else []
    entries = data.get("entries") if isinstance(data, dict) else []
    if isinstance(entries, list):
        candidates.extend(item for item in entries if isinstance(item, dict))
    for item in candidates:
        try:
            duration = float(item.get("duration") or 0)
        except (TypeError, ValueError):
            duration = 0.0
        if duration > 0:
            return duration
        formats = item.get("formats") or []
        format_durations = []
        if isinstance(formats, list):
            for fmt in formats:
                if not isinstance(fmt, dict):
                    continue
                try:
                    value = float(fmt.get("duration") or 0)
                except (TypeError, ValueError):
                    value = 0.0
                if value > 0:
                    format_durations.append(value)
        if format_durations:
            return max(format_durations)
    return 0.0


async def get_source_duration(url: str, *, raise_on_error: bool = False) -> float:
    original = _extract_first_url(url) or str(url or "").strip()
    if not original.startswith(("http://", "https://")):
        error = SourceDownloadError(
            "Video link မမှန်ပါ။ http/https link အပြည့်အစုံ ပို့ပါ။",
            detail="source URL is empty or not http/https",
        )
        if raise_on_error:
            raise error
        return 0.0
    telegram_info = _telegram_link_info(original)
    if telegram_info:
        if telegram_info.get("kind") != "public_post":
            error = _telegram_link_error(original, telegram_info)
            logger.warning(
                "get_source_duration skipped Telegram %s URL: %s",
                telegram_info.get("kind"),
                error.detail,
            )
            if raise_on_error:
                raise error
        return 0.0
    resolved = await _resolve_source_url(original)
    candidates = _source_url_candidates(original, resolved)
    attempts: list[tuple[str, bool]] = [(item, False) for item in candidates]
    if candidates and _is_rednote_url(candidates[0]) and _yt_dlp_impersonation_available():
        attempts.append((candidates[0], True))
    errors: list[SourceDownloadError] = []
    for candidate, impersonate in attempts:
        try:
            info = await _run_ytdlp_info(candidate, impersonate=impersonate)
            duration = _duration_from_ytdlp_info(info)
            if duration > 0:
                return duration
            errors.append(
                SourceDownloadError(
                    "Video duration ကို link က မရပါ။",
                    detail="yt-dlp info did not include a duration",
                )
            )
        except SourceDownloadError as e:
            errors.append(e)
        except Exception as e:
            errors.append(
                _download_error_from_detail(
                    f"{type(e).__name__}: {_safe_error_text(e)}", candidate
                )
            )
    if errors:
        logger.warning(
            "get_source_duration failed host=%s: %s",
            _url_hostname(original),
            errors[0].detail,
        )
        if raise_on_error:
            raise errors[0]
    return 0.0


def _normalize_downloaded_video(produced_path: str, out_path: str) -> bool:
    if os.path.abspath(produced_path) == os.path.abspath(out_path):
        return os.path.exists(out_path)
    parent = os.path.dirname(os.path.abspath(out_path))
    os.makedirs(parent, exist_ok=True)
    if os.path.exists(out_path):
        try:
            os.remove(out_path)
        except Exception:
            pass
    result = run_cmd(
        [
            FFMPEG_BIN,
            "-y",
            "-i",
            produced_path,
            "-c",
            "copy",
            "-movflags",
            "+faststart",
            out_path,
        ],
        1200,
    )
    if result.returncode == 0 and os.path.exists(out_path) and os.path.getsize(out_path) > 0:
        try:
            os.remove(produced_path)
        except Exception:
            pass
        return True
    try:
        if os.path.exists(out_path):
            os.remove(out_path)
        shutil.move(produced_path, out_path)
        return bool(os.path.exists(out_path) and os.path.getsize(out_path) > 0)
    except Exception:
        return False


async def _download_with_ytdlp_once(
    url: str,
    out_path: str,
    tracker=None,
    total_dur: float = 0,
    *,
    format_selector: str = "bestvideo[height<=720]+bestaudio/best[height<=720]",
    impersonate: bool = False,
) -> float:
    out_dir = os.path.dirname(os.path.abspath(out_path))
    os.makedirs(out_dir, exist_ok=True)
    filename = os.path.basename(out_path) or "source.mp4"
    stem = os.path.splitext(filename)[0] or "source"
    download_prefix = f"{stem}_download."
    template = os.path.join(out_dir, f"{stem}_download.%(ext)s")

    def current_files() -> list[str]:
        try:
            names = os.listdir(out_dir)
        except Exception:
            return []
        paths = []
        for name in names:
            if not name.startswith(download_prefix):
                continue
            path = os.path.join(out_dir, name)
            try:
                if os.path.isfile(path) and os.path.getsize(path) > 0:
                    paths.append(path)
            except Exception:
                continue
        return sorted(paths, key=lambda p: os.path.getsize(p), reverse=True)

    def cleanup_files(except_path: str = ""):
        for path in current_files():
            if except_path and os.path.abspath(path) == os.path.abspath(except_path):
                continue
            try:
                os.remove(path)
            except Exception:
                pass

    cleanup_files()
    if os.path.exists(out_path):
        try:
            os.remove(out_path)
        except Exception:
            pass

    cmd = [
        *_yt_dlp_command_prefix(),
        *_yt_dlp_base_args(url, impersonate=impersonate),
        "--no-part",
        "-f",
        format_selector,
        "--merge-output-format",
        "mp4",
        "-o",
        template,
        url,
    ]
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            start_new_session=True,
        )
    except FileNotFoundError as e:
        raise SourceDownloadError(
            "yt-dlp downloader မတွေ့ပါ။",
            detail="yt-dlp executable is not installed",
        ) from e
    stdout_task = asyncio.create_task(_read_stream_tail(proc.stdout))
    stderr_task = asyncio.create_task(_read_stream_tail(proc.stderr))
    started = time.monotonic()
    last_report = started
    try:
        while True:
            try:
                await asyncio.wait_for(proc.wait(), timeout=3.0)
                break
            except asyncio.TimeoutError:
                if time.monotonic() - started > SOURCE_DOWNLOAD_TIMEOUT_SECONDS:
                    raise _download_error_from_detail(
                        "yt-dlp download timed out", url
                    ) from None
                if tracker and time.monotonic() - last_report >= 4.0:
                    last_report = time.monotonic()
                    files = current_files()
                    mb = (
                        os.path.getsize(files[0]) / (1024 * 1024)
                        if files
                        else 0.0
                    )
                    if total_dur > 0:
                        pct = min(95, int((mb / max(1, total_dur)) * 100 / 4))
                    else:
                        pct = min(95, int(mb / 10))
                    await tracker.update(
                        "📥 မူရင်းဗီဒီယို ဒေါင်းနေသည်...\n"
                        f"📦 {mb:.0f} MB\n"
                        f"📊 {fmt_progress_bar(pct)}",
                        force=True,
                    )
    except BaseException:
        if proc.returncode is None:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass
        stdout_task.cancel()
        stderr_task.cancel()
        raise
    stdout_tail, stderr_tail = await asyncio.gather(stdout_task, stderr_task)
    combined_output = (
        (stderr_tail or b"").decode(errors="ignore")
        + "\n"
        + (stdout_tail or b"").decode(errors="ignore")
    )
    files = current_files()
    if proc.returncode != 0 or not files:
        cleanup_files()
        raise _download_error_from_detail(combined_output, url)

    produced = files[0]
    normalized = await asyncio.to_thread(
        _normalize_downloaded_video, produced, out_path
    )
    cleanup_files(except_path=out_path)
    if not normalized or not os.path.exists(out_path) or os.path.getsize(out_path) < 10000:
        size = os.path.getsize(out_path) if os.path.exists(out_path) else 0
        detail = _safe_error_text(combined_output[-1000:])
        raise SourceDownloadError(
            "Download ရလာတဲ့ video file က မပြည့်စုံ/ဖတ်မရပါ။",
            detail=f"yt-dlp produced {size} bytes. {detail}",
        )
    actual_dur = float(probe_video_info(out_path)[0] or 0)
    if actual_dur <= 0:
        raise SourceDownloadError(
            "Download ရလာတဲ့ file ကို video အဖြစ် ဖတ်မရပါ။",
            detail=(
                f"yt-dlp output was {os.path.getsize(out_path)} bytes but "
                "ffmpeg could not read a video duration"
            ),
        )
    return actual_dur


async def download_full(
    url: str,
    out_path: str,
    tracker=None,
    total_dur: float = 0,
    *,
    raise_on_error: bool = False,
) -> float:
    original = _extract_first_url(url) or str(url or "").strip()
    if not original.startswith(("http://", "https://")):
        error = SourceDownloadError(
            "Video link မမှန်ပါ။ http/https link အပြည့်အစုံ ပို့ပါ။",
            detail="source URL is empty or not http/https",
        )
        if raise_on_error:
            raise error
        return 0.0

    telegram_info = _telegram_link_info(original)
    if telegram_info:
        if telegram_info.get("kind") != "public_post":
            error = _telegram_link_error(original, telegram_info)
            logger.warning(
                "download_full rejected Telegram %s URL: %s",
                telegram_info.get("kind"),
                error.detail,
            )
            if raise_on_error:
                raise error
            return 0.0

        telegram_errors: list[SourceDownloadError] = []
        direct_urls = await _extract_telegram_direct_urls(original)
        for direct_url in direct_urls[:5]:
            try:
                direct_path = (urlparse(direct_url).path or "").lower()
                if direct_path.endswith(".m3u8"):
                    return await _download_with_ytdlp_once(
                        direct_url,
                        out_path,
                        tracker,
                        total_dur,
                        format_selector="best",
                    )
                return await _download_direct_media(
                    direct_url,
                    out_path,
                    tracker,
                    total_dur,
                    referer=original,
                )
            except SourceDownloadError as e:
                telegram_errors.append(e)
                logger.warning(
                    "Telegram public post direct fallback failed host=%s: %s",
                    _url_hostname(direct_url),
                    e.detail,
                )

        # One best-effort yt-dlp attempt keeps this useful if a future
        # extractor/webpage change makes the post downloadable there.
        try:
            return await _download_with_ytdlp_once(
                original,
                out_path,
                tracker,
                total_dur,
                format_selector="best",
            )
        except SourceDownloadError as e:
            telegram_errors.append(e)
            logger.warning(
                "Telegram public post yt-dlp fallback failed: %s", e.detail
            )

        error = _telegram_link_error(original, telegram_info)
        if telegram_errors:
            error.detail = _safe_error_text(
                f"{error.detail}; fallback detail: {telegram_errors[0].detail}",
                2000,
            )
        logger.warning("download_full failed for Telegram public post: %s", error.detail)
        if raise_on_error:
            raise error
        return 0.0

    resolved = await _resolve_source_url(original)
    candidates = _source_url_candidates(original, resolved)
    direct_errors: list[SourceDownloadError] = []
    ytdlp_errors: list[SourceDownloadError] = []
    fallback_errors: list[SourceDownloadError] = []

    # A direct media/CDN URL is often faster and more reliable than asking
    # yt-dlp's generic extractor to rediscover the same URL.
    for candidate in candidates:
        candidate_path = (urlparse(candidate).path or "").lower()
        if _is_direct_media_url(candidate) and not candidate_path.endswith(".m3u8"):
            try:
                return await _download_direct_media(
                    candidate, out_path, tracker, total_dur
                )
            except SourceDownloadError as e:
                direct_errors.append(e)
                logger.warning(
                    "direct media download failed host=%s: %s",
                    _url_hostname(candidate),
                    e.detail,
                )

    selectors = [
        "bestvideo[height<=720]+bestaudio/best[height<=720]",
        "best[height<=720]/best",
        "best",
    ]
    attempts: list[tuple[str, str, bool]] = []
    if candidates:
        for selector in selectors:
            attempts.append((candidates[0], selector, False))
        for candidate in candidates[1:]:
            attempts.append((candidate, selectors[0], False))
            attempts.append((candidate, "best", False))
        if _is_rednote_url(candidates[0]) and _yt_dlp_impersonation_available():
            attempts.append((candidates[0], selectors[0], True))
            attempts.append((candidates[0], "best", True))

    for candidate, selector, impersonate in attempts:
        try:
            return await _download_with_ytdlp_once(
                candidate,
                out_path,
                tracker,
                total_dur,
                format_selector=selector,
                impersonate=impersonate,
            )
        except SourceDownloadError as e:
            ytdlp_errors.append(e)
            logger.warning(
                "yt-dlp download failed host=%s selector=%s impersonate=%s: %s",
                _url_hostname(candidate),
                selector,
                impersonate,
                e.detail,
            )

    # Last RedNote fallback: the page's initial state normally contains
    # masterUrl/backupUrls/originVideoKey.  Parsing those direct CDN URLs
    # can still work when the extractor or an anti-bot layer fails.
    if any(_is_rednote_url(candidate) for candidate in candidates):
        for candidate in candidates:
            direct_urls = await _extract_rednote_direct_urls(candidate)
            for direct_url in direct_urls[:5]:
                try:
                    direct_path = (urlparse(direct_url).path or "").lower()
                    if direct_path.endswith(".m3u8") or not _is_direct_media_url(direct_url):
                        return await _download_with_ytdlp_once(
                            direct_url,
                            out_path,
                            tracker,
                            total_dur,
                            format_selector="best",
                        )
                    return await _download_direct_media(
                        direct_url,
                        out_path,
                        tracker,
                        total_dur,
                        referer=candidate,
                    )
                except SourceDownloadError as e:
                    fallback_errors.append(e)
                    logger.warning(
                        "RedNote direct fallback failed host=%s: %s",
                        _url_hostname(direct_url),
                        e.detail,
                    )

    error = (
        ytdlp_errors[0]
        if ytdlp_errors
        else (
            direct_errors[0]
            if direct_errors
            else (
                fallback_errors[0]
                if fallback_errors
                else SourceDownloadError(
                    "မူရင်းဗီဒီယို download မရပါ။",
                    detail="all source download attempts failed without a detailed error",
                )
            )
        )
    )
    logger.warning(
        "download_full failed host=%s: %s",
        _url_hostname(original),
        error.detail,
    )
    if raise_on_error:
        raise error
    return 0.0


def build_source_segment_plan(
    total_duration: float,
    segment_seconds: float = SOURCE_SEGMENT_SECONDS,
) -> list[dict]:
    """Build non-overlapping two-minute windows for any source duration."""
    try:
        duration = float(total_duration or 0)
    except (TypeError, ValueError):
        return []
    if duration <= 0:
        return []
    step = max(1.0, float(segment_seconds or SOURCE_SEGMENT_SECONDS))
    count = max(1, int(math.ceil(duration / step - 1e-9)))
    plan = []
    for index in range(count):
        start = index * step
        end = min(duration, start + step)
        if end - start <= 0.01:
            continue
        plan.append(
            {
                "index": len(plan) + 1,
                "start": round(start, 3),
                "end": round(end, 3),
                "duration": round(end - start, 3),
            }
        )
    return plan


def split_pcm_by_weights(master: np.ndarray, scenes: list) -> list[np.ndarray]:
    if len(scenes) == 0:
        return []
    if len(scenes) == 1 or len(master) < SAMPLE_RATE:
        return [master]

    weights = np.array([max(5, len(s.get("burmese", ""))) for s in scenes], dtype=np.float64)
    cum_ratios = np.cumsum(weights)[:-1] / np.sum(weights)

    hop = int(0.02 * SAMPLE_RATE)
    n_frames = max(1, (len(master) - hop) // hop)
    rms = np.array([
        float(np.sqrt(np.mean(master[i * hop:i * hop + hop] ** 2)))
        for i in range(n_frames)
    ])

    cuts = [0]
    for r in cum_ratios:
        expected = int(r * n_frames)
        win = max(25, int(0.15 * n_frames))
        lo = max(cuts[-1] // hop + 10, expected - win)
        hi = min(n_frames - 10, expected + win)
        if hi <= lo:
            best = max(cuts[-1] // hop + 1, expected)
        else:
            dists = np.abs(np.arange(lo, hi) - expected) / max(1.0, float(win))
            score = rms[lo:hi] + 0.015 * dists
            best = lo + int(np.argmin(score))
        cuts.append(min(len(master), best * hop))
    cuts.append(len(master))

    clips = []
    for i in range(len(scenes)):
        seg = master[cuts[i]:cuts[i + 1]].copy()
        if len(seg) < 200:
            seg = np.zeros(int(0.5 * SAMPLE_RATE), dtype=np.float32)
        clips.append(seg)
    return clips


def build_voice_filter(settings: dict = None) -> str:
    """Per-clip TTS filter (deep voice colour / speed).

    No loudnorm and no volume here (v5.14): single-pass loudnorm on
    every few-second scene clip normalizes each sentence on its
    own, so loudness jumps and wobbles from scene to scene -- a
    real cause of "the speech keeps breaking".  Loudness is
    normalized once on the assembled master narration instead
    (build_master_voice_filter).  Speed stays per-clip because
    duration calibration measures these very clips.
    """
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    parts = []
    if s.get("deep"):
        parts.append(DEEP_VOICE_FILTER)
    speed = float(s.get("speed") or 1.0)
    if abs(speed - 1.0) > 0.01:
        parts.append(f"atempo={speed:.3f}")
    return ",".join(parts) if parts else "anull"


def build_master_voice_filter(settings: dict = None) -> str:
    """One loudness pass over the whole assembled narration track.

    Applied where the per-scene clips become one master WAV (direct
    renderer and worker TTS stage).  User volume is applied after
    loudnorm here, preserving the pre-v5.14 chain order.
    """
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    base = MASTER_LOUDNORM_FILTER
    vol = float(s.get("volume") or 100) / 100.0
    if abs(vol - 1.0) > 0.01:
        base += f",volume={vol:.2f}"
    return base


def _tts_speech_config(voice_name: str, shape: str = "voice"):
    """Build the TTS speech config.

    Current Gemini TTS models (gemini-3.8-flash-tts and friends)
    document ``voice_config: {"voice": "Charon"}``; the older
    preview models used ``prebuilt_voice_config.voice_name``.
    Sending the shape a model does not accept fails every request
    with 400 -- observed in production as 100% silent scenes -- so
    callers alternate shapes across attempts and whichever shape a
    model accepts wins within the first two attempts.
    """
    if shape == "prebuilt":
        return types.SpeechConfig(
            voice_config=types.VoiceConfig(
                prebuilt_voice_config=types.PrebuiltVoiceConfig(
                    voice_name=voice_name
                )
            )
        )
    return types.SpeechConfig(
        voice_config=types.VoiceConfig(voice=voice_name)
    )


async def _audio_file_to_master(tmp_raw, tmp_pcm, voice_filter, input_args):
    """Decode a synthesized audio file into one float master array.

    ``input_args`` are extra ffmpeg *input* flags (empty when the
    file has a sniffable container like WAV/MP3, raw s16le flags for
    headerless PCM).  Raises RuntimeError on any decode problem.
    """
    # to_thread: a blocking ffmpeg call here would stall the event
    # loop (progress edits, keep-alive, parallel batches).
    result = await asyncio.to_thread(run_cmd, [
        FFMPEG_BIN, "-y",
        *input_args,
        "-i", tmp_raw,
        "-af", voice_filter,
        "-f", "s16le", "-acodec", "pcm_s16le",
        "-ac", "1", "-ar", str(SAMPLE_RATE),
        tmp_pcm,
    ], 180)
    if result.returncode != 0 or not os.path.exists(tmp_pcm):
        raise RuntimeError("ffmpeg convert failed")
    if os.path.getsize(tmp_pcm) < 400:
        raise RuntimeError("pcm too small")
    return np.fromfile(tmp_pcm, dtype=np.int16).astype(np.float32) / 32768.0


CLIP_TRIM_THRESHOLD = 0.002       # ~-54 dBFS: below this is dead air
CLIP_HEAD_PAD_SECONDS = 0.03      # speech safety margin kept at starts
CLIP_TAIL_PAD_SECONDS = 0.08      # natural decay kept at ends
CLIP_FADE_SECONDS = 0.006         # click-free clip joins


def _polish_clip(clip) -> np.ndarray:
    """Trim dead air at a scene clip's edges and add micro-fades.

    Every scene is its own synthesized file (per-scene Edge MP3 /
    sliced Gemini batch): the service prepends/appends a little
    silence and MP3 priming can add more.  Butt-joining those raw
    clips -- on top of the configured inter-scene pause -- made
    the narration stop-start every few seconds ("speech keeps
    breaking", user report).  Trimming to the actual speech with
    small safety pads leaves the configured pause as the only gap,
    and 6ms fades keep every join click-free.  All-silent clips
    (explicit silence fallbacks) pass through unchanged so the
    duration/silence gates still see them.
    """
    arr = _clip_array(clip)
    if arr.size == 0:
        return arr
    above = np.where(np.abs(arr) > CLIP_TRIM_THRESHOLD)[0]
    if above.size == 0:
        return arr
    head = int(CLIP_HEAD_PAD_SECONDS * SAMPLE_RATE)
    tail = int(CLIP_TAIL_PAD_SECONDS * SAMPLE_RATE)
    start = max(0, int(above[0]) - head)
    end = min(arr.size, int(above[-1]) + 1 + tail)
    out = np.array(arr[start:end], dtype=np.float32, copy=True)
    fade = min(int(CLIP_FADE_SECONDS * SAMPLE_RATE), out.size // 2)
    if fade > 0:
        ramp = np.linspace(0.0, 1.0, fade, endpoint=False, dtype=np.float32)
        out[:fade] *= ramp
        out[-fade:] *= ramp[::-1]
    return out


def _validate_scene_clip(clip, text: str) -> None:
    """Reject silent or grossly wrong-length scene audio (retry it).

    A decodable file is not proof of complete speech: an
    interrupted Edge stream can end mid-word yet decode cleanly,
    and the old >=400-byte check waved it through -- heard as
    cut-off speech in the final video.  Bounds must stay well
    clear of the voice's real speed: my-MM-ThihaNeural measures
    ~14-17 chars/second in production, and the previous
    chars/16 floor falsely rejected complete fast clips as
    "truncated" (313 chars in 18.65s), burning retries and
    turning good scenes into silence.  chars/26 only rejects
    clips missing a large share of their speech.
    """
    arr = _clip_array(clip)
    if _clip_is_silent(arr):
        raise RuntimeError("synthesized clip is silent")
    chars = max(1, len(str(text or "").strip()))
    seconds = float(arr.size) / SAMPLE_RATE
    min_seconds = max(0.30, chars / 26.0)
    max_seconds = chars / 1.7 + 3.5
    if seconds < min_seconds:
        raise RuntimeError(
            f"synthesized clip too short for {chars} chars: "
            f"{seconds:.2f}s < {min_seconds:.2f}s (truncated?)"
        )
    if seconds > max_seconds:
        raise RuntimeError(
            f"synthesized clip too long for {chars} chars: "
            f"{seconds:.2f}s > {max_seconds:.2f}s"
        )


# Burmese (my-MM) Microsoft Edge neural voices.  The Edge provider
# always speaks with Thiha (user rule); Nilar is kept only as a
# named constant for possible future opt-in use.
EDGE_TTS_VOICE_MALE = "my-MM-ThihaNeural"
EDGE_TTS_VOICE_FEMALE = "my-MM-NilarNeural"

# Edge TTS reliability.  The free Microsoft voice is the only working TTS
# in production (the free Gemini TTS plan quota is exhausted), and a
# Microsoft-side blip used to turn into "3/5 silent scenes" and a failed
# part within seconds.  Each scene now gets several spaced attempts, a
# failed scene is re-requested sentence by sentence (a long request that
# keeps failing usually works when broken up, and nothing is lost), a
# batch that is failing wholesale stops early instead of grinding through
# every scene, and synthesize_tts re-synthesizes any leftover silent scene
# in a fresh pass before anything is accepted.
EDGE_TTS_SCENE_ATTEMPTS = 4
EDGE_TTS_RETRY_DELAYS = (0.6, 1.5, 3.0)
EDGE_TTS_PIECE_ATTEMPTS = 2
EDGE_TTS_PIECE_DELAYS = (0.8,)
EDGE_TTS_BATCH_ABORT_AFTER_FAILURES = 2
EDGE_TTS_PIECE_MAX_SENTENCES = 12
TTS_SILENT_SCENE_RETRY_DELAY_SECONDS = 2.0
# Edge answers a scene in a few seconds; the 300s Gemini TTS timeout
# would let one hung half-open WebSocket eat five minutes of a job.
EDGE_TTS_TIMEOUT_SECONDS = max(
    10, _parse_int_env("EDGE_TTS_TIMEOUT_SECONDS", 45)
)


def _edge_tts_voice_for(settings) -> str:
    # User rule: the Edge narration voice is always Thiha
    # (my-MM-ThihaNeural), regardless of the selected Gemini voice
    # or pronoun.  One consistent voice across every job.
    return EDGE_TTS_VOICE_MALE


async def _edge_tts_synthesize_to_file(text: str, voice: str, out_path: str) -> None:
    """Write Edge TTS audio (MP3) for ``text`` to ``out_path``."""
    import edge_tts  # lazy import: fallback-only dependency

    communicate = edge_tts.Communicate(text, voice)
    await asyncio.wait_for(
        communicate.save(out_path),
        timeout=float(EDGE_TTS_TIMEOUT_SECONDS),
    )


async def _edge_tts_clip_for_text(
    text: str,
    voice: str,
    voice_filter,
    work_dir: str,
    tag: str,
    attempts: int = EDGE_TTS_SCENE_ATTEMPTS,
    delays=EDGE_TTS_RETRY_DELAYS,
):
    """Synthesize+validate one Edge request, retrying transient failures.

    Returns ``(clip, last_error)``; ``clip`` is a validated, polished
    float32 array, or ``None`` when every attempt failed.
    """
    raw_path = os.path.join(work_dir, f"{tag}.mp3")
    pcm_path = os.path.join(work_dir, f"{tag}.pcm")
    last_error = None
    for attempt in range(max(1, int(attempts or 1))):
        try:
            if not str(text or "").strip():
                raise RuntimeError("empty scene text")
            await _edge_tts_synthesize_to_file(text, voice, raw_path)
            if not os.path.exists(raw_path) or os.path.getsize(raw_path) < 400:
                raise RuntimeError("edge-tts produced no audio file")
            clip = await _audio_file_to_master(raw_path, pcm_path, voice_filter, [])
            # A decodable file can still be silent or cut off mid-word;
            # only complete speech may leave this loop.
            _validate_scene_clip(clip, text)
            return _polish_clip(clip), None
        except Exception as e:  # noqa: BLE001 - any provider failure is retried
            last_error = e
            if attempt + 1 < max(1, int(attempts or 1)):
                wait = delays[min(attempt, len(delays) - 1)] if delays else 0.6
                await asyncio.sleep(wait)
        finally:
            for path in (raw_path, pcm_path):
                if os.path.exists(path):
                    try:
                        os.remove(path)
                    except Exception:
                        pass
    return None, last_error


async def _edge_tts_clip_in_pieces(
    text: str,
    voice: str,
    voice_filter,
    work_dir: str,
    tag: str,
):
    """Retry a failing scene sentence by sentence and rejoin the audio.

    A single long Edge request that keeps failing usually succeeds when it
    is broken into its sentences, and every piece is still real speech for
    that scene -- no content is invented or dropped.
    """
    sentences = [part.strip() for part in _split_sentences(text) if part.strip()]
    if len(sentences) < 2:
        return None, RuntimeError("scene has a single sentence; cannot split")
    pieces = []
    last_error = None
    for index, sentence in enumerate(sentences[:EDGE_TTS_PIECE_MAX_SENTENCES]):
        clip, error = await _edge_tts_clip_for_text(
            sentence,
            voice,
            voice_filter,
            work_dir,
            f"{tag}_p{index}",
            attempts=EDGE_TTS_PIECE_ATTEMPTS,
            delays=EDGE_TTS_PIECE_DELAYS,
        )
        if clip is None:
            return None, error or RuntimeError("sentence piece failed")
        pieces.append(clip)
    if not pieces:
        return None, last_error or RuntimeError("no sentence pieces")
    return np.concatenate(pieces).astype(np.float32), None


async def _tts_one_batch_edge(batch, batch_idx, total_batches, work_dir, s, voice_filter, joined):
    """Edge TTS: synthesize each scene separately (free + fast).

    Per-scene requests matter: one joined request has to be sliced
    back into scenes by char-weight guessing, and any mis-slice is
    heard as doubled/cut-off speech in the final video (user
    report).  Separate requests make every clip exactly its own
    scene's audio, with clean sentence prosody per request.

    Reliability (v5.16): a scene is first retried with spaced attempts,
    then re-requested sentence by sentence, and only then does it become a
    short silence so one bad scene cannot sink the whole batch.  If the
    first scenes fail completely the batch gives up early (Edge is down,
    not one request) and returns ``None`` so the next provider -- and the
    re-synthesis pass in synthesize_tts -- can take over quickly instead
    of spending a minute on every scene.
    """
    global _LAST_TTS_ERROR, _LAST_TTS_PROVIDER, _LAST_TTS_SILENCED_SCENES
    voice = _edge_tts_voice_for(s)
    clips = []
    successes = 0
    failures = 0
    last_batch_error = None
    for scene_idx, scene in enumerate(batch):
        text = " ".join(str(scene.get("burmese") or "").split())
        tag = f"tts_{batch_idx}_edge_{scene_idx}"
        clip, last_error = await _edge_tts_clip_for_text(
            text, voice, voice_filter, work_dir, tag
        )
        if clip is None and text:
            piece_clip, piece_error = await _edge_tts_clip_in_pieces(
                text, voice, voice_filter, work_dir, tag
            )
            if piece_clip is not None:
                clip = piece_clip
                logger.info(
                    f"TTS batch {batch_idx + 1}/{total_batches} scene "
                    f"{scene_idx + 1}: sentence-by-sentence retry succeeded"
                )
            else:
                last_error = last_error or piece_error
        if clip is None:
            failures += 1
            last_batch_error = last_error
            _LAST_TTS_ERROR_BY_MODEL["edge-tts"] = str(last_error)[:800]
            logger.warning(
                f"TTS batch {batch_idx + 1}/{total_batches} scene "
                f"{scene_idx + 1} edge-tts failed ({voice}) after retries: "
                f"{str(last_error)[:250]}"
            )
            clip = np.zeros(int(2.5 * SAMPLE_RATE), dtype=np.float32)
            if successes == 0 and failures >= EDGE_TTS_BATCH_ABORT_AFTER_FAILURES:
                logger.warning(
                    f"TTS batch {batch_idx + 1}/{total_batches}: edge is "
                    f"failing wholesale ({failures} scenes, 0 successes); "
                    "giving up on Edge for this batch"
                )
                _LAST_TTS_ERROR = (
                    f"edge-tts: {failures} scene(s) failed with no success "
                    f"({voice}): {str(last_batch_error)[:400]}"
                )
                return None
        else:
            successes += 1
        clips.append(clip)
    if successes == 0:
        _LAST_TTS_ERROR = (
            f"edge-tts: every scene failed ({voice}): "
            f"{str(last_batch_error)[:400]}"
        )
        return None
    if failures:
        # Name the real cause in the user-facing error / /healthz rather
        # than leaving a stale Gemini quota error from an earlier job.
        _LAST_TTS_ERROR = (
            f"edge-tts: {failures}/{len(batch)} scene(s) silent ({voice}): "
            f"{str(last_batch_error)[:400]}"
        )
        _LAST_TTS_SILENCED_SCENES += failures
    _LAST_TTS_PROVIDER = "edge"
    logger.info(
        f"TTS batch {batch_idx + 1}/{total_batches} OK "
        f"(edge-tts {voice}, {successes}/{len(batch)} scenes)"
    )
    return clips


async def _tts_one_batch(batch: list, batch_idx: int, total_batches: int, work_dir: str, settings: dict = None):
    """Synthesize one batch with the configured providers in order.

    Default order is Edge (completely free, no quota queue) first,
    then Gemini Charon -- see TTS_PROVIDER_ORDER.
    """
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    voice_filter = build_voice_filter(s)
    joined = "\n\n".join(s_["burmese"] for s_ in batch)
    for provider in TTS_PROVIDER_ORDER:
        if provider == "edge":
            if not EDGE_TTS_FALLBACK_ENABLED:
                continue
            clips = await _tts_one_batch_edge(
                batch, batch_idx, total_batches, work_dir, s,
                voice_filter, joined,
            )
        elif provider == "gemini":
            clips = await _tts_one_batch_gemini(
                batch, batch_idx, total_batches, work_dir, s,
                voice_filter, joined,
            )
        else:  # pragma: no cover - parser only yields edge/gemini
            continue
        if clips is not None:
            return clips
        logger.warning(
            f"TTS batch {batch_idx + 1}/{total_batches}: provider "
            f"{provider} failed; trying next provider"
        )
    return None


async def _tts_one_batch_gemini(batch, batch_idx, total_batches, work_dir, s, voice_filter, joined):
    global _LAST_TTS_ERROR, _LAST_TTS_PROVIDER
    voice_name = s.get("voice") or "Charon"
    client = _make_gemini_client()
    # Current models want voice_config.voice; legacy preview models
    # want prebuilt_voice_config.voice_name.  Alternate per attempt.
    try:
        _voice_fields = types.VoiceConfig.model_fields
    except Exception:
        _voice_fields = {}
    shapes = ["voice", "prebuilt"] if "voice" in _voice_fields else ["prebuilt"]

    for model in _live_gemini_models(PREFERRED_TTS_MODELS):
        for attempt in range(3):
            tmp_raw = os.path.join(work_dir, f"tts_{batch_idx}_raw.bin")
            tmp_pcm = os.path.join(work_dir, f"tts_{batch_idx}.pcm")
            try:
                cfg = types.GenerateContentConfig(
                    response_modalities=["AUDIO"],
                    speech_config=_tts_speech_config(
                        voice_name, shapes[attempt % len(shapes)]
                    ),
                )
                # Plain text only: current TTS models recite the
                # input verbatim, so style instructions would be
                # read aloud.  Verbatim recitation in the selected
                # prebuilt voice *is* the original voice at natural
                # speed.
                resp = await asyncio.wait_for(
                    asyncio.to_thread(
                        client.models.generate_content,
                        model=model,
                        contents=joined,
                        config=cfg,
                    ),
                    timeout=float(GEMINI_TTS_TIMEOUT_SECONDS),
                )
                cands = getattr(resp, "candidates", None) or []
                if not cands or not getattr(cands[0], "content", None):
                    raise RuntimeError("no candidates")
                # The audio part is not guaranteed to be first --
                # scan every part for inline audio data.
                parts = getattr(cands[0].content, "parts", None) or []
                data = None
                for part in parts:
                    inline = getattr(part, "inline_data", None)
                    if inline is not None and getattr(inline, "data", None):
                        data = inline.data
                        break
                if data is None:
                    raise RuntimeError("no inline_data")
                if isinstance(data, str):
                    data = base64.b64decode(data)
                if not data or len(data) < 1000:
                    raise RuntimeError(f"too small ({len(data) if data else 0} bytes)")

                with open(tmp_raw, "wb") as f:
                    f.write(data)

                # Current TTS models return a complete WAV file by
                # default (older ones returned headerless PCM).
                # Let ffmpeg sniff WAV itself; only force the raw
                # s16le/24kHz interpretation for headerless data.
                input_args = (
                    []
                    if data[:4] == b"RIFF"
                    else ["-f", "s16le", "-ar", "24000", "-ac", "1"]
                )
                master = await _audio_file_to_master(
                    tmp_raw, tmp_pcm, voice_filter, input_args
                )
                clips = [
                    _polish_clip(c)
                    for c in split_pcm_by_weights(master, batch)
                ]
                _LAST_TTS_PROVIDER = "gemini"
                logger.info(f"TTS batch {batch_idx + 1}/{total_batches} OK ({model})")
                return clips

            except Exception as e:
                err = str(e)[:200]
                _LAST_TTS_ERROR = f"{model}: {err}"[:300]
                _LAST_TTS_ERROR_BY_MODEL[model] = str(e)[:800]
                logger.warning(f"TTS batch {batch_idx + 1} attempt {attempt + 1} ({model}): {err}")
                if _gemini_error_is_model_gone(e):
                    # Retired model: remember it and move straight to
                    # the next model instead of burning more attempts.
                    _DEAD_GEMINI_MODELS.add(model)
                    break
                if _gemini_error_is_quota_exhausted(e):
                    # Plan quota is gone for this model -- sleeping
                    # and retrying it inside this job cannot help.
                    # Remember it (skipped process-wide for a while)
                    # and move straight to the next model.
                    _mark_quota_exhausted(model)
                    logger.warning(
                        "TTS model %s quota-exhausted; skipping it for %ss",
                        model,
                        GEMINI_QUOTA_SKIP_SECONDS,
                    )
                    break
                if _gemini_error_is_overload(e):
                    # High-demand spikes need real waiting, not seconds.
                    await asyncio.sleep(15 * (attempt + 1))
                else:
                    await asyncio.sleep(2)
            finally:
                for p in (tmp_raw, tmp_pcm):
                    if os.path.exists(p):
                        try:
                            os.remove(p)
                        except Exception:
                            pass

    return None


async def synthesize_tts(scenes: list, work_dir: str, settings: dict = None) -> list[np.ndarray]:
    global _LAST_TTS_SILENCED_SCENES
    _LAST_TTS_SILENCED_SCENES = 0
    BATCH_SIZE = 8
    batches = [scenes[i:i + BATCH_SIZE] for i in range(0, len(scenes), BATCH_SIZE)]
    logger.info(f"TTS: {len(scenes)} scenes in {len(batches)} batches")

    # Batches are independent (own temp files per batch index), so run
    # two at a time instead of strictly one-by-one with a fixed pause
    # between them.  Order is preserved by gather; the per-batch
    # overload waits inside _tts_one_batch still apply.
    semaphore = asyncio.Semaphore(2)

    async def _run_batch(b_idx, batch):
        async with semaphore:
            return await _tts_one_batch(
                batch, b_idx, len(batches), work_dir, settings
            )

    results = await asyncio.gather(
        *(_run_batch(b_idx, batch) for b_idx, batch in enumerate(batches)),
        return_exceptions=True,
    )
    all_clips = []
    for b_idx, (batch, clips) in enumerate(zip(batches, results)):
        if isinstance(clips, Exception) or clips is None:
            if isinstance(clips, Exception):
                logger.error(
                    f"TTS batch {b_idx + 1}/{len(batches)} raised "
                    f"{clips!r} — silence fallback"
                )
            else:
                logger.error(f"TTS batch {b_idx + 1}/{len(batches)} failed — silence fallback")
            clips = [np.zeros(int(2.5 * SAMPLE_RATE), dtype=np.float32) for _ in batch]
        all_clips.extend(clips)

    # Any scene still silent gets one more fresh pass.  A missing scene is
    # not just a shorter recap: it is silence in the middle of the video
    # and content the viewer never hears.  A new connection/request a
    # moment later usually succeeds where the first pass was refused.
    global _LAST_TTS_RETRY_RECOVERED
    _LAST_TTS_RETRY_RECOVERED = 0
    silent_indexes = [
        index for index, clip in enumerate(all_clips) if _clip_is_silent(clip)
    ]
    if silent_indexes:
        logger.warning(
            f"TTS: {len(silent_indexes)} scene(s) came back silent; "
            "retrying them in a fresh pass"
        )
        await asyncio.sleep(TTS_SILENT_SCENE_RETRY_DELAY_SECONDS)
        retry_scenes = [scenes[index] for index in silent_indexes]
        retry_batches = max(1, len(batches))
        retry_clips = await _tts_one_batch(
            retry_scenes, retry_batches, retry_batches + 1, work_dir, settings
        )
        if retry_clips is not None:
            for index, clip in zip(silent_indexes, retry_clips):
                if not _clip_is_silent(clip):
                    all_clips[index] = clip
        _LAST_TTS_RETRY_RECOVERED = sum(
            1 for index in silent_indexes if not _clip_is_silent(all_clips[index])
        )
        logger.info(
            "TTS: %d/%d silent scene(s) recovered in the retry pass"
            % (_LAST_TTS_RETRY_RECOVERED, len(silent_indexes))
        )

    _LAST_TTS_SILENCED_SCENES = sum(
        1 for clip in all_clips if _clip_is_silent(clip)
    )
    return all_clips


FIRST_PERSON_MALE = "ကျွန်တော်"
FIRST_PERSON_FEMALE = "ကျွန်မ"
FIRST_PERSON_PRONOUNS = (FIRST_PERSON_MALE, FIRST_PERSON_FEMALE)
FIRST_PERSON_POSSESSIVE_VARIANTS = {
    FIRST_PERSON_MALE: ("ကျွန်တော့်", "ကျွန်တော့်"),
    FIRST_PERSON_FEMALE: ("ကျွန်မ့်",),
}
NARRATOR_PERSPECTIVE = "first_person_protagonist"
_QUOTE_PAIRS = (
    ("“", "”"),
    ("‘", "’"),
    ('"', '"'),
    ("'", "'"),
    ("«", "»"),
    ("‹", "›"),
    ("「", "」"),
    ("『", "』"),
    ("〈", "〉"),
    ("《", "》"),
)
_QUOTED_SPEECH_PATTERNS = tuple(
    re.compile(re.escape(opening) + r"(.*?)" + re.escape(closing), re.DOTALL)
    for opening, closing in _QUOTE_PAIRS
)


def _normalize_burmese_text(text: str) -> str:
    normalized = unicodedata.normalize("NFC", str(text or ""))
    return (
        normalized
        .replace("\u200b", "")
        .replace("\u200c", "")
        .replace("\u200d", "")
    )


def _quoted_speech_segments(text: str) -> list:
    """Return the contents of quoted direct-speech spans in ``text``."""
    value = str(text or "")
    segments = []
    for pattern in _QUOTED_SPEECH_PATTERNS:
        segments.extend(match.group(1) for match in pattern.finditer(value))
    return segments


def _strip_quoted_speech(text: str) -> str:
    """Remove quoted character dialogue, leaving only narrator text."""
    value = str(text or "")
    for pattern in _QUOTED_SPEECH_PATTERNS:
        value = pattern.sub(" ", value)
    return value


def _first_person_token_counts(text: str) -> dict:
    normalized = _normalize_burmese_text(text)
    counts = {}
    for pronoun in FIRST_PERSON_PRONOUNS:
        total = normalized.count(pronoun)
        for variant in FIRST_PERSON_POSSESSIVE_VARIANTS.get(pronoun, ()):
            total += normalized.count(variant)
        counts[pronoun] = int(total)
    return counts


def _first_person_narrator_counts(text: str) -> dict:
    """Count first-person words spoken by the narrator, not in quotes."""
    return _first_person_token_counts(_strip_quoted_speech(text))


def _quoted_first_person_counts(text: str) -> dict:
    return _first_person_token_counts(" ".join(_quoted_speech_segments(text)))


def _normalize_protagonist_gender(value) -> str:
    """Return ``female``, ``male`` or ``""`` from explicit source metadata."""

    text = _normalize_burmese_text(value).strip().lower()
    if not text:
        return ""
    if FIRST_PERSON_FEMALE in text:
        return "female"
    if FIRST_PERSON_MALE in text:
        return "male"
    female_markers = (
        "female",
        "woman",
        "girl",
        "အမျိုးသမီး",
        "မိန်းကလေး",
        "ကောင်မလေး",
        "သမီး",
        "အစ်မ",
        "ညီမ",
    )
    male_markers = (
        "male",
        "man",
        "boy",
        "အမျိုးသား",
        "ယောက်ျား",
        "ကောင်လေး",
        "သား",
        "အစ်ကို",
        "ညီ",
    )
    has_female = any(marker in text for marker in female_markers)
    has_male = any(marker in text for marker in male_markers)
    if has_female and not has_male:
        return "female"
    if has_male and not has_female:
        return "male"
    if text in {"f", "female"}:
        return "female"
    if text in {"m", "male"}:
        return "male"
    return ""


def _pronoun_for_gender(gender) -> str:
    normalized = _normalize_protagonist_gender(gender)
    if normalized == "female":
        return FIRST_PERSON_FEMALE
    if normalized == "male":
        return FIRST_PERSON_MALE
    return ""


def _gender_from_pronoun(pronoun) -> str:
    text = _normalize_burmese_text(pronoun)
    if FIRST_PERSON_FEMALE in text:
        return "female"
    if FIRST_PERSON_MALE in text:
        return "male"
    return ""


def _normalize_protagonist_pronoun(value, gender="") -> str:
    text = _normalize_burmese_text(value)
    if FIRST_PERSON_FEMALE in text and FIRST_PERSON_MALE not in text:
        return FIRST_PERSON_FEMALE
    if FIRST_PERSON_MALE in text and FIRST_PERSON_FEMALE not in text:
        return FIRST_PERSON_MALE
    return _pronoun_for_gender(gender or value)


def _opposite_first_person_pronoun(pronoun) -> str:
    normalized = _normalize_protagonist_pronoun(pronoun)
    if normalized == FIRST_PERSON_FEMALE:
        return FIRST_PERSON_MALE
    if normalized == FIRST_PERSON_MALE:
        return FIRST_PERSON_FEMALE
    return ""


def _dominant_narrator_pronoun(texts) -> str:
    counts = {FIRST_PERSON_MALE: 0, FIRST_PERSON_FEMALE: 0}
    if isinstance(texts, (str, dict)):
        texts = [texts]
    for item in texts or []:
        if isinstance(item, dict):
            value = str(item.get("burmese") or item.get("text") or "")
        else:
            value = str(item or "")
        item_counts = _first_person_narrator_counts(value)
        for pronoun in FIRST_PERSON_PRONOUNS:
            counts[pronoun] += int(item_counts.get(pronoun) or 0)
    if counts[FIRST_PERSON_FEMALE] > counts[FIRST_PERSON_MALE]:
        return FIRST_PERSON_FEMALE
    if counts[FIRST_PERSON_MALE] > counts[FIRST_PERSON_FEMALE]:
        return FIRST_PERSON_MALE
    return ""


_PROTAGONIST_SUBJECT_PREFIXES = (
    "",
    "အဲဒီမှာ ",
    "အဲ့ဒီမှာ ",
    "ဒီအချိန်မှာပဲ ",
    "အဲဒီအချိန်မှာပဲ ",
    "အဲ့ဒီအချိန်မှာပဲ ",
    "ဒါနဲ့ ",
    "အဲ့ဒါနဲ့ ",
    "အဲဒါနဲ့ ",
    "ဒါပေမဲ့ ",
    "ဒါပေမယ့် ",
    "နောက်တော့ ",
    "ပြီးတော့ ",
    "ဒီလိုနဲ့ ",
    "ရုတ်တရက် ",
    "ချက်ချင်း ",
    "နောက်ဆုံးမှာတော့ ",
    "အဲဒီမှာ",
    "အဲ့ဒီမှာ",
    "ဒီအချိန်မှာပဲ",
    "အဲဒီအချိန်မှာပဲ",
    "အဲ့ဒီအချိန်မှာပဲ",
    "ဒါနဲ့",
    "အဲ့ဒါနဲ့",
    "အဲဒါနဲ့",
    "ဒါပေမဲ့",
    "ဒါပေမယ့်",
    "နောက်တော့",
    "ပြီးတော့",
    "ဒီလိုနဲ့",
    "ရုတ်တရက်",
    "ချက်ချင်း",
    "နောက်ဆုံးမှာတော့",
    "အဲဒီနောက် ",
    "အဲ့ဒီနောက် ",
    "အဲဒီနောက်",
    "အဲ့ဒီနောက်",
    "အဲဒီနောက်မှာတော့ ",
    "အဲဒီနောက်မှာတော့",
    "ခဏအကြာမှာ ",
    "ခဏအကြာမှာ",
    "တစ်ချိန်တည်းမှာ ",
    "တစ်ချိန်တည်းမှာ",
    "ဒီကြားထဲမှာ ",
    "ဒီကြားထဲမှာ",
    "နောက်နေ့မနက် ",
    "နောက်နေ့မနက်",
)


def _protagonist_self_name_subject_count(text: str, protagonist_forms=None) -> int:
    """Count clauses where the protagonist's own name is the narrator subject.

    The benchmark voice introduces herself by name once, then normally says
    ``ကျွန်မ/ကျွန်တော်`` for her own actions.  A name used as an object, a
    possessive, a quoted form of address, or another person's subject is not
    a POV error, so this deliberately looks only at clause-initial subject
    particles after a small set of spoken-story connectors.
    """

    forms = []
    for form in protagonist_forms or []:
        clean = _normalize_burmese_text(form).strip(" «»\"'“”‘’")
        if clean and clean not in forms:
            forms.append(clean)
    if not forms:
        return 0
    forms.sort(key=len, reverse=True)
    total = 0
    for sentence in _split_sentences(str(text or "")):
        unquoted = _strip_quoted_speech(sentence)
        compact_sentence = _normalize_burmese_text(unquoted)
        # Self-introduction ("ကျွန်မအမည်က ... ပါ" / "... လို့ခေါ်တယ်") is
        # precisely the one place where the full name belongs.
        if any(pronoun in compact_sentence for pronoun in FIRST_PERSON_PRONOUNS) and any(
            marker in compact_sentence
            for marker in ("အမည်က", "နာမည်က", "အမည်က", "နာမည်က", "လို့ခေါ်", "ဆိုတဲ့")
        ):
            continue
        for clause in unquoted.split("၊"):
            candidate = clause.strip(" \t\r\n«»\"'“”‘’-")
            for prefix in _PROTAGONIST_SUBJECT_PREFIXES:
                probe = candidate
                if prefix:
                    if not probe.startswith(prefix):
                        continue
                    probe = probe[len(prefix):].lstrip()
                matched = False
                for form in forms:
                    if not probe.startswith(form):
                        continue
                    rest = probe[len(form):]
                    if rest.startswith(("ကတော့", "ကလည်း", "တို့က", "တို့လည်း", "က", "ဟာ", "လည်း")):
                        total += 1
                        matched = True
                        break
                if matched:
                    break
    return total


def _scene_uses_first_person_protagonist_narrator(
    text: str,
    *,
    expected_pronoun: str = "",
    protagonist_forms=None,
    require_self_reference: bool = False,
) -> bool:
    """Whether one scene is compatible with the locked protagonist voice.

    A named cutaway about other people may validly contain no ``I`` at all;
    it is still the protagonist retelling what happened in benchmark style.
    POV errors are the wrong/mixed self-pronoun outside quotes and the
    protagonist repeatedly acting under their own name as if a third-person
    narrator were watching them.
    """

    value = str(text or "").strip()
    if not value:
        return False
    counts = _first_person_narrator_counts(value)
    male_count = int(counts.get(FIRST_PERSON_MALE) or 0)
    female_count = int(counts.get(FIRST_PERSON_FEMALE) or 0)
    if male_count and female_count:
        return False
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    if expected:
        opposite = _opposite_first_person_pronoun(expected)
        if int(counts.get(opposite) or 0):
            return False
        if require_self_reference and not int(counts.get(expected) or 0):
            return False
    elif require_self_reference and not (male_count + female_count):
        return False
    if _protagonist_self_name_subject_count(value, protagonist_forms):
        return False
    return True


def _scene_text_for_pov(scene) -> str:
    if isinstance(scene, dict):
        return str(scene.get("burmese") or scene.get("text") or "")
    if isinstance(scene, str):
        return scene
    return ""


def _first_person_bad_scene_indexes(
    scenes: list,
    *,
    expected_pronoun: str = "",
    protagonist_forms=None,
    require_opening_self_reference: bool = False,
) -> list:
    texts = [_scene_text_for_pov(scene) for scene in (scenes or [])]
    expected = _normalize_protagonist_pronoun(expected_pronoun) or _dominant_narrator_pronoun(texts)
    bad = []
    for index, text in enumerate(texts):
        if not _scene_uses_first_person_protagonist_narrator(
            text,
            expected_pronoun=expected,
            protagonist_forms=protagonist_forms,
        ):
            bad.append(index)
    if require_opening_self_reference and texts:
        opening_counts = _first_person_narrator_counts(texts[0])
        if expected:
            opening_ok = bool(opening_counts.get(expected))
        else:
            opening_ok = bool(sum(opening_counts.values()))
        if not opening_ok and 0 not in bad:
            bad.insert(0, 0)
    return sorted(set(bad))


def _first_person_repair_scene_indexes(
    scenes: list,
    *,
    expected_pronoun: str = "",
    protagonist_forms=None,
    is_opening: bool = False,
) -> list:
    """Scenes needing model POV repair, including silent third-person drift."""

    texts = [_scene_text_for_pov(scene) for scene in (scenes or [])]
    bad = set(
        _first_person_bad_scene_indexes(
            texts,
            expected_pronoun=expected_pronoun,
            protagonist_forms=protagonist_forms,
        )
    )
    metrics = _first_person_metrics(
        texts,
        expected_pronoun=expected_pronoun,
        protagonist_forms=protagonist_forms,
    )
    forms = [
        _normalize_burmese_text(form).strip()
        for form in (protagonist_forms or [])
        if str(form or "").strip()
    ]
    if forms and not metrics.get("pov_established"):
        for index, text in enumerate(texts):
            unquoted = _strip_quoted_speech(text)
            if any(form in unquoted for form in forms):
                bad.add(index)
    if is_opening and texts and forms and expected_pronoun:
        if not _protagonist_self_introduction_present(
            texts,
            protagonist_forms=forms,
            expected_pronoun=expected_pronoun,
        ):
            bad.add(0)
    return sorted(index for index in bad if 0 <= index < len(texts))


def _first_person_metrics(
    texts: list,
    *,
    expected_pronoun: str = "",
    protagonist_forms=None,
) -> dict:
    values = [_scene_text_for_pov(text) for text in (texts or [])]
    narrator_counts = {FIRST_PERSON_MALE: 0, FIRST_PERSON_FEMALE: 0}
    quoted_counts = {FIRST_PERSON_MALE: 0, FIRST_PERSON_FEMALE: 0}
    first_person_scene_count = 0
    named_cutaway_scene_count = 0
    protagonist_self_name_subject_count = 0
    for value in values:
        item_narrator_counts = _first_person_narrator_counts(value)
        item_quoted_counts = _quoted_first_person_counts(value)
        for key in narrator_counts:
            narrator_counts[key] += int(item_narrator_counts.get(key) or 0)
            quoted_counts[key] += int(item_quoted_counts.get(key) or 0)
        if sum(item_narrator_counts.values()):
            first_person_scene_count += 1
        elif value.strip():
            named_cutaway_scene_count += 1
        protagonist_self_name_subject_count += _protagonist_self_name_subject_count(
            value,
            protagonist_forms,
        )
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    dominant = _dominant_narrator_pronoun(values)
    effective_expected = expected or dominant
    bad_indexes = _first_person_bad_scene_indexes(
        values,
        expected_pronoun=effective_expected,
        protagonist_forms=protagonist_forms,
    )
    compatible_scene_count = len(values) - len(bad_indexes)
    return {
        "perspective": NARRATOR_PERSPECTIVE,
        "narrator_perspective": NARRATOR_PERSPECTIVE,
        "expected_pronoun": effective_expected,
        "dominant_pronoun": dominant,
        "protagonist_gender": _gender_from_pronoun(effective_expected),
        "male_narrator_count": int(narrator_counts[FIRST_PERSON_MALE]),
        "female_narrator_count": int(narrator_counts[FIRST_PERSON_FEMALE]),
        "first_person_narrator_count": int(sum(narrator_counts.values())),
        "quoted_first_person_count": int(sum(quoted_counts.values())),
        "scene_count": len(values),
        "first_person_scene_count": int(first_person_scene_count),
        "named_cutaway_scene_count": int(named_cutaway_scene_count),
        "compatible_scene_count": int(compatible_scene_count),
        "protagonist_self_name_subject_count": int(
            protagonist_self_name_subject_count
        ),
        "bad_scene_indexes": bad_indexes,
        "pov_established": bool(sum(narrator_counts.values())),
        "all_scenes_first_person_compatible": bool(values) and not bad_indexes,
        # Compatibility for older stored diagnostics only.  New gates use
        # the explicit first-person keys above.
        "third_person_scene_count": int(named_cutaway_scene_count),
        "all_scenes_third_person": False,
    }


DIRECT_SCENE_TEXT_KEYS = (
    "burmese",
    "text",
    "narration",
    "narration_text",
    "myanmar",
    "myanmar_text",
    "script",
    "content",
    "description",
)
DIRECT_SCENE_LIST_KEYS = (
    "scenes",
    "segments",
    "parts",
    "chunks",
    "script_scenes",
    "scene_list",
    "script",
    "data",
    "result",
    "output",
)


def _scene_text_from_mapping(item) -> str:
    if isinstance(item, str):
        return item.strip()
    if not isinstance(item, dict):
        return ""
    for key in DIRECT_SCENE_TEXT_KEYS:
        value = item.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


def _salvage_json_scene_objects(raw: str) -> list:
    """Recover complete scene objects from a truncated JSON response."""
    decoder = json.JSONDecoder()
    scenes = []
    seen = set()
    for match in re.finditer(r"\{", raw or ""):
        start = match.start()
        try:
            value, end = decoder.raw_decode(raw, start)
        except Exception:
            continue
        if not isinstance(value, dict) or not _scene_text_from_mapping(value):
            continue
        marker = (start, end, _scene_text_from_mapping(value))
        if marker in seen:
            continue
        seen.add(marker)
        scenes.append(value)
    return scenes


def _parse_gemini_json_text(raw, *, _depth: int = 0):
    """Parse Gemini JSON even when it is fenced, wrapped, or truncated."""
    if isinstance(raw, (dict, list)):
        return raw
    text = str(raw or "").strip()
    if not text:
        raise ValueError("Gemini returned empty text")
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s*```$", "", text).strip()

    try:
        value = json.loads(text)
        if isinstance(value, str) and _depth < 3:
            return _parse_gemini_json_text(value, _depth=_depth + 1)
        if isinstance(value, (dict, list)):
            return value
        raise ValueError("Gemini JSON was not an object/list")
    except Exception as first_error:
        decoder = json.JSONDecoder()
        for match in re.finditer(r"[\{\[]", text):
            try:
                value, _end = decoder.raw_decode(text, match.start())
            except Exception:
                continue
            if isinstance(value, list):
                return value
            if isinstance(value, dict):
                # A lone complete scene inside a truncated parent object is
                # only a fragment.  Keep scanning so the salvage step below
                # can recover every complete scene, not just the first one.
                if _scene_text_from_mapping(value) and not any(
                    isinstance(value.get(key), list)
                    for key in DIRECT_SCENE_LIST_KEYS
                ):
                    continue
                return value
        salvaged = _salvage_json_scene_objects(text)
        if salvaged:
            return {"scenes": salvaged, "cuts": []}
        raise ValueError(
            f"Gemini returned invalid JSON ({len(text)} chars): {first_error}"
        ) from first_error


def _gemini_response_text_and_diagnostics(response) -> tuple[str, str]:
    """Return response text plus safe finish/block/token diagnostics."""
    diagnostics = []
    text = ""
    try:
        text = str(getattr(response, "text", "") or "")
    except Exception as e:
        diagnostics.append(f"text_error={_safe_error_text(e, 180)}")

    candidates = list(getattr(response, "candidates", None) or [])
    if not text and candidates:
        pieces = []
        for candidate in candidates:
            content = getattr(candidate, "content", None)
            for part in list(getattr(content, "parts", None) or []):
                part_text = getattr(part, "text", "")
                if isinstance(part_text, str) and part_text:
                    pieces.append(part_text)
        text = "".join(pieces)

    if candidates:
        finish_reason = getattr(candidates[0], "finish_reason", None)
        if finish_reason:
            diagnostics.append(f"finish_reason={finish_reason}")
        safety = []
        for rating in list(getattr(candidates[0], "safety_ratings", None) or []):
            if getattr(rating, "blocked", False):
                safety.append(
                    f"{getattr(rating, 'category', 'safety')}="
                    f"{getattr(rating, 'probability', 'blocked')}"
                )
        if safety:
            diagnostics.append("safety_blocked=" + ",".join(safety[:4]))

    prompt_feedback = getattr(response, "prompt_feedback", None)
    if prompt_feedback is not None:
        block_reason = getattr(prompt_feedback, "block_reason", None)
        if block_reason:
            diagnostics.append(f"block_reason={block_reason}")
        block_message = getattr(prompt_feedback, "block_reason_message", "")
        if block_message:
            diagnostics.append(
                "block_message=" + _safe_error_text(block_message, 180)
            )

    usage = getattr(response, "usage_metadata", None)
    if usage is not None:
        output_tokens = getattr(usage, "candidates_token_count", None)
        total_tokens = getattr(usage, "total_token_count", None)
        if output_tokens is not None or total_tokens is not None:
            diagnostics.append(
                f"output_tokens={output_tokens},total_tokens={total_tokens}"
            )
    return text, "; ".join(str(item) for item in diagnostics if str(item).strip())


def _make_gemini_client():
    """Build a Gemini client whose HTTP calls cannot hang forever."""
    timeout_ms = int(
        max(GEMINI_GENERATE_TIMEOUT_SECONDS, GEMINI_TTS_TIMEOUT_SECONDS) * 1000
    )
    try:
        return genai.Client(
            api_key=GEMINI_API_KEY,
            http_options=types.HttpOptions(timeout=timeout_ms),
        )
    except Exception:
        # Older SDKs (or test doubles) may not accept http_options; the
        # asyncio-level heartbeat timeout still bounds every call.
        return genai.Client(api_key=GEMINI_API_KEY)


def _direct_gemini_json_config(
    max_output_tokens: int = 8192,
    response_mime_type: str = "application/json",
    temperature: float = 0.25,
):
    kwargs = {
        "temperature": float(temperature),
        "max_output_tokens": int(max_output_tokens),
    }
    if response_mime_type:
        kwargs["response_mime_type"] = response_mime_type
    try:
        safety_setting = getattr(types, "SafetySetting", None)
        harm_category = getattr(types, "HarmCategory", None)
        harm_threshold = getattr(types, "HarmBlockThreshold", None)
        if safety_setting and harm_category and harm_threshold:
            threshold = getattr(harm_threshold, "BLOCK_ONLY_HIGH", None)
            categories = [
                getattr(harm_category, name, None)
                for name in (
                    "HARM_CATEGORY_HARASSMENT",
                    "HARM_CATEGORY_HATE_SPEECH",
                    "HARM_CATEGORY_SEXUALLY_EXPLICIT",
                    "HARM_CATEGORY_DANGEROUS_CONTENT",
                )
            ]
            settings = [
                safety_setting(category=category, threshold=threshold)
                for category in categories
                if category is not None and threshold is not None
            ]
            if settings:
                kwargs["safety_settings"] = settings
    except Exception:
        kwargs.pop("safety_settings", None)
    return types.GenerateContentConfig(**kwargs)


async def _generate_direct_gemini_json(
    client,
    contents,
    *,
    purpose: str,
    tracker=None,
    attempts_per_model: int = 1,
    max_output_tokens: int = 8192,
    plain_text: bool = False,
):
    """Generate JSON with model fallback instead of silently using no scenes.

    ``plain_text=True`` asks the same model cascade for ordinary prose
    (no ``response_mime_type``) and returns the raw text.  It is the
    last-resort script path: a model that returns empty or truncated
    JSON normally still writes a full spoken retelling as plain text.

    Within a round, models are launched with staggered hedging: the
    next model starts as soon as the previous one *fails*, or after
    ``GEMINI_HEDGE_DELAY_SECONDS`` if it is still running; on calls
    that carry the video itself, the first
    ``GEMINI_HEDGE_INITIAL_PARALLEL`` models are raced from t=0.
    The first successfully parsed response wins.  A single
    slow/queued request (observed running 100+ seconds on one model
    while others were idle) therefore no longer blocks the whole
    cascade; losing attempts are abandoned and die via the client
    HTTP timeout.  Ordinary failures stop after one round.
    Overload-class failures (429 / 503 "high demand") run extra
    rounds with very short backoff inside
    ``GEMINI_OVERLOAD_RETRY_BUDGET_SECONDS`` (probing every ~6-10s so
    the job resumes almost as soon as capacity returns, but giving
    up clearly after ~2 minutes instead of making the user wait).
    """
    attempts_per_model = max(1, int(attempts_per_model or 1))
    global _LAST_SCRIPT_ANSWERED
    _LAST_SCRIPT_ANSWERED = False
    models = _live_gemini_models(PREFERRED_MODELS)
    sequence = [
        model for model in models for _ in range(attempts_per_model)
    ]
    total_attempts = len(sequence)
    attempt_number = 0
    last_error = "unknown Gemini error"
    last_overload_error = ""
    started = time.monotonic()
    overload_deadline = started + float(
        GEMINI_OVERLOAD_RETRY_BUDGET_SECONDS or 0
    )
    max_rounds = max(1, int(GEMINI_OVERLOAD_MAX_ROUNDS or 1))
    hedge_delay = max(0.05, float(GEMINI_HEDGE_DELAY_SECONDS or 15.0))
    # Race several models from t=0 on the slow calls (video attached);
    # text-only calls start single and rely on the hedge timer.
    has_media = isinstance(contents, (list, tuple)) and any(
        not isinstance(part, str) for part in contents
    )
    initial_parallel = (
        max(1, int(GEMINI_HEDGE_INITIAL_PARALLEL or 1)) if has_media else 1
    )
    attempt_timeout = max(
        0.05, float(GEMINI_GENERATE_TIMEOUT_SECONDS or 240)
    )
    heartbeat_interval = max(0.05, float(GEMINI_HEARTBEAT_SECONDS or 20.0))

    def _abandon(task, model=None) -> None:
        def _swallow(done_task) -> None:
            if done_task.cancelled():
                return
            try:
                exc = done_task.exception()
            except Exception:
                return
            # Even a losing/abandoned attempt can teach us that a
            # model was retired or ran out of plan quota -- remember
            # it so later calls skip straight past it.
            if exc is not None and model:
                if _gemini_error_is_model_gone(exc):
                    _DEAD_GEMINI_MODELS.add(model)
                if _gemini_error_is_quota_exhausted(exc):
                    _mark_quota_exhausted(model)

        task.add_done_callback(_swallow)

    overload_round = 0
    while True:
        overload_round += 1
        saw_overload = False
        # Rebuild per round: a model that 404'd in an earlier round is
        # dead for good -- never relaunch it.
        sequence = [
            model
            for model in _live_gemini_models(models)
            for _ in range(attempts_per_model)
        ]
        if not sequence:
            break
        total_attempts = len(sequence)
        pending: dict = {}  # task -> (model, seq_no, launched_at)
        next_index = 0
        last_launch_at = 0.0
        round_started = time.monotonic()
        last_heartbeat_at = round_started
        winner = None

        def _launch_next() -> None:
            nonlocal next_index, attempt_number, last_launch_at
            model = sequence[next_index]
            next_index += 1
            attempt_number += 1
            task = asyncio.ensure_future(
                asyncio.to_thread(
                    client.models.generate_content,
                    model=model,
                    contents=contents,
                    config=_direct_gemini_json_config(
                        max_output_tokens,
                        response_mime_type=(
                            "" if plain_text else "application/json"
                        ),
                        temperature=0.45 if plain_text else 0.25,
                    ),
                )
            )
            pending[task] = (model, attempt_number, time.monotonic())
            last_launch_at = time.monotonic()

        try:
            # Fastest-answer race: launch the initial batch together.
            while next_index < min(initial_parallel, len(sequence)):
                _launch_next()
            while pending or next_index < len(sequence):
                # Launch immediately when idle, or hedge once the
                # latest attempt has been running for hedge_delay.
                if next_index < len(sequence) and (
                    not pending
                    or (time.monotonic() - last_launch_at) >= hedge_delay
                ):
                    _launch_next()

                now = time.monotonic()
                wake_in = heartbeat_interval
                if next_index < len(sequence) and pending:
                    wake_in = min(
                        wake_in,
                        max(0.05, hedge_delay - (now - last_launch_at)),
                    )
                for _model, _seq, launched_at in pending.values():
                    wake_in = min(
                        wake_in,
                        max(0.05, attempt_timeout - (now - launched_at)),
                    )
                done, _ = await asyncio.wait(
                    set(pending),
                    timeout=wake_in,
                    return_when=asyncio.FIRST_COMPLETED,
                )
                now = time.monotonic()

                for task in list(done):
                    model, seq_no, _launched = pending.pop(task)
                    try:
                        response = task.result()
                    except asyncio.CancelledError:
                        raise
                    except Exception as e:
                        last_error = f"{model}: {_safe_error_text(e, 700)}"
                        _LAST_SCRIPT_ERROR_BY_MODEL[model] = (
                            _safe_error_text(e, 300)
                        )
                        if _gemini_error_is_overload(e):
                            saw_overload = True
                            last_overload_error = last_error
                        if _gemini_error_is_model_gone(e):
                            _DEAD_GEMINI_MODELS.add(model)
                            logger.warning(
                                "Gemini model %s is unavailable (404); "
                                "skipping it for the rest of this process",
                                model,
                            )
                        if _gemini_error_is_quota_exhausted(e):
                            _mark_quota_exhausted(model)
                            logger.warning(
                                "Gemini model %s quota-exhausted; "
                                "skipping it for %ss",
                                model,
                                GEMINI_QUOTA_SKIP_SECONDS,
                            )
                        logger.warning(
                            "Direct Gemini %s failed attempt %s/%s "
                            "(round %s): %s",
                            purpose,
                            seq_no,
                            total_attempts,
                            overload_round,
                            last_error,
                        )
                        continue
                    if winner is not None:
                        # A sibling attempt already won this batch;
                        # failures above were still recorded (404 /
                        # overload bookkeeping), extra successes are
                        # simply ignored.
                        continue
                    raw, diagnostics = _gemini_response_text_and_diagnostics(
                        response
                    )
                    _LAST_SCRIPT_ANSWERED = True
                    _remember_script_preview(raw, purpose=purpose)
                    _LAST_SCRIPT_ERROR_BY_MODEL[model] = (
                        f"answered {len(str(raw or ''))} chars"
                        + (f"; {diagnostics}" if diagnostics else "")
                    )
                    try:
                        if not str(raw or "").strip():
                            detail = (
                                f" ({diagnostics})" if diagnostics else ""
                            )
                            raise ValueError(
                                f"Gemini returned empty text{detail}"
                            )
                        if plain_text:
                            winner = str(raw).strip()
                        else:
                            winner = _parse_gemini_json_text(raw)
                    except Exception as e:
                        last_error = f"{model}: {_safe_error_text(e, 700)}"
                        logger.warning(
                            "Direct Gemini %s unusable response on "
                            "attempt %s/%s (round %s): %s",
                            purpose,
                            seq_no,
                            total_attempts,
                            overload_round,
                            last_error,
                        )
                        continue
                    logger.info(
                        "Direct Gemini %s succeeded with %s on attempt "
                        "%s/%s (%s chars%s)",
                        purpose,
                        model,
                        seq_no,
                        total_attempts,
                        len(str(raw or "")),
                        f"; {diagnostics}" if diagnostics else "",
                    )
                    # Do not break yet: finish recording any sibling
                    # failures from this completed batch first.
                if winner is not None:
                    break

                # Per-attempt hard deadlines.
                for task, (model, seq_no, launched_at) in list(
                    pending.items()
                ):
                    if now - launched_at >= attempt_timeout:
                        del pending[task]
                        _abandon(task, model)
                        last_error = (
                            f"{model}: Gemini call timeout after "
                            f"{attempt_timeout:.0f}s"
                        )
                        logger.warning(
                            "Direct Gemini %s timed out on attempt "
                            "%s/%s (round %s)",
                            purpose,
                            seq_no,
                            total_attempts,
                            overload_round,
                        )

                # Heartbeat so the user sees life + elapsed time.
                if (
                    tracker is not None
                    and pending
                    and (now - last_heartbeat_at) >= heartbeat_interval
                ):
                    last_heartbeat_at = now
                    active_models = ", ".join(
                        m for m, _s, _l in pending.values()
                    )
                    label = (
                        f"{next_index}/{total_attempts}"
                        if overload_round == 1
                        else str(next_index)
                    )
                    try:
                        await tracker.update(
                            f"⏳ Gemini Script ရေးနေဆဲ... "
                            f"({active_models}, ကြိုးစားမှု {label}) "
                            f"⏱ {fmt_time(now - round_started)}",
                            force=True,
                        )
                    except Exception:
                        pass
        finally:
            for leftover, (leftover_model, _s, _l) in list(pending.items()):
                _abandon(leftover, leftover_model)
            pending.clear()

        if winner is not None:
            return winner

        # One full round over every model finished without success.
        if not saw_overload or overload_round >= max_rounds:
            break
        # Probe again almost immediately (6s, 8s, then every 10s):
        # resume the moment capacity returns, never sleep through
        # the end of the spike.
        backoff = min(10.0, 4.0 + 2.0 * overload_round)
        remaining_budget = overload_deadline - time.monotonic()
        if remaining_budget <= 0:
            break
        backoff = min(backoff, remaining_budget)
        logger.warning(
            "Direct Gemini %s overloaded on every model; waiting %.0fs "
            "before round %s (elapsed %.0fs)",
            purpose,
            backoff,
            overload_round + 1,
            time.monotonic() - started,
        )
        wait_left = backoff
        while wait_left > 0:
            if tracker is not None:
                try:
                    await tracker.update(
                        "⏳ Gemini က အလုပ်များနေပါသည် (High Demand/503) — "
                        f"နောက် {max(1, int(round(wait_left)))} စက္ကန့်မှာ "
                        "ပြန်ကြိုးစားပါမယ်... "
                        f"⏱ စောင့်နေချိန် {fmt_time(time.monotonic() - started)}",
                        force=True,
                    )
                except Exception:
                    pass
            chunk = min(10.0, wait_left)
            await asyncio.sleep(chunk)
            wait_left -= chunk

    raise RuntimeError(
        f"Gemini {purpose} failed after {attempt_number} attempts: "
        f"{last_overload_error or last_error}"
    )


def _remember_script_preview(raw, *, purpose: str = "") -> None:
    """Keep a short, log-free record of what Gemini actually answered."""
    global _LAST_SCRIPT_RAW_PREVIEW
    text = str(raw or "").strip()
    if not text:
        _LAST_SCRIPT_RAW_PREVIEW = f"<empty response from {purpose or 'Gemini'}>"
        return
    collapsed = " ".join(text.split())
    _LAST_SCRIPT_RAW_PREVIEW = collapsed[:1200]


def _burmese_ratio(text: str) -> float:
    text = str(text or "")
    if not text:
        return 0.0
    burmese = sum(1 for ch in text if "\u1000" <= ch <= "\u109f")
    letters = sum(1 for ch in text if not ch.isspace())
    if not letters:
        return 0.0
    return burmese / float(letters)


def _scenes_from_plain_narration(
    text: str, chunk_duration: float, scene_count: int = 0
) -> list:
    """Turn a plain spoken retelling into timed scenes.

    Gemini sometimes refuses to answer inside a JSON envelope (empty or
    truncated object) while happily writing the same retelling as
    prose.  The prose is split on sentence boundaries, in order, and
    laid out over the chunk so the timeline and the 90% duration gate
    keep working.  Nothing is invented: only the text the model wrote
    is used, and only Burmese sentences survive.
    """
    body = str(text or "").strip()
    if not body:
        return []
    body = re.sub(r"```[a-zA-Z]*", " ", body)
    sentences = [
        part.strip()
        for part in re.split(r"(?<=[။.!?\u104a\u104b])\s+", body)
        if part.strip()
    ]
    kept = [
        part
        for part in sentences
        if _burmese_ratio(part) >= 0.35 and len(part) >= 2
    ]
    if not kept:
        kept = [line.strip() for line in body.splitlines() if line.strip()]
        kept = [line for line in kept if _burmese_ratio(line) >= 0.35]
    kept = [part for part in kept if part]
    if sum(len(part) for part in kept) < SCRIPT_PLAIN_TEXT_MIN_CHARS:
        return []
    try:
        wanted = int(scene_count or 0)
    except Exception:
        wanted = 0
    if wanted <= 0:
        wanted = max(1, min(12, int(round(len(kept) / 2.0)) or 1))
    wanted = max(1, min(wanted, len(kept)))
    total_chars = float(sum(len(part) for part in kept)) or 1.0
    per_scene = total_chars / float(wanted)
    groups: list = []
    current: list = []
    current_chars = 0
    for part in kept:
        current.append(part)
        current_chars += len(part)
        if (
            current_chars >= per_scene
            and len(groups) < wanted - 1
        ):
            groups.append(current)
            current = []
            current_chars = 0
    if current:
        groups.append(current)
    if not groups:
        return []
    duration = max(0.0, float(chunk_duration or 0.0))
    step = duration / float(len(groups)) if duration else 0.0
    scenes = []
    for index, group in enumerate(groups):
        start = round(index * step, 3)
        end = round(min(duration, (index + 1) * step), 3) if duration else 0.0
        scenes.append(
            {
                "start": start,
                "end": end,
                "burmese": " ".join(group),
            }
        )
    return scenes


def _prose_from_direct_payload(data) -> str:
    """Longest Burmese-ish string inside an unusable JSON answer."""
    candidates: list = []

    def _walk(value, depth: int = 0) -> None:
        if depth > 5:
            return
        if isinstance(value, str):
            if len(value) >= SCRIPT_PLAIN_TEXT_MIN_CHARS:
                candidates.append(value)
            return
        if isinstance(value, (list, tuple)):
            for item in value:
                _walk(item, depth + 1)
            return
        if isinstance(value, dict):
            for item in value.values():
                _walk(item, depth + 1)

    _walk(data)
    burmese = [text for text in candidates if _burmese_ratio(text) >= 0.35]
    pool = burmese or candidates
    if not pool:
        return ""
    return max(pool, key=len)


def _find_direct_scene_list(data, *, _depth: int = 0) -> list:
    if isinstance(data, list):
        return data
    if isinstance(data, str) and _depth < 3:
        try:
            return _find_direct_scene_list(
                _parse_gemini_json_text(data), _depth=_depth + 1
            )
        except Exception:
            return []
    if not isinstance(data, dict) or _depth > 5:
        return []

    if _scene_text_from_mapping(data) and not any(
        isinstance(data.get(key), list) for key in DIRECT_SCENE_LIST_KEYS
    ):
        return [data]

    for key in DIRECT_SCENE_LIST_KEYS:
        value = data.get(key)
        if isinstance(value, list) and value:
            return value
        if isinstance(value, (dict, str)):
            nested = _find_direct_scene_list(value, _depth=_depth + 1)
            if nested:
                return nested
    for value in data.values():
        if isinstance(value, (dict, list, str)):
            nested = _find_direct_scene_list(value, _depth=_depth + 1)
            if nested:
                return nested
    # Preserve an explicitly empty scenes list so callers can distinguish it
    # from unrelated metadata, while the searches above prefer usable data.
    return data.get("scenes") if isinstance(data.get("scenes"), list) else []


def _find_direct_payload_value(data, keys: tuple, *, _depth: int = 0):
    if isinstance(data, str) and _depth < 3:
        try:
            return _find_direct_payload_value(
                _parse_gemini_json_text(data), keys, _depth=_depth + 1
            )
        except Exception:
            return None
    if isinstance(data, list) and _depth < 5:
        for item in data:
            value = _find_direct_payload_value(item, keys, _depth=_depth + 1)
            if value not in (None, "", []):
                return value
        return None
    if not isinstance(data, dict) or _depth > 5:
        return None
    for key in keys:
        value = data.get(key)
        if value not in (None, "", []):
            return value
    for value in data.values():
        if isinstance(value, (dict, list, str)):
            nested = _find_direct_payload_value(value, keys, _depth=_depth + 1)
            if nested not in (None, "", []):
                return nested
    return None


def _direct_float_or_none(value):
    try:
        if value is None or str(value).strip() == "":
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _clean_story_text(value, limit: int = 240) -> str:
    text = " ".join(str(value or "").split()).strip()
    return text[: max(0, int(limit or 0))].strip()


def _clean_story_string_list(
    value,
    *,
    limit: int = 12,
    item_limit: int = 240,
) -> list:
    if isinstance(value, (str, int, float)):
        raw_values = [value]
    elif isinstance(value, list):
        raw_values = value
    else:
        raw_values = []
    cleaned = []
    seen = set()
    for item in raw_values:
        if isinstance(item, dict):
            raw_text = (
                item.get("name")
                or item.get("beat")
                or item.get("event")
                or item.get("fact")
                or item.get("text")
                or item.get("summary")
                or ""
            )
        else:
            raw_text = item
        text = _clean_story_text(raw_text, item_limit)
        key = _normalize_burmese_text(text)
        if text and key and key not in seen:
            cleaned.append(text)
            seen.add(key)
    return cleaned[: max(0, int(limit or 0))]


def _normalize_cast_name_source(value) -> str:
    raw = str(value or "").strip()
    lowered = raw.lower().replace("-", "_").replace(" ", "_")
    if not raw:
        return "unknown"
    if (
        "subtitle" in lowered
        or "caption" in lowered
        or lowered in {"cc", "burned_in", "burnedin"}
        or "စာတန်း" in raw
    ):
        return "subtitle"
    if (
        any(
            token in lowered
            for token in (
                "on_screen",
                "onscreen",
                "name_card",
                "namecard",
                "title_card",
                "lower_third",
                "screen_text",
                "overlay",
            )
        )
        or "အမည်ကတ်" in raw
        or "ဖန်သားပြင်" in raw
    ):
        return "on_screen"
    if (
        any(
            token in lowered
            for token in (
                "dialogue",
                "dialog",
                "spoken",
                "audio",
                "heard",
                "introduction",
                "address",
                "voice",
            )
        )
        or "စကားပြော" in raw
    ):
        return "dialogue"
    if (
        any(
            token in lowered
            for token in ("visual", "descriptive", "label", "appearance", "look")
        )
        or "ဖော်ပြချက်" in raw
    ):
        return "visual_label"
    return "unknown"


def _normalize_cast_confidence(value, name_source: str = "unknown") -> str:
    raw = str(value or "").strip()
    lowered = raw.lower().replace("-", "_").replace(" ", "_")
    if name_source == "visual_label" or any(
        token in lowered for token in ("descriptive", "label_only")
    ):
        return "descriptive"
    if any(
        token in lowered
        for token in ("uncertain", "unconfirmed", "low", "guess", "inferred")
    ):
        return "uncertain"
    if any(
        token in lowered
        for token in ("confirmed", "exact", "verified", "certain", "high", "known")
    ):
        return "confirmed"
    if name_source in ("subtitle", "on_screen"):
        return "confirmed"
    return "uncertain"


def _cast_evidence_rank(name_source: str, confidence: str) -> int:
    source = _normalize_cast_name_source(name_source)
    status = _normalize_cast_confidence(confidence, source)
    if status == "descriptive" or source == "visual_label":
        return 0
    if source in ("subtitle", "on_screen"):
        return 40
    if source == "dialogue" and status == "confirmed":
        return 30
    if source == "dialogue":
        return 20
    if status == "confirmed":
        return 20
    return 10


def _character_card_spoken_name(card) -> str:
    if isinstance(card, dict):
        return _clean_story_text(
            card.get("spoken_name")
            or card.get("canonical_name")
            or card.get("display_name")
            or card.get("name")
            or card.get("character")
            or card.get("title")
            or card.get("label")
            or "",
            80,
        )
    return _clean_story_text(card, 80)


def _character_card_short_name(card) -> str:
    """Approved routine form after the detailed first introduction.

    ``spoken_name`` remains the full canonical form.  A distinct
    ``short_name`` is allowed only when the source itself uses that
    shorter address form, or when a descriptive label has a compact
    unique core; otherwise the routine form is simply the spoken
    name.  Keeping the distinction prevents a long first-mention
    description from being repeated as if it were a natural name.
    """
    spoken_name = _character_card_spoken_name(card)
    if not isinstance(card, dict):
        return spoken_name
    short_name = _clean_story_text(
        card.get("short_name")
        or card.get("everyday_name")
        or card.get("routine_name")
        or card.get("address_form")
        or "",
        80,
    )
    return short_name or spoken_name


def _character_card_name_forms(card) -> list:
    forms = []
    for value in (
        _character_card_spoken_name(card),
        _character_card_short_name(card),
    ):
        if value and value not in forms:
            forms.append(value)
    return forms


def _character_card_gender(card) -> str:
    if not isinstance(card, dict):
        return ""
    for key in (
        "gender",
        "sex",
        "protagonist_gender",
        "narrator_gender",
        "pronoun",
        "self_pronoun",
        "protagonist_pronoun",
        "narrator_pronoun",
    ):
        gender = _normalize_protagonist_gender(card.get(key))
        if gender:
            return gender
    return ""


def _character_card_pronoun(card) -> str:
    if not isinstance(card, dict):
        return ""
    for key in (
        "pronoun",
        "self_pronoun",
        "protagonist_pronoun",
        "narrator_pronoun",
    ):
        pronoun = _normalize_protagonist_pronoun(card.get(key))
        if pronoun:
            return pronoun
    return _pronoun_for_gender(_character_card_gender(card))


def _find_character_card_for_name(cards, protagonist) -> dict:
    protagonist_key = _normalize_burmese_text(
        _clean_protagonist_name(protagonist)
    )
    if not protagonist_key:
        return {}
    for card in cards or []:
        if not isinstance(card, dict):
            continue
        keys = {
            _normalize_burmese_text(form)
            for form in _character_card_name_forms(card)
            if form
        }
        keys.add(_normalize_burmese_text(card.get("source_name") or ""))
        keys.add(_normalize_burmese_text(card.get("name") or ""))
        keys.update(
            _normalize_burmese_text(alias)
            for alias in (card.get("aliases") or [])
        )
        if protagonist_key in keys:
            return card
    return {}


def _protagonist_gender_and_pronoun(
    *sources,
    protagonist: str = "",
    character_cards=None,
) -> tuple:
    """Resolve the locked self-pronoun without guessing across windows."""

    gender = ""
    pronoun = ""
    cards = list(character_cards or [])
    protagonist_name = _clean_protagonist_name(protagonist)

    def inspect(value, depth=0):
        nonlocal gender, pronoun, protagonist_name
        if depth > 3 or not isinstance(value, dict):
            return
        if not protagonist_name:
            protagonist_name = _clean_protagonist_name(
                value.get("protagonist") or value.get("main_character") or ""
            )
        for key in (
            "protagonist_gender",
            "narrator_gender",
            "main_character_gender",
        ):
            if not gender:
                gender = _normalize_protagonist_gender(value.get(key))
        for key in (
            "protagonist_pronoun",
            "narrator_pronoun",
            "self_pronoun",
        ):
            if not pronoun:
                pronoun = _normalize_protagonist_pronoun(value.get(key))
        for key in ("character_cards", "characters"):
            values = value.get(key)
            if isinstance(values, list):
                cards.extend(item for item in values if isinstance(item, dict))
        for key in ("story_map", "story_bible", "story_context", "context"):
            inspect(value.get(key), depth + 1)

    for source in sources:
        inspect(source)
    if (not gender or not pronoun) and protagonist_name and cards:
        card = _find_character_card_for_name(cards, protagonist_name)
        if card:
            if not gender:
                gender = _character_card_gender(card)
            if not pronoun:
                pronoun = _character_card_pronoun(card)
    if pronoun:
        gender = _gender_from_pronoun(pronoun)
    elif gender:
        pronoun = _pronoun_for_gender(gender)
    return gender, pronoun


def _spoken_name_form_is_long(value) -> bool:
    """Whether a name/label reads like a clause, not a routine name."""
    compact = "".join(
        _normalize_burmese_text(value or "").split()
    ).strip("«»\"'()[]{}")
    if len(compact) >= 22:
        return True
    clause_markers = (
        "ကိုင်ထားတဲ့",
        "ဝတ်ထားတဲ့",
        "နေတဲ့",
        "ဖြစ်တဲ့",
        "လုပ်တဲ့",
        "ရှိတဲ့",
        "ပါတဲ့",
    )
    return len(compact) >= 14 and any(
        marker in compact for marker in clause_markers
    )


def _clean_protagonist_name(value) -> str:
    if isinstance(value, dict):
        value = (
            value.get("spoken_name")
            or value.get("canonical_name")
            or value.get("display_name")
            or value.get("name")
            or value.get("protagonist")
            or ""
        )
    return _clean_story_text(value, 100)


def _normalize_character_cards(value, character_names=None) -> list:
    """Canonical cast registry shared across every narration window.

    ``spoken_name`` is the full Burmese form used for a person's
    first detailed introduction; an optional distinct ``short_name``
    is the only other routine form the narrator may use afterwards.
    A readable subtitle/name-card name is the strongest
    evidence; unsure later guesses never replace an established form.
    If no reliable name exists, the stable descriptive label itself is
    the spoken form.  Original names and spelling variants are kept
    only as non-spoken aliases so later windows can recognise that
    they refer to the same person instead of inventing a new identity.
    """
    raw_values = value if isinstance(value, list) else []
    cards = []
    ambiguous_alias_keys = set()

    def first_value(item, keys):
        for key in keys:
            candidate = item.get(key)
            if candidate not in (None, "", []):
                return candidate
        return ""

    def first_text(item, keys, limit):
        return _clean_story_text(first_value(item, keys), limit)

    def alias_values(item, spoken_name, source_name="", short_name=""):
        aliases = []
        for key in (
            "aliases",
            "nicknames",
            "variants",
            "variant_spellings",
            "also_called",
            "other_names",
        ):
            aliases.extend(
                _clean_story_string_list(
                    item.get(key) or [], limit=8, item_limit=60
                )
            )
        if source_name:
            aliases.append(source_name)
        spoken_key = _normalize_burmese_text(spoken_name)
        short_key = _normalize_burmese_text(short_name)
        return [
            alias
            for alias in _clean_story_string_list(
                aliases, limit=8, item_limit=60
            )
            if _normalize_burmese_text(alias) not in {spoken_key, short_key}
        ]

    def candidate_from_item(item):
        if not isinstance(item, dict):
            spoken_name = _clean_story_text(item, 80)
            if not spoken_name:
                return None
            return {
                "name": spoken_name,
                "spoken_name": spoken_name,
                "source_name": "",
                "gender": "",
                "role": "",
                "relation": "",
                "introduction": "",
                "identity_anchor": "",
                "short_name": "",
                "name_evidence_text": "",
                "name_reveal_bridge": "",
                "goal": "",
                "motivation": "",
                "aliases": [],
                "name_source": "unknown",
                "confidence": "uncertain",
                "visual_cue": "",
            }
        spoken_name = _character_card_spoken_name(item)
        if not spoken_name:
            return None
        source_name = first_text(
            item,
            (
                "source_name",
                "original_name",
                "name_in_source",
                "subtitle_name",
                "original",
                "source_text",
            ),
            100,
        )
        name_source = _normalize_cast_name_source(
            first_value(
                item,
                ("name_source", "source", "evidence_source", "name_evidence"),
            )
        )
        confidence = _normalize_cast_confidence(
            first_value(
                item,
                ("confidence", "name_confidence", "certainty", "status"),
            ),
            name_source,
        )
        supplied_short_name = first_text(
            item,
            (
                "short_name",
                "everyday_name",
                "routine_name",
                "address_form",
                "short_form",
            ),
            80,
        )
        # Blank means "use spoken_name routinely".  A generic pronoun
        # or kinship word is not a unique routine name, even when the
        # characters happen to address the person that way in dialogue.
        if (
            not supplied_short_name
            or _normalize_burmese_text(supplied_short_name)
            == _normalize_burmese_text(spoken_name)
            or _normalize_burmese_text(supplied_short_name)
            in _CAST_GENERIC_ALIASES
        ):
            supplied_short_name = ""
        identity_anchor_value = first_text(
            item,
            (
                "identity_anchor",
                "reintroduction",
                "reintroduction_phrase",
                "recognition_phrase",
                "reminder_phrase",
                "anchor_phrase",
            ),
            180,
        )
        # For a descriptive identity, a materially shorter anchor can
        # be the compact routine label.  This derivation is deliberately
        # not used for confirmed names: their anchor is a relationship
        # reminder, not a nickname.
        if (
            not supplied_short_name
            and confidence == "descriptive"
            and _spoken_name_form_is_long(spoken_name)
            and identity_anchor_value
            and len(_normalize_burmese_text(identity_anchor_value))
            + 4
            <= len(_normalize_burmese_text(spoken_name))
            and _normalize_burmese_text(identity_anchor_value)
            not in _CAST_GENERIC_ALIASES
        ):
            supplied_short_name = identity_anchor_value
        return {
            "name": spoken_name,
            "spoken_name": spoken_name,
            "source_name": source_name,
            "gender": _normalize_protagonist_gender(
                first_value(
                    item,
                    (
                        "gender",
                        "sex",
                        "protagonist_gender",
                        "narrator_gender",
                        "pronoun",
                        "self_pronoun",
                        "protagonist_pronoun",
                        "narrator_pronoun",
                    ),
                )
            ),
            "role": first_text(item, ("role", "identity"), 140),
            "relation": first_text(
                item,
                (
                    "relation",
                    "relationship",
                    "relation_to_protagonist",
                    "relationship_to_protagonist",
                ),
                180,
            ),
            # The exact Burmese phrase used the first time this person
            # is mentioned (name/label + role + relation/group).  It
            # is what lets an audio-only listener remember who is who
            # instead of hearing an endless stream of bare labels.
            "introduction": first_text(
                item,
                (
                    "introduction",
                    "intro",
                    "first_mention",
                    "first_introduction",
                    "intro_phrase",
                ),
                240,
            ),
            # A short reminder used when the person returns after an
            # absence ("Mary's elder brother Aiden"), so re-entry does
            # not depend on the listener remembering a bare name from
            # several scenes/windows earlier.
            "identity_anchor": identity_anchor_value,
            # Distinct routine form only; blank means spoken_name.
            "short_name": supplied_short_name,
            # Exact readable subtitle/name-card/dialogue wording that
            # supports the name.  This is evidence metadata, never a
            # form the Burmese narrator should read aloud verbatim.
            "name_evidence_text": first_text(
                item,
                (
                    "name_evidence_text",
                    "evidence_text",
                    "name_quote",
                    "evidence_quote",
                    "evidence",
                ),
                240,
            ),
            # One-time Burmese bridge for a deliberate later reveal:
            # previous descriptive label -> confirmed real name.
            "name_reveal_bridge": first_text(
                item,
                (
                    "name_reveal_bridge",
                    "reveal_bridge",
                    "name_bridge",
                    "rename_bridge",
                ),
                240,
            ),
            "goal": first_text(
                item,
                ("goal", "current_goal", "objective", "want", "wants"),
                160,
            ),
            "motivation": first_text(
                item,
                ("motivation", "reason", "why", "driving_reason"),
                200,
            ),
            "aliases": alias_values(
                item, spoken_name, source_name, supplied_short_name
            ),
            "name_source": name_source,
            "confidence": confidence,
            "visual_cue": first_text(
                item,
                ("visual_cue", "appearance", "visual_identity", "description"),
                180,
            ),
        }

    def card_rank(card):
        return _cast_evidence_rank(
            card.get("name_source") or "unknown",
            card.get("confidence") or "uncertain",
        )

    def identity_keys(card):
        keys = set()
        spoken_key = _normalize_burmese_text(_character_card_spoken_name(card))
        if spoken_key:
            keys.add(spoken_key)
        source_key = _normalize_burmese_text(card.get("source_name") or "")
        if source_key:
            keys.add(source_key)
        for item in card.get("aliases") or []:
            key = _normalize_burmese_text(item)
            # An alias claimed for two different spoken identities is
            # evidence of ambiguity, not evidence that the people are
            # the same person.  Never let it collapse two cast cards.
            if key and key not in ambiguous_alias_keys:
                keys.add(key)
        return keys

    def add_alias(card, alias):
        clean_alias = _clean_story_text(alias, 60)
        if not clean_alias:
            return
        spoken_key = _normalize_burmese_text(_character_card_spoken_name(card))
        short_key = _normalize_burmese_text(card.get("short_name") or "")
        alias_key = _normalize_burmese_text(clean_alias)
        if not alias_key or alias_key in {spoken_key, short_key}:
            return
        existing_keys = {
            _normalize_burmese_text(item) for item in (card.get("aliases") or [])
        }
        if alias_key not in existing_keys and len(card.get("aliases") or []) < 8:
            card.setdefault("aliases", []).append(clean_alias)

    def find_match(candidate):
        candidate_keys = identity_keys(candidate)
        candidate_spoken_key = _normalize_burmese_text(
            _character_card_spoken_name(candidate)
        )
        candidate_visual = _normalize_burmese_text(candidate.get("visual_cue") or "")
        candidate_rank = card_rank(candidate)
        for existing in cards:
            if not (candidate_keys & identity_keys(existing)):
                continue
            existing_spoken_key = _normalize_burmese_text(
                _character_card_spoken_name(existing)
            )
            existing_visual = _normalize_burmese_text(
                existing.get("visual_cue") or ""
            )
            # Two independently confirmed identities with different
            # visual identities must not be collapsed just because a
            # model repeated a nickname/source name on both cards.
            if (
                candidate_spoken_key != existing_spoken_key
                and candidate_rank >= 30
                and card_rank(existing) >= 30
                and candidate_visual
                and existing_visual
                and candidate_visual != existing_visual
            ):
                continue
            return existing
        candidate_role = _normalize_burmese_text(candidate.get("role") or "")
        if candidate_visual:
            for existing in cards:
                existing_spoken_key = _normalize_burmese_text(
                    _character_card_spoken_name(existing)
                )
                # A shared outfit/visual cue can upgrade a descriptive
                # label to a confirmed name, but it is not enough to
                # merge two already-confirmed different people.
                if (
                    candidate_spoken_key != existing_spoken_key
                    and candidate_rank >= 30
                    and card_rank(existing) >= 30
                ):
                    continue
                existing_visual = _normalize_burmese_text(
                    existing.get("visual_cue") or ""
                )
                existing_role = _normalize_burmese_text(existing.get("role") or "")
                if existing_visual == candidate_visual and (
                    not candidate_role
                    or not existing_role
                    or existing_role == candidate_role
                ):
                    return existing
        return None

    def merge_candidate(candidate):
        existing = find_match(candidate)
        if existing is None:
            cards.append(candidate)
            return
        old_spoken_name = _character_card_spoken_name(existing)
        candidate_spoken_name = _character_card_spoken_name(candidate)
        existing_rank = _cast_evidence_rank(
            existing.get("name_source") or "unknown",
            existing.get("confidence") or "uncertain",
        )
        candidate_rank = _cast_evidence_rank(
            candidate.get("name_source") or "unknown",
            candidate.get("confidence") or "uncertain",
        )
        upgraded = False
        old_short_name = str(existing.get("short_name") or "").strip()
        if _normalize_burmese_text(candidate_spoken_name) != _normalize_burmese_text(
            old_spoken_name
        ):
            if candidate_rank > existing_rank and candidate_rank >= 30:
                existing["name"] = candidate_spoken_name
                existing["spoken_name"] = candidate_spoken_name
                existing["name_source"] = candidate.get("name_source") or "unknown"
                existing["confidence"] = candidate.get("confidence") or "uncertain"
                if candidate.get("source_name"):
                    existing["source_name"] = candidate["source_name"]
                existing["aliases"] = [
                    alias
                    for alias in (existing.get("aliases") or [])
                    if _normalize_burmese_text(alias)
                    != _normalize_burmese_text(candidate_spoken_name)
                ]
                existing["short_name"] = candidate.get("short_name") or ""
                if old_short_name:
                    add_alias(existing, old_short_name)
                add_alias(existing, old_spoken_name)
                if candidate.get("name_evidence_text"):
                    existing["name_evidence_text"] = candidate[
                        "name_evidence_text"
                    ]
                if candidate.get("name_reveal_bridge"):
                    existing["name_reveal_bridge"] = candidate[
                        "name_reveal_bridge"
                    ]
                elif not existing.get("name_reveal_bridge") and existing_rank < 30:
                    # The listener has been following the old label.
                    # Give the narrator one explicit bridge instead of
                    # a sudden unexplained rename.
                    existing["name_reveal_bridge"] = (
                        f"အရင် {old_spoken_name} ရဲ့ အမည်က "
                        f"{candidate_spoken_name} ဖြစ်တယ်"
                    )
                upgraded = True
            else:
                add_alias(existing, candidate_spoken_name)
        if not upgraded and candidate_rank > existing_rank:
            existing["name_source"] = candidate.get("name_source") or "unknown"
            existing["confidence"] = candidate.get("confidence") or "uncertain"
            if candidate.get("source_name"):
                existing["source_name"] = candidate["source_name"]
        elif not existing.get("source_name") and candidate.get("source_name"):
            existing["source_name"] = candidate["source_name"]
        for key in (
            "gender",
            "role",
            "relation",
            "visual_cue",
            "introduction",
            "identity_anchor",
            "short_name",
            "name_evidence_text",
            "name_reveal_bridge",
        ):
            if candidate.get(key) and not existing.get(key):
                existing[key] = candidate[key]
        # A goal/motivation is current story state, not a permanent
        # identity fact: a later, equally-trusted card may update it
        # (the character now wants something else), while identity
        # fields above keep their first established value.
        for key in ("goal", "motivation"):
            if candidate.get(key) and (
                not existing.get(key) or candidate_rank >= existing_rank
            ):
                existing[key] = candidate[key]
        if candidate.get("source_name"):
            add_alias(existing, candidate["source_name"])
        for alias in candidate.get("aliases") or []:
            add_alias(existing, alias)
        current_key = _normalize_burmese_text(_character_card_spoken_name(existing))
        current_short_key = _normalize_burmese_text(
            existing.get("short_name") or ""
        )
        existing["aliases"] = [
            alias
            for alias in _clean_story_string_list(
                existing.get("aliases") or [], limit=8, item_limit=60
            )
            if _normalize_burmese_text(alias)
            not in {current_key, current_short_key}
        ][:8]

    candidates = []
    for item in raw_values:
        candidate = candidate_from_item(item)
        if candidate is not None:
            candidates.append(candidate)
    for name in _clean_story_string_list(
        character_names or [], limit=16, item_limit=80
    ):
        candidate = candidate_from_item(name)
        if candidate is not None:
            candidates.append(candidate)

    # First pass: detect aliases that the model assigned to more than
    # one spoken identity.  Kinship words and nicknames such as
    # ``ညီလေး`` are routinely reused for different people; treating
    # one as a unique identity key used to merge two confirmed cast
    # cards and then replace the second person's name with the first.
    alias_owner_keys = {}
    for candidate in candidates:
        spoken_key = _normalize_burmese_text(
            _character_card_spoken_name(candidate)
        )
        source_key = _normalize_burmese_text(candidate.get("source_name") or "")
        if not spoken_key:
            continue
        for alias in candidate.get("aliases") or []:
            alias_key = _normalize_burmese_text(alias)
            if alias_key and alias_key != source_key:
                alias_owner_keys.setdefault(alias_key, set()).add(spoken_key)
    ambiguous_alias_keys.update(
        alias_key
        for alias_key, owner_keys in alias_owner_keys.items()
        if len(owner_keys) > 1
    )
    if ambiguous_alias_keys:
        for candidate in candidates:
            candidate["aliases"] = [
                alias
                for alias in (candidate.get("aliases") or [])
                if _normalize_burmese_text(alias) not in ambiguous_alias_keys
            ]

    for candidate in candidates:
        merge_candidate(candidate)

    # Final safety pass after all merges/upgrades: a surviving card
    # may not claim an alias that is shared with another surviving
    # identity or that is itself another card's spoken name.  Keeping
    # such an alias would make later deterministic replacement pick
    # the wrong person even though the cards stayed separate.
    final_spoken_keys = {
        _normalize_burmese_text(form)
        for card in cards
        for form in _character_card_name_forms(card)
        if form
    }
    final_alias_owner_keys = {}
    for card in cards:
        spoken_key = _normalize_burmese_text(_character_card_spoken_name(card))
        if not spoken_key:
            continue
        for alias in card.get("aliases") or []:
            alias_key = _normalize_burmese_text(alias)
            if alias_key:
                final_alias_owner_keys.setdefault(alias_key, set()).add(spoken_key)
    for card in cards:
        spoken_key = _normalize_burmese_text(_character_card_spoken_name(card))
        card["aliases"] = [
            alias
            for alias in (card.get("aliases") or [])
            if (
                _normalize_burmese_text(alias)
                and _normalize_burmese_text(alias) != spoken_key
                and _normalize_burmese_text(alias) not in final_spoken_keys
                and len(
                    final_alias_owner_keys.get(
                        _normalize_burmese_text(alias), set()
                    )
                )
                <= 1
            )
        ]
    # A routine short form is useful only when it points to one
    # person.  If two people share it (or it is another person's full
    # spoken name), retire it rather than letting narration swap the
    # wrong identity in later windows.
    short_owner_keys = {}
    final_spoken_only_keys = {
        _normalize_burmese_text(_character_card_spoken_name(card))
        for card in cards
        if _character_card_spoken_name(card)
    }
    for card in cards:
        spoken_key = _normalize_burmese_text(_character_card_spoken_name(card))
        short_key = _normalize_burmese_text(card.get("short_name") or "")
        if spoken_key and short_key:
            short_owner_keys.setdefault(short_key, set()).add(spoken_key)
    for card in cards:
        short_key = _normalize_burmese_text(card.get("short_name") or "")
        if short_key and (
            len(short_owner_keys.get(short_key, set())) > 1
            or short_key in final_spoken_only_keys
        ):
            card["short_name"] = ""
    return cards[:16]


def _normalize_story_beats(value, *, chunk_duration: float = 0.0) -> list:
    raw_values = value if isinstance(value, list) else []
    duration = max(0.0, float(chunk_duration or 0))
    beats = []
    seen = set()
    # A beat may arrive as one sentence or as structured parts
    # (trigger -> action/dialogue -> reaction -> result).  Keeping
    # the parts lets later prompts and the clarity gate see *why* an
    # event happens and how people responded, instead of a flat
    # "X did Y" caption that narration then copies as a mere report.
    beat_part_aliases = (
        ("trigger", ("trigger", "cause", "reason", "because", "setup")),
        ("dialogue", ("dialogue", "dialogue_meaning", "exchange", "said")),
        ("reaction", ("reaction", "response", "decision", "judgement", "judgment")),
        ("result", ("result", "outcome", "consequence", "next_problem", "next_step")),
        (
            "visible_text",
            (
                "visible_text",
                "visible_text_meaning",
                "on_screen_text_meaning",
                "screen_text_meaning",
            ),
        ),
        (
            "why_it_matters",
            ("why_it_matters", "importance", "stakes", "why_important"),
        ),
    )
    for item in raw_values:
        parts = {}
        if isinstance(item, dict):
            for output_key, aliases in beat_part_aliases:
                for alias in aliases:
                    part_text = _clean_story_text(item.get(alias), 240)
                    if part_text:
                        parts[output_key] = part_text
                        break
            text = _clean_story_text(
                item.get("beat")
                or item.get("event")
                or item.get("summary")
                or item.get("text")
                or item.get("description")
                or "",
                320,
            )
            if not text and parts:
                text = _clean_story_text(
                    " — ".join(
                        parts[key]
                        for key in (
                            "trigger",
                            "dialogue",
                            "reaction",
                            "result",
                            "visible_text",
                            "why_it_matters",
                        )
                        if parts.get(key)
                    ),
                    320,
                )
            start = _direct_float_or_none(
                item.get("start", item.get("start_time", item.get("start_seconds")))
            )
            end = _direct_float_or_none(
                item.get("end", item.get("end_time", item.get("end_seconds")))
            )
        else:
            text = _clean_story_text(item, 320)
            start = None
            end = None
        if not text:
            continue
        beat = {"beat": text}
        beat.update(parts)
        if start is not None:
            start = max(0.0, float(start))
            if duration > 0:
                start = min(duration, start)
            beat["start"] = round(start, 3)
        if end is not None:
            end = max(0.0, float(end))
            if duration > 0:
                end = min(duration, end)
            if beat.get("start") is None or end > float(beat["start"]):
                beat["end"] = round(end, 3)
        key = (
            _normalize_burmese_text(text),
            beat.get("start"),
            beat.get("end"),
        )
        if key not in seen:
            beats.append(beat)
            seen.add(key)
    beats.sort(
        key=lambda b: (
            float(b.get("start"))
            if isinstance(b.get("start"), (int, float))
            else float("inf"),
            float(b.get("end"))
            if isinstance(b.get("end"), (int, float))
            else float("inf"),
        )
    )
    return beats[:32]


def _story_term_key(value) -> str:
    return " ".join(_normalize_burmese_text(value or "").lower().split()).strip()


def _normalize_story_terms(value) -> list:
    """Canonical glossary for story-specific words and world rules.

    Real system/cultivation/game recaps failed not only on people's
    names: words such as a system, a rank/quality, or "mortal" were
    merely transliterated and repeated with no explanation.  A term
    therefore locks three things together -- the one Burmese form the
    narrator may say, what it means *in this story*, and the exact
    plain-Burmese explanation to use at its first occurrence.
    Definitions are first-established facts; a later window may add
    aliases but must not silently redefine the term.
    """
    if isinstance(value, list):
        raw_values = value
    elif isinstance(value, (dict, str)):
        raw_values = [value]
    else:
        raw_values = []
    terms: list[dict] = []
    by_key: dict[str, dict] = {}

    def first_value(item, keys):
        for key in keys:
            candidate = item.get(key)
            if candidate not in (None, "", []):
                return candidate
        return ""

    def first_text(item, keys, limit):
        return _clean_story_text(first_value(item, keys), limit)

    for item in raw_values:
        if isinstance(item, dict):
            source_term = first_text(
                item,
                (
                    "source_term",
                    "original_term",
                    "term_in_source",
                    "source_text",
                    "original",
                ),
                120,
            )
            spoken_term = first_text(
                item,
                (
                    "spoken_term",
                    "burmese_term",
                    "canonical_term",
                    "term",
                    "name",
                ),
                120,
            )
            meaning = first_text(
                item,
                (
                    "meaning_in_story",
                    "meaning",
                    "definition",
                    "burmese_meaning",
                    "explanation",
                ),
                300,
            )
            first_explanation = first_text(
                item,
                (
                    "first_explanation",
                    "first_mention_explanation",
                    "explanation_phrase",
                    "intro_explanation",
                ),
                320,
            )
            category = first_text(
                item,
                ("category", "kind", "term_type", "type"),
                60,
            ).lower()
            evidence_source = _normalize_cast_name_source(
                first_value(
                    item,
                    ("evidence_source", "source", "term_source", "evidence"),
                )
            )
            aliases = []
            for key in ("aliases", "variants", "variant_spellings", "also_called"):
                aliases.extend(
                    _clean_story_string_list(
                        item.get(key) or [], limit=8, item_limit=80
                    )
                )
        else:
            source_term = ""
            spoken_term = _clean_story_text(item, 120)
            meaning = ""
            first_explanation = ""
            category = ""
            evidence_source = "unknown"
            aliases = []
        if not spoken_term and source_term:
            spoken_term = source_term
        if not spoken_term:
            continue
        if source_term and _story_term_key(source_term) != _story_term_key(spoken_term):
            aliases.append(source_term)
        aliases = [
            alias
            for alias in _clean_story_string_list(
                aliases, limit=8, item_limit=80
            )
            if _story_term_key(alias) != _story_term_key(spoken_term)
        ]
        candidate = {
            "spoken_term": spoken_term,
            "source_term": source_term,
            "meaning": meaning,
            "first_explanation": first_explanation,
            "category": category,
            "evidence_source": evidence_source,
            "aliases": aliases,
        }
        keys = {
            _story_term_key(value)
            for value in [spoken_term, source_term, *aliases]
            if _story_term_key(value)
        }
        existing = next(
            (by_key[key] for key in keys if key in by_key),
            None,
        )
        if existing is None:
            terms.append(candidate)
            existing = candidate
        else:
            for key in (
                "source_term",
                "meaning",
                "first_explanation",
                "category",
            ):
                if candidate.get(key) and not existing.get(key):
                    existing[key] = candidate[key]
            if existing.get("evidence_source") in ("", "unknown") and candidate.get(
                "evidence_source"
            ):
                existing["evidence_source"] = candidate["evidence_source"]
            existing_alias_keys = {
                _story_term_key(alias)
                for alias in (existing.get("aliases") or [])
            }
            for alias in aliases:
                alias_key = _story_term_key(alias)
                if alias_key and alias_key not in existing_alias_keys:
                    existing.setdefault("aliases", []).append(alias)
                    existing_alias_keys.add(alias_key)
            existing["aliases"] = (existing.get("aliases") or [])[:8]
        for key in keys:
            by_key[key] = existing
    return terms[:16]


def _normalize_visible_text_kind(value) -> str:
    raw = _clean_story_text(value, 60)
    lowered = raw.lower().replace("-", "_").replace(" ", "_")
    if any(token in lowered for token in ("system", "status", "panel", "window")):
        return "system_panel"
    if any(token in lowered for token in ("name_card", "namecard", "character_name")):
        return "name_card"
    if any(token in lowered for token in ("subtitle", "caption")):
        return "subtitle"
    if any(token in lowered for token in ("document", "letter", "paper", "note")):
        return "document"
    if any(token in lowered for token in ("sign", "board", "plaque")):
        return "sign"
    if any(token in lowered for token in ("chat", "message", "phone")):
        return "message"
    if "title" in lowered:
        return "title_card"
    return lowered or "visible_text"


def _normalize_visible_texts(value, *, chunk_duration: float = 0.0) -> list:
    """Important readable on-screen text and its Burmese meaning.

    This is deliberately not a transcript of every subtitle line.  It
    is the ledger for name cards, system/status panels, signs,
    documents, title cards and messages whose meaning an audio-only
    listener cannot recover from dialogue alone.  Keeping the source
    text beside the Burmese meaning lets prompts/QA reconcile the
    narration with what was actually written on screen.
    """
    if isinstance(value, list):
        raw_values = value
    elif isinstance(value, (dict, str)):
        raw_values = [value]
    else:
        raw_values = []
    duration = max(0.0, float(chunk_duration or 0))
    texts = []
    seen = set()
    for item in raw_values:
        if isinstance(item, dict):
            source_text = _clean_story_text(
                item.get("source_text")
                or item.get("original_text")
                or item.get("chinese_text")
                or item.get("text")
                or item.get("original")
                or "",
                260,
            )
            meaning = _clean_story_text(
                item.get("burmese_meaning")
                or item.get("meaning")
                or item.get("translation")
                or item.get("spoken_meaning")
                or item.get("meaning_in_burmese")
                or "",
                320,
            )
            kind = _normalize_visible_text_kind(
                item.get("kind") or item.get("type") or item.get("text_type")
            )
            related_character = _clean_story_text(
                item.get("related_character")
                or item.get("character")
                or item.get("related_to")
                or "",
                100,
            )
            narrate_raw = None
            for key in ("narrate", "must_narrate", "should_narrate", "important"):
                if key in item:
                    narrate_raw = item.get(key)
                    break
            if isinstance(narrate_raw, bool):
                narrate = narrate_raw
            elif narrate_raw is None:
                narrate = True
            else:
                narrate = str(narrate_raw).strip().lower() not in {
                    "0",
                    "false",
                    "no",
                    "none",
                }
            start = _direct_float_or_none(
                item.get("start", item.get("start_time", item.get("start_seconds")))
            )
            end = _direct_float_or_none(
                item.get("end", item.get("end_time", item.get("end_seconds")))
            )
        else:
            source_text = _clean_story_text(item, 260)
            meaning = ""
            kind = "visible_text"
            related_character = ""
            narrate = True
            start = None
            end = None
        if not source_text and not meaning:
            continue
        entry = {
            "source_text": source_text,
            "burmese_meaning": meaning,
            "kind": kind,
            "narrate": bool(narrate),
        }
        if related_character:
            entry["related_character"] = related_character
        if start is not None:
            start = max(0.0, float(start))
            if duration > 0:
                start = min(duration, start)
            entry["start"] = round(start, 3)
        if end is not None:
            end = max(0.0, float(end))
            if duration > 0:
                end = min(duration, end)
            if entry.get("start") is None or end > float(entry["start"]):
                entry["end"] = round(end, 3)
        key = (
            entry.get("start"),
            _story_term_key(source_text),
            _normalize_burmese_text(meaning),
        )
        if key in seen:
            continue
        seen.add(key)
        texts.append(entry)
    texts.sort(
        key=lambda item: (
            float(item.get("start"))
            if isinstance(item.get("start"), (int, float))
            else float("inf"),
            float(item.get("end"))
            if isinstance(item.get("end"), (int, float))
            else float("inf"),
        )
    )
    return texts[:16]


def _normalize_story_map(value, *, chunk_duration: float = 0.0) -> dict:
    """Normalize the model's non-spoken story plan for one window."""
    if not isinstance(value, dict):
        return {}
    cards = _normalize_character_cards(
        value.get("character_cards") or value.get("characters") or [],
    )
    beats = _normalize_story_beats(
        value.get("beats")
        or value.get("story_beats")
        or value.get("events")
        or [],
        chunk_duration=chunk_duration,
    )
    terms = _normalize_story_terms(
        value.get("terms")
        or value.get("glossary")
        or value.get("world_terms")
        or value.get("key_terms")
        or []
    )
    visible_texts = _normalize_visible_texts(
        value.get("visible_texts")
        or value.get("on_screen_texts")
        or value.get("screen_texts")
        or value.get("visible_text")
        or value.get("on_screen_text")
        or [],
        chunk_duration=chunk_duration,
    )
    # A readable name card is evidence, not just another visible-text
    # fact.  Link it back to Cast Lock so later windows know *why* a
    # Burmese spoken form is trusted; if the model recorded the card
    # but forgot the character card, create the minimal card from the
    # ledger instead of leaving the person outside Cast Lock.
    for entry in visible_texts:
        if entry.get("kind") != "name_card":
            continue
        source_text = str(entry.get("source_text") or "").strip()
        related_character = str(entry.get("related_character") or "").strip()
        meaning = str(entry.get("burmese_meaning") or "").strip()
        if not source_text or not related_character:
            continue
        related_key = _normalize_burmese_text(related_character)
        matched_card = None
        for card in cards:
            form_keys = {
                _normalize_burmese_text(form)
                for form in _character_card_name_forms(card)
                if form
            }
            form_keys.add(_normalize_burmese_text(card.get("source_name") or ""))
            form_keys.update(
                _normalize_burmese_text(alias)
                for alias in (card.get("aliases") or [])
            )
            spoken_name = _character_card_spoken_name(card)
            if related_key in form_keys or (
                related_key == _normalize_burmese_text(source_text)
                and spoken_name
                and spoken_name in meaning
            ):
                matched_card = card
                break
        if matched_card is not None:
            if not matched_card.get("name_evidence_text"):
                matched_card["name_evidence_text"] = source_text
            if not matched_card.get("source_name"):
                matched_card["source_name"] = source_text
            if (
                _normalize_burmese_text(matched_card.get("source_name") or "")
                == _normalize_burmese_text(source_text)
                and matched_card.get("confidence") != "descriptive"
                and not _cast_label_is_generic(
                    _character_card_spoken_name(matched_card)
                )
            ):
                matched_card["name_source"] = "on_screen"
                matched_card["confidence"] = "confirmed"
        elif any("\u1000" <= char <= "\u109f" for char in related_character):
            generic_related = _cast_label_is_generic(related_character)
            cards = _normalize_character_cards(
                cards
                + [
                    {
                        "spoken_name": related_character,
                        "source_name": source_text,
                        "name_source": (
                            "visual_label" if generic_related else "on_screen"
                        ),
                        "confidence": (
                            "descriptive" if generic_related else "confirmed"
                        ),
                        "name_evidence_text": source_text,
                    }
                ]
            )
    story_map = {}
    if cards:
        story_map["character_cards"] = cards
    if beats:
        story_map["beats"] = beats
    if terms:
        story_map["terms"] = terms
    if visible_texts:
        story_map["visible_texts"] = visible_texts
    for output_key, aliases in (
        ("current_goal", ("current_goal", "goal", "objective")),
        ("current_conflict", ("current_conflict", "conflict", "problem")),
        (
            "conflict_stakes",
            (
                "conflict_stakes",
                "stakes",
                "what_is_at_stake",
                "consequence",
                "consequences",
                "risk",
            ),
        ),
        (
            "central_question",
            (
                "central_question",
                "main_question",
                "unresolved_question",
                "ending_question",
            ),
        ),
        ("setting", ("setting", "location", "place")),
    ):
        for alias in aliases:
            text = _clean_story_text(value.get(alias), 240)
            if text:
                story_map[output_key] = text
                break
    open_threads = _clean_story_string_list(
        value.get("open_threads")
        or value.get("unresolved_questions")
        or value.get("mysteries")
        or [],
        limit=10,
        item_limit=240,
    )
    if open_threads:
        story_map["open_threads"] = open_threads
    important_facts = _clean_story_string_list(
        value.get("important_facts") or value.get("facts_to_remember") or [],
        limit=16,
        item_limit=240,
    )
    if important_facts:
        story_map["important_facts"] = important_facts
    protagonist_gender, protagonist_pronoun = _protagonist_gender_and_pronoun(
        value,
        protagonist=value.get("protagonist") or value.get("main_character") or "",
        character_cards=cards,
    )
    if protagonist_gender:
        story_map["protagonist_gender"] = protagonist_gender
    if protagonist_pronoun:
        story_map["protagonist_pronoun"] = protagonist_pronoun
    return story_map


def _merge_story_maps(*maps, chunk_duration: float = 0.0) -> dict:
    normalized = [
        _normalize_story_map(item, chunk_duration=chunk_duration)
        for item in maps
        if isinstance(item, dict)
    ]
    if not normalized:
        return {}
    merged_cards = _normalize_character_cards(
        [
            card
            for story_map in normalized
            for card in (story_map.get("character_cards") or [])
        ]
    )
    merged_beats = _normalize_story_beats(
        [
            beat
            for story_map in normalized
            for beat in (story_map.get("beats") or [])
        ],
        chunk_duration=chunk_duration,
    )
    merged = {}
    if merged_cards:
        merged["character_cards"] = merged_cards
    if merged_beats:
        merged["beats"] = merged_beats
    merged_terms = _normalize_story_terms(
        [
            term
            for story_map in normalized
            for term in (story_map.get("terms") or [])
        ]
    )
    if merged_terms:
        merged["terms"] = merged_terms
    merged_visible_texts = _normalize_visible_texts(
        [
            item
            for story_map in normalized
            for item in (story_map.get("visible_texts") or [])
        ],
        chunk_duration=chunk_duration,
    )
    if merged_visible_texts:
        merged["visible_texts"] = merged_visible_texts
    for key in (
        "current_goal",
        "current_conflict",
        "conflict_stakes",
        "central_question",
        "setting",
    ):
        for story_map in reversed(normalized):
            if story_map.get(key):
                merged[key] = story_map[key]
                break
    for key in ("protagonist_gender", "protagonist_pronoun"):
        for story_map in normalized:
            if story_map.get(key):
                merged[key] = story_map[key]
                break
    for key, limit in (("open_threads", 12), ("important_facts", 20)):
        values = _clean_story_string_list(
            [
                item
                for story_map in normalized
                for item in (story_map.get(key) or [])
            ],
            limit=limit,
            item_limit=240,
        )
        if values:
            merged[key] = values
    return merged


def _story_context_from_story_map(
    story_map,
    *,
    last_scene: str = "",
    protagonist: str = "",
    narrator_perspective: str = NARRATOR_PERSPECTIVE,
) -> dict:
    normalized_map = _normalize_story_map(story_map)
    clean_protagonist = _clean_protagonist_name(
        protagonist
        or (story_map.get("protagonist") if isinstance(story_map, dict) else "")
    )
    # The recap narrator is the protagonist.  Perspective is fixed,
    # but the protagonist's own Burmese pronoun must be carried as
    # locked story state so it cannot drift between windows.
    clean_perspective = NARRATOR_PERSPECTIVE
    if not normalized_map and not last_scene and not clean_protagonist:
        return {}
    cards = normalized_map.get("character_cards") or []
    protagonist_gender, protagonist_pronoun = _protagonist_gender_and_pronoun(
        normalized_map,
        story_map if isinstance(story_map, dict) else {},
        protagonist=clean_protagonist,
        character_cards=cards,
    )
    beats = []
    for item in normalized_map.get("beats") or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get("beat") or "")
        for key in ("visible_text", "why_it_matters"):
            detail = str(item.get(key) or "").strip()
            if detail and _normalize_burmese_text(detail) not in _normalize_burmese_text(text):
                text = f"{text}; {detail}" if text else detail
        beats.append(text)
    return {
        "characters": [
            _character_card_spoken_name(card)
            for card in cards
            if _character_card_spoken_name(card)
        ],
        "character_cards": cards,
        "terms": normalized_map.get("terms") or [],
        "summary": "",
        "story_beats": _clean_story_string_list(beats, limit=24, item_limit=320),
        "current_goal": normalized_map.get("current_goal") or "",
        "current_conflict": normalized_map.get("current_conflict") or "",
        "conflict_stakes": normalized_map.get("conflict_stakes") or "",
        "central_question": normalized_map.get("central_question") or "",
        "setting": normalized_map.get("setting") or "",
        "open_threads": normalized_map.get("open_threads") or [],
        "important_facts": normalized_map.get("important_facts") or [],
        "last_scene": _clean_story_text(last_scene, 600),
        "protagonist": clean_protagonist,
        "protagonist_gender": protagonist_gender,
        "protagonist_pronoun": protagonist_pronoun,
        "narrator_perspective": clean_perspective,
    }


def _normalize_story_context(value, *, scenes=None, derive_beats: bool = False) -> dict:
    """Canonical, cumulative story memory shared by direct and worker jobs."""
    raw = value if isinstance(value, dict) else {}
    nested_map = _normalize_story_map(
        raw.get("story_map") or raw.get("story_bible") or {}
    )
    map_context = _story_context_from_story_map(nested_map)
    raw_characters = raw.get("characters") or []
    character_names = []
    raw_cards = list(raw.get("character_cards") or [])
    if isinstance(raw_characters, list):
        for item in raw_characters:
            if isinstance(item, dict):
                raw_cards.append(item)
                name = _character_card_spoken_name(item)
            else:
                name = _clean_story_text(item, 80)
            if name:
                character_names.append(name)
    character_names = _clean_story_string_list(
        character_names + (map_context.get("characters") or []),
        limit=16,
        item_limit=80,
    )
    cards = _normalize_character_cards(
        raw_cards + (map_context.get("character_cards") or []),
        character_names=character_names,
    )
    if cards:
        character_names = _clean_story_string_list(
            [_character_card_spoken_name(card) for card in cards],
            limit=16,
            item_limit=80,
        )
    beats = []
    for key in ("story_beats", "beats", "previous_beats", "events"):
        beats.extend(
            _clean_story_string_list(raw.get(key) or [], limit=32, item_limit=320)
        )
    beats.extend(map_context.get("story_beats") or [])
    beats = _clean_story_string_list(beats, limit=32, item_limit=320)
    if derive_beats and not beats and scenes:
        derived = []
        for scene in scenes:
            text = _clean_story_text(
                scene.get("burmese") if isinstance(scene, dict) else "",
                220,
            )
            if text:
                derived.append(text)
        beats = _clean_story_string_list(derived, limit=16, item_limit=220)

    protagonist = _clean_protagonist_name(
        raw.get("protagonist") or raw.get("main_character") or ""
    )
    protagonist_gender, protagonist_pronoun = _protagonist_gender_and_pronoun(
        raw,
        map_context,
        protagonist=protagonist,
        character_cards=cards,
    )
    term_values = []
    for key in ("terms", "glossary", "world_terms", "key_terms"):
        value = raw.get(key)
        if isinstance(value, list):
            term_values.extend(value)
        elif value not in (None, ""):
            term_values.append(value)
    terms = _normalize_story_terms(
        term_values + list(map_context.get("terms") or [])
    )
    def first_text(*keys, fallback="", limit=260):
        for key in keys:
            text = _clean_story_text(raw.get(key), limit)
            if text:
                return text
        return _clean_story_text(fallback, limit)

    return {
        "characters": character_names,
        "character_cards": cards,
        "terms": terms,
        "summary": _clean_story_text(raw.get("summary"), 4000),
        "story_beats": beats,
        "current_goal": first_text(
            "current_goal", "goal", fallback=map_context.get("current_goal")
        ),
        "current_conflict": first_text(
            "current_conflict",
            "conflict",
            fallback=map_context.get("current_conflict"),
        ),
        "conflict_stakes": first_text(
            "conflict_stakes",
            "stakes",
            fallback=map_context.get("conflict_stakes"),
        ),
        "central_question": first_text(
            "central_question",
            "main_question",
            fallback=map_context.get("central_question"),
        ),
        "setting": first_text(
            "setting", "location", fallback=map_context.get("setting")
        ),
        "open_threads": _clean_story_string_list(
            list(raw.get("open_threads") or [])
            + list(map_context.get("open_threads") or []),
            limit=12,
            item_limit=240,
        ),
        "important_facts": _clean_story_string_list(
            list(raw.get("important_facts") or [])
            + list(map_context.get("important_facts") or []),
            limit=24,
            item_limit=240,
        ),
        "last_scene": _clean_story_text(raw.get("last_scene"), 800),
        "protagonist": protagonist,
        "protagonist_gender": protagonist_gender,
        "protagonist_pronoun": protagonist_pronoun,
        "narrator_perspective": NARRATOR_PERSPECTIVE,
    }


def _merge_story_contexts(*contexts, fallback_from_scenes=None) -> dict:
    """Merge per-window story memory without resetting earlier chapters.

    The previous summary step replaced the whole context with a
    two/three-line summary of only the latest two minutes.  On a
    long video that made names, motives and unresolved threads
    vanish at every boundary, so later narration could sound like
    disconnected captions.  Identity fields keep the first
    established value; current-state fields use the latest value;
    beats/facts accumulate in chronological order with sane caps.
    """
    normalized = [
        _normalize_story_context(item)
        for item in contexts
        if isinstance(item, dict)
    ]
    fallback_scenes = (
        list(fallback_from_scenes)
        if isinstance(fallback_from_scenes, (list, tuple))
        else []
    )
    fallback_texts = [
        _clean_story_text(
            scene.get("burmese") if isinstance(scene, dict) else "",
            800,
        )
        for scene in fallback_scenes
    ]
    fallback_texts = [text for text in fallback_texts if text]
    if not normalized:
        fallback_context = _normalize_story_context(
            {},
            scenes=fallback_scenes,
            derive_beats=bool(fallback_texts),
        )
        if fallback_texts:
            fallback_context["last_scene"] = fallback_texts[-1]
        return fallback_context

    # The registry is capped, so feed the newest window's active cast
    # first.  Chronological first-seen order let walk-on characters
    # from minute 2 permanently occupy every slot while an important
    # person introduced at minute 70 never entered Cast Lock.  The
    # established protagonist is moved back to the front below.
    priority_contexts = list(reversed(normalized))
    character_names = _clean_story_string_list(
        [
            name
            for item in priority_contexts
            for name in (item.get("characters") or [])
        ],
        limit=16,
        item_limit=80,
    )
    cards = _normalize_character_cards(
        [
            card
            for item in priority_contexts
            for card in (item.get("character_cards") or [])
        ],
        character_names=character_names,
    )
    protagonist = next(
        (item.get("protagonist") for item in normalized if item.get("protagonist")),
        "",
    )
    protagonist_key = _normalize_burmese_text(protagonist)
    if protagonist_key and cards:
        cards.sort(
            key=lambda card: 0
            if protagonist_key
            in {
                _normalize_burmese_text(_character_card_spoken_name(card)),
                _normalize_burmese_text(_character_card_short_name(card)),
                _normalize_burmese_text(card.get("source_name") or ""),
                _normalize_burmese_text(card.get("name") or ""),
            }
            else 1
        )
    if cards:
        character_names = _clean_story_string_list(
            [_character_card_spoken_name(card) for card in cards],
            limit=16,
            item_limit=80,
        )
    summary_pieces = []
    seen_summaries = set()
    for item in normalized:
        summary = str(item.get("summary") or "").strip()
        key = _normalize_burmese_text(summary)
        if summary and key and key not in seen_summaries:
            summary_pieces.append(summary)
            seen_summaries.add(key)
    summary = " ".join(summary_pieces)
    if len(summary) > 4000:
        summary = summary[:1000].rstrip() + " … " + summary[-2900:].lstrip()

    def first_value(key):
        for item in normalized:
            if item.get(key):
                return item[key]
        return ""

    def latest_value(key):
        for item in reversed(normalized):
            if item.get(key):
                return item[key]
        return ""

    merged = {
        "characters": character_names,
        "character_cards": cards,
        "terms": _normalize_story_terms(
            [term for item in normalized for term in (item.get("terms") or [])]
        ),
        "summary": summary,
        "story_beats": _clean_story_string_list(
            [beat for item in normalized for beat in (item.get("story_beats") or [])],
            limit=64,
            item_limit=320,
        )[-24:],
        "current_goal": latest_value("current_goal"),
        "current_conflict": latest_value("current_conflict"),
        "conflict_stakes": latest_value("conflict_stakes"),
        "central_question": latest_value("central_question"),
        "setting": latest_value("setting"),
        "open_threads": _clean_story_string_list(
            [
                x
                for item in priority_contexts
                for x in (item.get("open_threads") or [])
            ],
            limit=12,
            item_limit=240,
        ),
        "important_facts": _clean_story_string_list(
            [x for item in normalized for x in (item.get("important_facts") or [])],
            limit=48,
            item_limit=240,
        )[-32:],
        "last_scene": latest_value("last_scene"),
        "protagonist": first_value("protagonist"),
        "protagonist_gender": first_value("protagonist_gender"),
        "protagonist_pronoun": first_value("protagonist_pronoun"),
        "narrator_perspective": NARRATOR_PERSPECTIVE,
    }
    if fallback_texts:
        if not merged.get("story_beats"):
            merged["story_beats"] = _clean_story_string_list(
                fallback_texts,
                limit=16,
                item_limit=220,
            )
        if not merged.get("last_scene"):
            merged["last_scene"] = fallback_texts[-1]
    return _normalize_story_context(merged)


def _story_context_prompt_lines(story_context: dict) -> str:
    context = _normalize_story_context(story_context or {})
    lines = []
    card_lines = []
    for card in context["character_cards"][:16]:
        spoken_name = _character_card_spoken_name(card)
        if not spoken_name:
            continue
        safe_spoken_name = _character_card_safe_spoken_form(card)
        short_name = str(card.get("short_name") or "").strip()
        safe_short_name = _tts_safe_spoken_form(short_name, limit=120)
        if safe_spoken_name:
            bits = [safe_spoken_name]
        elif safe_short_name:
            bits = [
                safe_short_name
                + " (လက်ရှိ Burmese spoken form — ဒါကိုသာသုံးပါ; "
                + f"မူရင်းစာလုံး {spoken_name} ကို narration မှာ မသုံးရ)"
            ]
        else:
            bits = [
                "Burmese spoken_name မရှိသေး — မူရင်းအထောက်အထားစာလုံး "
                f"{spoken_name} ကို narration မှာ လုံးဝမသုံးဘဲ "
                "မြန်မာအသံထွက် transliteration အသစ်တစ်ခုတည်း lock လုပ်ပါ"
            ]
        source_name = str(card.get("source_name") or "").strip()
        if source_name and _normalize_burmese_text(source_name) != _normalize_burmese_text(
            spoken_name
        ):
            bits.append(f"မူရင်းအမည်: {source_name}")
        if card.get("gender"):
            bits.append("ကျား/မ: " + str(card["gender"]))
        if card.get("role"):
            bits.append(str(card["role"]))
        if card.get("relation"):
            bits.append(str(card["relation"]))
        introduction = str(card.get("introduction") or "")
        if introduction and not _tts_unsafe_script_chars(introduction):
            bits.append("ပထမမိတ်ဆက်ရန်: " + introduction)
        elif introduction:
            bits.append(
                "ပထမမိတ်ဆက်စာသားမှာ နိုင်ငံခြားစာလုံးပါနေ၍ အတိအကျမသုံးရ — "
                "Burmese transliteration နဲ့ ပြန်ရေးပါ"
            )
        if (
            safe_short_name
            and _normalize_burmese_text(safe_short_name)
            != _normalize_burmese_text(safe_spoken_name or spoken_name)
        ):
            bits.append("နောက်ပိုင်းနေ့တိုင်းခေါ်ရန်: " + safe_short_name)
        identity_anchor = str(card.get("identity_anchor") or "")
        if identity_anchor and not _tts_unsafe_script_chars(identity_anchor):
            bits.append("ပြန်ပေါ်လာရင်အမှတ်ရစေရန်: " + identity_anchor)
        if card.get("goal"):
            bits.append("ရည်မှန်းချက်: " + str(card["goal"]))
        if card.get("motivation"):
            bits.append("အကြောင်းရင်း: " + str(card["motivation"]))
        if card.get("visual_cue"):
            bits.append("မြင်မှတ်ချက်: " + str(card["visual_cue"]))
        name_source = str(card.get("name_source") or "unknown")
        confidence = str(card.get("confidence") or "uncertain")
        bits.append(f"အမည်အထောက်အထား: {name_source}/{confidence}")
        if card.get("name_evidence_text"):
            bits.append("အမည်အထောက်အထားစာသား: " + str(card["name_evidence_text"]))
        name_reveal_bridge = str(card.get("name_reveal_bridge") or "")
        if name_reveal_bridge and not _tts_unsafe_script_chars(
            name_reveal_bridge
        ):
            bits.append(
                "အမည်ပြောင်းချိန် ယခင်အပိုင်းမှာ မပြောရသေးရင်သာ တစ်ခါတည်းသုံးရန်: "
                + name_reveal_bridge
            )
        if card.get("aliases"):
            bits.append("မသုံးရန် variant: " + ", ".join(card["aliases"][:3]))
        card_lines.append(" — ".join(bit for bit in bits if bit))
    if card_lines:
        lines.append(
            "- Cast Lock / Name Ladder (ပထမတစ်ခါ introduction + spoken_name အပြည့်၊ "
            "နောက်ပိုင်း approved short_name သို့မဟုတ် spoken_name၊ ပြန်ပေါ်လာရင် identity_anchor၊ "
            "variant မသုံးရ): " + "; ".join(card_lines)
        )
    elif context["characters"]:
        lines.append("- ဇာတ်ကောင်များ: " + ", ".join(context["characters"][:10]))
    if context.get("protagonist"):
        protagonist_form = str(context["protagonist"])
        if _tts_unsafe_script_chars(protagonist_form):
            protagonist_form = (
                "Burmese spoken form မရှိသေး — မူရင်းအထောက်အထားစာလုံး "
                f"{protagonist_form} ကို narration မှာ မသုံးဘဲ "
                "မြန်မာအသံထွက် transliteration အသစ်တစ်ခု lock လုပ်ပါ"
            )
        protagonist_bits = [
            "- Narrator protagonist (ကိုယ်တိုင်ပြန်ပြောသူ): "
            + protagonist_form
        ]
        if context.get("protagonist_pronoun"):
            protagonist_bits.append(
                "ကိုယ့်ကိုယ်ကိုညွှန်းရန် lock လုပ်ထားတဲ့ pronoun: "
                + str(context["protagonist_pronoun"])
            )
        if context.get("protagonist_gender"):
            protagonist_bits.append(
                "ကျား/မ: " + str(context["protagonist_gender"])
            )
        protagonist_bits.append(
            "ပထမတစ်ခါပဲ အမည်အပြည့်နဲ့ မိတ်ဆက်ပြီး နောက်ပိုင်း ကိုယ့်လုပ်ရပ်အတွက် "
            "အဲဒီ pronoun ကိုသုံးပါ; အခြားလူတွေကိုတော့ Name Ladder အမည်တွေနဲ့ပြောပါ"
        )
        lines.append(" — ".join(protagonist_bits))
    term_lines = []
    for term in (context.get("terms") or [])[:16]:
        spoken_term = str(term.get("spoken_term") or "").strip()
        if not spoken_term:
            continue
        safe_spoken_term = _tts_safe_spoken_form(spoken_term, limit=120)
        if safe_spoken_term:
            bits = [safe_spoken_term]
        else:
            bits = [
                "Burmese spoken_term မရှိသေး — မူရင်းအထောက်အထားစာလုံး "
                f"{spoken_term} ကို narration မှာ မသုံးဘဲ "
                "မြန်မာအဓိပ္ပာယ်/transliteration အသစ်တစ်ခု lock လုပ်ပါ"
            ]
        if term.get("source_term"):
            bits.append("မူရင်းအခေါ်: " + str(term["source_term"]))
        if term.get("meaning"):
            bits.append("အဓိပ္ပာယ်: " + str(term["meaning"]))
        first_explanation = str(term.get("first_explanation") or "")
        if first_explanation and not _tts_unsafe_script_chars(
            first_explanation
        ):
            bits.append("ပထမအကြိမ်ရှင်းပြရန်: " + first_explanation)
        if term.get("aliases"):
            bits.append("မသုံးရန် variant: " + ", ".join(term["aliases"][:3]))
        term_lines.append(" — ".join(bit for bit in bits if bit))
    if term_lines:
        lines.append(
            "- Glossary Lock (အသုံးအနှုန်း/စည်းမျဉ်းတစ်ခုချင်းအတွက် ပြောရမည့်ပုံစံ "
            "တစ်မျိုးတည်းသုံးပြီး ပထမဆုံးအကြိမ်မှာ ရှင်းပြရန်): "
            + "; ".join(term_lines)
        )
    if context["story_beats"]:
        beats = context["story_beats"][-10:]
        lines.append(
            "- အရင်ဖြစ်ရပ်အစဉ်: "
            + " → ".join(f"{index + 1}. {beat}" for index, beat in enumerate(beats))
        )
    if context["current_goal"]:
        lines.append("- လက်ရှိရည်မှန်းချက်: " + context["current_goal"])
    if context["current_conflict"]:
        lines.append("- လက်ရှိအဓိကပြဿနာ: " + context["current_conflict"])
    if context.get("conflict_stakes"):
        lines.append(
            "- မအောင်မြင်/ငြင်းဆန်ရင် ဆုံးရှုံးနိုင်တာ (stakes): "
            + context["conflict_stakes"]
        )
    if context.get("central_question"):
        lines.append(
            "- မဖြေရှင်းရသေးတဲ့ အဓိကမေးခွန်း: " + context["central_question"]
        )
    if context["open_threads"]:
        lines.append("- မဖြေရှင်းသေးသည့်အရာများ: " + "; ".join(context["open_threads"][:6]))
    if context["important_facts"]:
        lines.append("- မမေ့ရမည့်အချက်များ: " + "; ".join(context["important_facts"][-8:]))
    if context["setting"]:
        lines.append("- လက်ရှိနေရာ/အခြေအနေ: " + context["setting"])
    if context["summary"]:
        lines.append("- အဓိကဖြစ်ရပ်အကျဉ်း: " + context["summary"][-2500:])
    if context["last_scene"]:
        lines.append("- နောက်ဆုံးအခြေအနေ: " + context["last_scene"][-800:])
    return "\n".join(lines)


_CAST_GENERIC_ALIASES = {
    _normalize_burmese_text(value)
    for value in (
        "သူ",
        "သူမ",
        "ဒီလူ",
        "အဲ့ဒီလူ",
        "လူ",
        "အဖေ",
        "အမေ",
        "အစ်ကို",
        "အစ်မ",
        "ညီ",
        "ညီမလေး",
        "သား",
        "သမီး",
    )
}


def _tts_safe_spoken_form(value, *, limit: int = 120) -> str:
    """Return a Burmese form the narration voices can actually speak."""

    clean = _clean_story_text(value, limit)
    if (
        not clean
        or _tts_unsafe_script_chars(clean)
        or not any("\u1000" <= char <= "\u109f" for char in clean)
    ):
        return ""
    return clean


def _character_card_safe_spoken_form(card) -> str:
    """Locked spoken form, falling back to a safe approved short form."""

    spoken_name = _character_card_spoken_name(card)
    safe_spoken = _tts_safe_spoken_form(spoken_name, limit=80)
    if safe_spoken:
        return safe_spoken
    return _tts_safe_spoken_form(
        _character_card_short_name(card), limit=80
    )


def _apply_cast_lock_to_scenes(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
) -> int:
    """Replace known non-canonical name variants with locked spoken forms.

    Character cards may retain an original foreign name or an older
    descriptive label for recognition, but narration should use only
    the locked full form and its one approved routine short form.
    Generic kinship/pronoun words and aliases claimed by
    more than one person are deliberately left alone.
    """
    if not scenes:
        return 0
    context_cards = []
    if story_context:
        context_cards = (
            _normalize_story_context(story_context).get("character_cards") or []
        )
    map_cards = _normalize_story_map(story_map).get("character_cards") or []
    cards = _normalize_character_cards(list(context_cards) + list(map_cards))
    if not cards:
        return 0

    # Only Burmese forms the TTS voices can speak are canonical
    # narration forms.  A foreign-script ``spoken_name`` is source
    # evidence, not a replacement target: using it here used to
    # *introduce* the very Latin/CJK/Korean characters the final
    # professional gate then rejected.
    canonical_keys = {
        _normalize_burmese_text(form)
        for card in cards
        for form in _character_card_name_forms(card)
        if form and not _tts_unsafe_script_chars(form)
    }
    alias_replacements = {}
    conflicting_alias_keys = set()
    for card in cards:
        spoken_name = _character_card_safe_spoken_form(card)
        if not spoken_name:
            continue
        raw_aliases = []
        for unsafe_form in (
            _character_card_spoken_name(card),
            _character_card_short_name(card),
        ):
            if unsafe_form and _tts_unsafe_script_chars(unsafe_form):
                raw_aliases.append(unsafe_form)
        if card.get("source_name"):
            raw_aliases.append(card["source_name"])
        raw_aliases.extend(card.get("aliases") or [])
        for raw_alias in raw_aliases:
            alias = _clean_story_text(raw_alias, 80)
            alias_key = _normalize_burmese_text(alias)
            if (
                len(alias) < 2
                or not alias_key
                or alias_key in canonical_keys
                or alias_key in _CAST_GENERIC_ALIASES
            ):
                continue
            if any(
                alias_key != canonical_key
                and (alias_key in canonical_key or canonical_key in alias_key)
                for canonical_key in canonical_keys
            ):
                continue
            previous = alias_replacements.get(alias_key)
            if previous is not None and previous[1] != spoken_name:
                conflicting_alias_keys.add(alias_key)
            else:
                alias_replacements[alias_key] = (alias, spoken_name)
    for alias_key in conflicting_alias_keys:
        alias_replacements.pop(alias_key, None)
    if not alias_replacements:
        return 0

    replacements = sorted(
        alias_replacements.values(), key=lambda item: len(item[0]), reverse=True
    )
    replacement_count = 0
    for scene in scenes:
        if not isinstance(scene, dict):
            continue
        original_text = str(scene.get("burmese") or "")
        if not original_text:
            continue
        new_text = original_text
        for alias, spoken_name in replacements:
            occurrences = new_text.count(alias)
            if occurrences:
                replacement_count += int(occurrences)
                new_text = new_text.replace(alias, spoken_name)
        if new_text != original_text:
            scene["burmese"] = new_text
    return int(replacement_count)


def _sanitize_tts_unsafe_scenes(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
) -> dict:
    """Replace ledger-known foreign-script forms with Burmese speech.

    The professional gate must still refuse a foreign name/term the
    Burmese voice would skip, but it should not discard an otherwise
    valid script when the story bible already knows the Burmese form:
    a character card's safe spoken/short name, a glossary term's
    locked ``spoken_term``, or an on-screen text entry's Burmese
    meaning.  Unknown foreign tokens are left untouched for the
    bounded model repair/gate and reported in the returned stats so
    health diagnostics show *which* tokens remained.
    """

    stats = {
        "replacements": 0,
        "replaced_tokens": [],
        "remaining_unsafe_chars": 0,
        "remaining_tokens": [],
    }
    scene_list = [
        scene
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    if not scene_list:
        return stats

    normalized_map = _normalize_story_map(story_map)
    normalized_context = _normalize_story_context(story_context or {})
    cards = _normalize_character_cards(
        list(normalized_context.get("character_cards") or [])
        + list(normalized_map.get("character_cards") or [])
    )

    replacements = {}
    conflicting = set()

    def add_replacement(raw_value, target_value, *, only_if_new=False):
        raw = _clean_story_text(raw_value, 180)
        target = _tts_safe_spoken_form(target_value, limit=200)
        if (
            not raw
            or not target
            or len(raw) < 2
            or raw == target
            or not _tts_unsafe_script_chars(raw)
        ):
            return
        # The narration may use the Traditional spelling while the
        # card kept the Simplified one (or vice versa). The Burmese
        # ledger target is exactly as trustworthy for the variant.
        for form in _cjk_variant_forms(raw):
            previous = replacements.get(form)
            if previous is not None:
                if previous != target and not only_if_new:
                    conflicting.add(form)
                continue
            replacements[form] = target

    # Character names first: they are the tokens a listener most
    # needs to hear, and their locked form outranks a visible-text
    # paraphrase of the same source wording.
    card_targets = []
    descriptive_target_counts = {}
    for card in cards:
        target = _character_card_safe_spoken_form(card)
        descriptive = False
        if not target:
            for key in (
                "identity_anchor",
                "visual_cue",
                "relation",
                "role",
            ):
                candidate = _tts_safe_spoken_form(card.get(key), limit=120)
                if (
                    candidate
                    and len(_normalize_burmese_text(candidate)) >= 8
                    and not _cast_label_is_generic(candidate)
                ):
                    target = candidate
                    descriptive = True
                    break
        card_targets.append((target, descriptive))
        if target and descriptive:
            target_key = _normalize_burmese_text(target)
            descriptive_target_counts[target_key] = (
                descriptive_target_counts.get(target_key, 0) + 1
            )
    for card, (target, descriptive) in zip(cards, card_targets):
        if not target:
            continue
        if descriptive and descriptive_target_counts.get(
            _normalize_burmese_text(target), 0
        ) > 1:
            # Two different people must never collapse into one
            # shared descriptive label just to satisfy TTS safety.
            continue
        raw_forms = [
            _character_card_spoken_name(card),
            _character_card_short_name(card),
            card.get("source_name"),
            *(card.get("aliases") or []),
        ]
        for raw_form in raw_forms:
            add_replacement(raw_form, target)

    terms = _normalize_story_terms(
        list(normalized_context.get("terms") or [])
        + list(normalized_map.get("terms") or [])
    )
    for term in terms:
        target = _tts_safe_spoken_form(term.get("spoken_term"), limit=120)
        if not target:
            meaning = _tts_safe_spoken_form(term.get("meaning"), limit=120)
            if meaning and len(_normalize_burmese_text(meaning)) <= 60:
                target = meaning.rstrip("။!?")
        if not target:
            continue
        for raw_form in [
            term.get("spoken_term"),
            term.get("source_term"),
            *(term.get("aliases") or []),
        ]:
            add_replacement(raw_form, target)

    for entry in normalized_map.get("visible_texts") or []:
        if not isinstance(entry, dict) or entry.get("kind") == "name_card":
            continue
        meaning = _tts_safe_spoken_form(
            entry.get("burmese_meaning"), limit=200
        )
        if meaning:
            add_replacement(
                entry.get("source_text"),
                meaning.rstrip("။!?"),
                only_if_new=True,
            )

    for raw in conflicting:
        replacements.pop(raw, None)

    replaced_tokens = []
    for scene in scene_list:
        original = str(scene.get("burmese") or "")
        updated = original
        for raw, target in sorted(
            replacements.items(), key=lambda item: len(item[0]), reverse=True
        ):
            if raw not in updated:
                continue
            if all(ord(char) < 128 for char in raw):
                pattern = (
                    r"(?<![A-Za-z])" + re.escape(raw) + r"(?![A-Za-z])"
                )
                updated, count = re.subn(pattern, target, updated)
            else:
                count = updated.count(raw)
                updated = updated.replace(raw, target)
            if count:
                stats["replacements"] += int(count)
                if raw not in replaced_tokens:
                    replaced_tokens.append(raw)
        if updated != original:
            scene["burmese"] = updated

    remaining_tokens = []
    for scene in scene_list:
        text = str(scene.get("burmese") or "")
        stats["remaining_unsafe_chars"] += int(
            _tts_unsafe_script_chars(text)
        )
        for token in _tts_unsafe_tokens(text):
            if token not in remaining_tokens:
                remaining_tokens.append(token)
    stats["replaced_tokens"] = replaced_tokens[:16]
    stats["remaining_tokens"] = remaining_tokens[:16]
    return stats


def _protagonist_name_forms(
    protagonist: str = "",
    story_map: dict = None,
    story_context: dict = None,
) -> list:
    protagonist_name = _clean_protagonist_name(protagonist)
    cards = []
    if story_context:
        cards.extend(
            _normalize_story_context(story_context).get("character_cards") or []
        )
        if not protagonist_name:
            protagonist_name = _clean_protagonist_name(
                _normalize_story_context(story_context).get("protagonist")
            )
    if story_map:
        cards.extend(_normalize_story_map(story_map).get("character_cards") or [])
    forms = []
    if protagonist_name:
        forms.append(protagonist_name)
        card = _find_character_card_for_name(cards, protagonist_name)
        for form in _character_card_name_forms(card):
            if form and form not in forms:
                forms.append(form)
    return sorted(forms, key=len, reverse=True)


def _resolve_protagonist_pronoun(
    *,
    protagonist: str = "",
    story_map: dict = None,
    story_context: dict = None,
    scenes: list = None,
) -> tuple:
    """Return ``(protagonist, gender, pronoun, merged_context)``.

    Earlier story context wins over a later model's guess.  If neither the
    cards nor payload metadata know the gender, the dominant unquoted
    self-pronoun already used by the script is the only deterministic
    fallback; we never choose a Burmese gendered pronoun from a name.
    """

    map_context = _story_context_from_story_map(
        story_map or {},
        protagonist=protagonist,
    )
    merged_context = _merge_story_contexts(story_context or {}, map_context)
    protagonist_name = _clean_protagonist_name(
        protagonist or merged_context.get("protagonist") or ""
    )
    gender, pronoun = _protagonist_gender_and_pronoun(
        merged_context,
        protagonist=protagonist_name,
        character_cards=merged_context.get("character_cards") or [],
    )
    if not pronoun and scenes:
        pronoun = _dominant_narrator_pronoun(scenes)
        gender = _gender_from_pronoun(pronoun)
    if protagonist_name:
        merged_context["protagonist"] = protagonist_name
    if gender:
        merged_context["protagonist_gender"] = gender
    if pronoun:
        merged_context["protagonist_pronoun"] = pronoun
    return protagonist_name, gender, pronoun, merged_context


def _replace_wrong_narrator_pronoun(text: str, expected_pronoun: str) -> str:
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    if not expected:
        return str(text or "")
    opposite = _opposite_first_person_pronoun(expected)
    if not opposite:
        return str(text or "")
    expected_possessive = (FIRST_PERSON_POSSESSIVE_VARIANTS.get(expected) or ("",))[0]

    def convert(chunk: str) -> str:
        result = str(chunk or "")
        for variant in FIRST_PERSON_POSSESSIVE_VARIANTS.get(opposite, ()):
            result = result.replace(variant, expected_possessive or expected)
        return result.replace(opposite, expected)

    return _map_unquoted_text(str(text or ""), convert)


def _replace_protagonist_self_name_subjects(
    text: str,
    expected_pronoun: str,
    protagonist_forms=None,
) -> str:
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    forms = []
    for form in protagonist_forms or []:
        clean = _normalize_burmese_text(form).strip(" «»\"'“”‘’")
        if clean and clean not in forms:
            forms.append(clean)
    if not expected or not forms:
        return str(text or "")
    forms.sort(key=len, reverse=True)
    markers = (
        "တို့ကတော့",
        "တို့က",
        "တို့လည်း",
        "ကတော့",
        "ကလည်း",
        "က",
        "ဟာ",
        "လည်း",
    )

    def convert_clause(clause: str) -> str:
        leading_len = len(clause) - len(clause.lstrip())
        leading = clause[:leading_len]
        candidate = clause[leading_len:]
        prefix = ""
        probe = candidate
        for candidate_prefix in sorted(
            _PROTAGONIST_SUBJECT_PREFIXES,
            key=len,
            reverse=True,
        ):
            if candidate_prefix and candidate.startswith(candidate_prefix):
                rest = candidate[len(candidate_prefix):].lstrip()
                if any(rest.startswith(form) for form in forms):
                    prefix = candidate[:len(candidate) - len(rest)]
                    probe = rest
                    break
        for form in forms:
            if not probe.startswith(form):
                continue
            rest = probe[len(form):]
            for marker in markers:
                if rest.startswith(marker):
                    return f"{leading}{prefix}{expected}{rest}"
        return clause

    def convert_chunk(chunk: str) -> str:
        converted_sentences = []
        for raw_sentence in _split_sentences(str(chunk or "")):
            sentence = raw_sentence
            compact = _normalize_burmese_text(sentence)
            if expected in compact and any(
                marker in compact
                for marker in ("အမည်က", "နာမည်က", "အမည်က", "နာမည်က", "လို့ခေါ်")
            ):
                converted_sentences.append(sentence)
                continue
            converted_sentences.append(
                "၊".join(convert_clause(clause) for clause in sentence.split("၊"))
            )
        return "".join(converted_sentences)

    return _map_unquoted_text(str(text or ""), convert_chunk)


def _protagonist_self_introduction_present(
    texts: list,
    protagonist_forms=None,
    expected_pronoun: str = "",
) -> bool:
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    forms = [
        _normalize_burmese_text(form).strip()
        for form in (protagonist_forms or [])
        if str(form or "").strip()
    ]
    if not expected or not forms:
        return False
    opening_sentences = []
    for text in texts or []:
        opening_sentences.extend(_split_sentences(_scene_text_for_pov(text)))
        if len(opening_sentences) >= 4:
            break
    for sentence in opening_sentences[:4]:
        unquoted = _strip_quoted_speech(sentence)
        if expected not in unquoted:
            continue
        if not any(form in unquoted for form in forms):
            continue
        if any(
            marker in unquoted
            for marker in ("အမည်က", "နာမည်က", "အမည်က", "နာမည်က", "လို့ခေါ်")
        ):
            return True
        compact = "".join(unquoted.split())
        if ("ဖြစ်တယ်" in compact or "ဖြစ်ပါတယ်" in compact or compact.endswith("ပါ")) and (
            compact.startswith(expected) or f"{expected}က" in compact
        ):
            return True
    return False


def _build_protagonist_self_introduction(
    protagonist: str,
    expected_pronoun: str,
    story_map: dict = None,
    story_context: dict = None,
) -> str:
    protagonist_name = _clean_protagonist_name(protagonist)
    expected = _normalize_protagonist_pronoun(expected_pronoun)
    if not protagonist_name or not expected:
        return ""
    _name, _gender, _pronoun, merged_context = _resolve_protagonist_pronoun(
        protagonist=protagonist_name,
        story_map=story_map,
        story_context=story_context,
    )
    card = _find_character_card_for_name(
        merged_context.get("character_cards") or [],
        protagonist_name,
    )
    introduction = _clean_story_text(card.get("introduction"), 240)
    # A card can mention the narrator and their name without actually
    # introducing them (or do so only in quoted dialogue).  Reusing such
    # text makes every repair pass insert the same invalid opening again.
    # Validate it with the very same quote-aware gate as the final script.
    introduction = _polish_text_for_speech(introduction)
    if (
        introduction
        and not _tts_unsafe_script_chars(introduction)
        and _protagonist_self_introduction_present(
            [introduction],
            protagonist_forms=_protagonist_name_forms(
                protagonist_name, story_map=story_map, story_context=merged_context
            ),
            expected_pronoun=expected,
        )
    ):
        return introduction

    # Never manufacture an introduction by speaking foreign evidence.
    # The token repair or model repair must first lock a safe identity.
    if not _tts_safe_spoken_form(protagonist_name, limit=100):
        return ""

    confidence = str(card.get("confidence") or "")
    descriptive = confidence == "descriptive" or _spoken_name_form_is_long(
        protagonist_name
    )
    role = _clean_story_text(card.get("role"), 120)
    relation = _clean_story_text(card.get("relation"), 140)
    for form in _character_card_name_forms(card):
        if role.startswith(form):
            role = role[len(form):].lstrip(" ကကတော့")
        if relation.startswith(form):
            relation = relation[len(form):].lstrip(" ကကတော့")
    identity_detail = role or relation
    if identity_detail and (
        _tts_unsafe_script_chars(identity_detail)
        or any(marker in identity_detail for marker in ("။", "?", "!"))
    ):
        identity_detail = ""

    if descriptive:
        # A descriptive label is who the listener can recognise, not a
        # literal personal name.  Saying "my name is <long label>" would
        # invent evidence the source never gave.
        return _polish_text_for_speech(
            f"{expected}က {protagonist_name} ဖြစ်တယ်"
        )
    if identity_detail and _normalize_burmese_text(identity_detail) != _normalize_burmese_text(
        protagonist_name
    ):
        return _polish_text_for_speech(
            f"{expected}အမည်က {protagonist_name} ဖြစ်တယ်။ "
            f"{expected}က {identity_detail} ဖြစ်တယ်"
        )
    return _polish_text_for_speech(
        f"{expected}အမည်က {protagonist_name} ဖြစ်တယ်"
    )


def _ensure_first_person_protagonist_scenes(
    scenes: list,
    *,
    protagonist: str = "",
    story_map: dict = None,
    story_context: dict = None,
    protagonist_gender: str = "",
    protagonist_pronoun: str = "",
    is_opening: bool = False,
) -> tuple:
    """Deterministically lock narration to the protagonist's own voice.

    Model repair still handles genuinely tangled POV.  This pass handles
    the safe, mechanical failures that made output drift back into a
    third-person book voice: the wrong gendered self-pronoun outside
    quotes, the protagonist repeatedly acting under their own name, and a
    first window that never actually introduces the narrator by name.
    """

    scene_list = [
        dict(scene)
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    identity_context = dict(story_context or {})
    if protagonist_gender:
        identity_context["protagonist_gender"] = protagonist_gender
    if protagonist_pronoun:
        identity_context["protagonist_pronoun"] = protagonist_pronoun
    protagonist_name, gender, pronoun, merged_context = _resolve_protagonist_pronoun(
        protagonist=protagonist,
        story_map=story_map,
        story_context=identity_context,
        scenes=scene_list,
    )
    forms = _protagonist_name_forms(
        protagonist_name,
        story_map=story_map,
        story_context=merged_context,
    )
    before_metrics = _first_person_metrics(
        scene_list,
        expected_pronoun=pronoun,
        protagonist_forms=forms,
    )
    wrong_before = 0
    if pronoun:
        opposite = _opposite_first_person_pronoun(pronoun)
        wrong_before = int(
            before_metrics.get(
                "male_narrator_count"
                if opposite == FIRST_PERSON_MALE
                else "female_narrator_count"
            )
            or 0
        )
    self_name_before = int(
        before_metrics.get("protagonist_self_name_subject_count") or 0
    )

    if pronoun:
        for scene in scene_list:
            text = str(scene.get("burmese") or "")
            text = _replace_wrong_narrator_pronoun(text, pronoun)
            text = _replace_protagonist_self_name_subjects(
                text,
                pronoun,
                forms,
            )
            scene["burmese"] = text

    introduction_added = False
    if is_opening and scene_list and protagonist_name and pronoun:
        if not _protagonist_self_introduction_present(
            scene_list,
            protagonist_forms=forms,
            expected_pronoun=pronoun,
        ):
            introduction = _build_protagonist_self_introduction(
                protagonist_name,
                pronoun,
                story_map=story_map,
                story_context=merged_context,
            )
            if introduction:
                first_text = str(scene_list[0].get("burmese") or "").strip()
                if _normalize_burmese_text(introduction) not in _normalize_burmese_text(
                    first_text
                ):
                    scene_list[0]["burmese"] = (
                        f"{introduction} {first_text}".strip()
                    )
                    introduction_added = True

    after_metrics = _first_person_metrics(
        scene_list,
        expected_pronoun=pronoun,
        protagonist_forms=forms,
    )
    wrong_after = 0
    if pronoun:
        opposite = _opposite_first_person_pronoun(pronoun)
        wrong_after = int(
            after_metrics.get(
                "male_narrator_count"
                if opposite == FIRST_PERSON_MALE
                else "female_narrator_count"
            )
            or 0
        )
    stats = {
        "protagonist": protagonist_name,
        "protagonist_gender": gender,
        "protagonist_pronoun": pronoun,
        "protagonist_forms": forms,
        "pronoun_known": bool(pronoun),
        "wrong_pronoun_replacements": max(0, wrong_before - wrong_after),
        "protagonist_self_name_subject_conversions": max(
            0,
            self_name_before
            - int(after_metrics.get("protagonist_self_name_subject_count") or 0),
        ),
        "self_introduction_added": bool(introduction_added),
        "bad_scene_indexes": after_metrics.get("bad_scene_indexes") or [],
        "metrics": after_metrics,
    }
    return scene_list, stats


def _repair_scene_opening_identities(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
    protagonist: str = "",
) -> tuple:
    """Name the actor at a scene opening when the evidence is unambiguous.

    Cast Lock can replace a known alias, but it cannot help an opening such
    as ``သူက ...`` or a subjectless clause after an actor switch.  This pass
    therefore uses only two safe repairs: replace an opening ambiguous
    pronoun when the overlapping story beat/scene identifies exactly one
    person, or insert that one beat-supported actor after an opening
    connector.  Anything less certain is left for the story editor, because
    inserting the wrong subject in Burmese would be worse than a pronoun.
    """

    scene_list = [
        dict(scene)
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    if not scene_list:
        return [], {
            "pronoun_replacements": 0,
            "actor_insertions": 0,
            "repaired_scene_indexes": [],
        }
    protagonist_name, _gender, protagonist_pronoun, merged_context = (
        _resolve_protagonist_pronoun(
            protagonist=protagonist,
            story_map=story_map,
            story_context=story_context,
            scenes=scene_list,
        )
    )
    normalized_map = _normalize_story_map(story_map)
    cards = _normalize_character_cards(
        list(merged_context.get("character_cards") or [])
        + list(normalized_map.get("character_cards") or [])
    )
    if not cards:
        return scene_list, {
            "pronoun_replacements": 0,
            "actor_insertions": 0,
            "repaired_scene_indexes": [],
            "protagonist": protagonist_name,
            "protagonist_pronoun": protagonist_pronoun,
        }
    protagonist_card = _find_character_card_for_name(cards, protagonist_name)
    protagonist_spoken_name = (
        _character_card_spoken_name(protagonist_card) or protagonist_name
    )
    context_only = _normalize_story_context(story_context or {})
    established_identities = {
        _character_card_spoken_name(card)
        for card in (context_only.get("character_cards") or [])
        if _character_card_spoken_name(card)
    }
    seen_identities = set(established_identities)
    beats = [
        beat
        for beat in (normalized_map.get("beats") or [])
        if isinstance(beat, dict)
    ]

    def identities_in_text(value: str, *, extended: bool = False) -> set:
        identities = set()
        text = str(value or "")
        unquoted = _strip_quoted_speech(text)
        for card in cards:
            spoken_name = _character_card_spoken_name(card)
            if not spoken_name:
                continue
            forms = list(_character_card_name_forms(card))
            if extended:
                if card.get("source_name"):
                    forms.append(str(card["source_name"]))
                forms.extend(str(alias) for alias in (card.get("aliases") or []))
            if any(form and form in text for form in forms):
                identities.add(spoken_name)
                continue
            if (
                protagonist_spoken_name
                and _normalize_burmese_text(spoken_name)
                == _normalize_burmese_text(protagonist_spoken_name)
                and protagonist_pronoun
                and _first_person_token_counts(unquoted).get(
                    protagonist_pronoun, 0
                )
                > 0
            ):
                identities.add(spoken_name)
        return identities

    def beat_for_scene(scene: dict, scene_index: int) -> dict:
        if not beats:
            return {}
        try:
            scene_start = float(scene.get("start") or 0)
            scene_end = float(scene.get("end") or scene_start)
        except (TypeError, ValueError):
            scene_start = scene_end = 0.0
        best_beat = {}
        best_overlap = 0.0
        for beat in beats:
            try:
                beat_start = float(beat.get("start") or 0)
                beat_end = float(beat.get("end") or beat_start)
            except (TypeError, ValueError):
                continue
            overlap = min(scene_end, beat_end) - max(scene_start, beat_start)
            if overlap > best_overlap:
                best_overlap = overlap
                best_beat = beat
        if best_beat:
            return best_beat
        beat_index = min(
            len(beats) - 1,
            int(scene_index * len(beats) / max(1, len(scene_list))),
        )
        return beats[beat_index]

    ambiguous_markers = (
        ("သူမကို", "ကို"),
        ("သူ့ကို", "ကို"),
        ("သူမရဲ့", "ရဲ့"),
        ("သူ့ရဲ့", "ရဲ့"),
        ("သူမက", "က"),
        ("သူက", "က"),
        ("သူမ", ""),
        ("သူ", ""),
    )
    opening_prefixes = tuple(
        sorted(
            set(_PROTAGONIST_SUBJECT_PREFIXES)
            | {"တစ်ဖက်မှာတော့ ", "တစ်ဖက်မှာတော့", "အဲဒီအချိန်မှာပဲ ", "အဲဒီအချိန်မှာပဲ"},
            key=len,
            reverse=True,
        )
    )
    stats = {
        "pronoun_replacements": 0,
        "actor_insertions": 0,
        "repaired_scene_indexes": [],
        "protagonist": protagonist_spoken_name,
        "protagonist_pronoun": protagonist_pronoun,
    }

    for scene_index, scene in enumerate(scene_list):
        text = str(scene.get("burmese") or "")
        sentences = _split_sentences(text)
        if not sentences:
            continue
        opening = "".join(sentences[:2]) or text
        opening_identities = identities_in_text(opening)
        scene_identities = identities_in_text(text)
        first_sentence = sentences[0]
        unquoted_first_sentence = _strip_quoted_speech(first_sentence)
        has_ambiguous_opening_pronoun = any(
            0 <= unquoted_first_sentence.find(marker) <= 70
            for marker, _particle in ambiguous_markers
        )
        if opening_identities and not has_ambiguous_opening_pronoun:
            seen_identities.update(scene_identities)
            continue

        beat = beat_for_scene(scene, scene_index)
        beat_blob = " ".join(
            str(beat.get(key) or "")
            for key in (
                "beat",
                "trigger",
                "dialogue",
                "reaction",
                "result",
                "visible_text",
                "why_it_matters",
            )
        )
        beat_identities = identities_in_text(beat_blob, extended=True)
        if (
            has_ambiguous_opening_pronoun
            and protagonist_pronoun
            and _first_person_token_counts(unquoted_first_sentence).get(
                protagonist_pronoun, 0
            )
            > 0
        ):
            # In ``သူက ကျွန်တော့်ဆီ ...`` the protagonist is present as
            # the recipient/object, so the ambiguous opening subject
            # cannot also be the protagonist.  Removing that identity
            # can leave the one named actor the beat supports.
            beat_identities = {
                identity
                for identity in beat_identities
                if _normalize_burmese_text(identity)
                != _normalize_burmese_text(protagonist_spoken_name)
            }
        candidate = ""
        candidate_from_beat = False
        if len(beat_identities) == 1:
            candidate = next(iter(beat_identities))
            candidate_from_beat = True
        elif beat_identities and len(beat_identities.intersection(scene_identities)) == 1:
            candidate = next(iter(beat_identities.intersection(scene_identities)))
            candidate_from_beat = True
        elif not beat_identities and len(scene_identities) == 1:
            candidate = next(iter(scene_identities))
        if not candidate:
            seen_identities.update(scene_identities)
            continue
        is_protagonist_candidate = bool(
            protagonist_spoken_name
            and _normalize_burmese_text(candidate)
            == _normalize_burmese_text(protagonist_spoken_name)
        )
        if is_protagonist_candidate and not protagonist_pronoun:
            seen_identities.update(scene_identities)
            continue
        candidate_card = _find_character_card_for_name(cards, candidate)
        if is_protagonist_candidate:
            candidate_reference = protagonist_pronoun
        elif candidate in seen_identities:
            candidate_reference = _character_card_short_name(candidate_card)
        else:
            candidate_reference = _character_card_spoken_name(candidate_card) or candidate
        if not candidate_reference:
            seen_identities.update(scene_identities)
            continue

        first_sentence = sentences[0]
        unquoted_first_sentence = _strip_quoted_speech(first_sentence)
        has_ambiguous_pronoun = any(
            marker in unquoted_first_sentence for marker, _particle in ambiguous_markers
        )
        repaired = False
        if has_ambiguous_pronoun:
            replaced = False

            def replace_opening_pronoun(chunk: str) -> str:
                nonlocal replaced
                if replaced:
                    return chunk
                best = None
                for marker, particle in ambiguous_markers:
                    position = chunk.find(marker)
                    if position < 0 or position > 70:
                        continue
                    if best is None or position < best[0] or (
                        position == best[0] and len(marker) > len(best[1])
                    ):
                        best = (position, marker, particle)
                if best is None:
                    return chunk
                position, marker, particle = best
                replaced = True
                return (
                    chunk[:position]
                    + candidate_reference
                    + particle
                    + chunk[position + len(marker):]
                )

            new_first_sentence = _map_unquoted_text(
                first_sentence,
                replace_opening_pronoun,
            )
            if replaced and new_first_sentence != first_sentence:
                scene["burmese"] = new_first_sentence + "".join(sentences[1:])
                stats["pronoun_replacements"] += 1
                repaired = True

        if (
            not repaired
            and candidate_from_beat
            and not first_sentence.lstrip().startswith(tuple("\"'“‘«‹「『〈《"))
        ):
            prefix = ""
            probe = first_sentence.lstrip()
            leading = first_sentence[:len(first_sentence) - len(probe)]
            for candidate_prefix in opening_prefixes:
                if candidate_prefix and probe.startswith(candidate_prefix):
                    prefix = candidate_prefix
                    break
            # Subject-fronting after a time/contrast bridge is ordinary
            # spoken Burmese.  Without such a bridge, only insert when
            # the first clause plainly carries an action/speech verb.
            first_clause = probe.split("၊", 1)[0]
            has_action_or_speech = any(
                marker in first_clause
                for marker in (
                    _STORY_DIALOGUE_MARKERS
                    + _STORY_REACTION_MARKERS
                    + ("သွား", "လာ", "ရောက်", "ထွက်", "ဝင်", "လုပ်", "ကြည့်", "တွေ့")
                )
            )
            if prefix or has_action_or_speech:
                rest = probe[len(prefix):] if prefix else probe
                if rest and not rest.lstrip().startswith(candidate_reference):
                    prefix_text = (
                        prefix
                        if not prefix or prefix.endswith(" ")
                        else prefix + " "
                    )
                    new_first_sentence = (
                        f"{leading}{prefix_text}{candidate_reference}က {rest.lstrip()}"
                    )
                    scene["burmese"] = new_first_sentence + "".join(sentences[1:])
                    stats["actor_insertions"] += 1
                    repaired = True

        if repaired:
            stats["repaired_scene_indexes"].append(scene_index)
        seen_identities.update(
            identities_in_text(str(scene.get("burmese") or ""))
        )

    return scene_list, stats


def _ensure_character_introductions(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
    protagonist: str = "",
    *,
    treat_context_as_introduced: bool = True,
) -> tuple:
    """Actually speak a new person's full identity at first mention.

    The prompts already ask for the Name Ladder, but a weaker draft can
    still drop straight into a short form or bare name while the card's
    carefully built ``introduction`` sits unused in metadata.  This
    deterministic pass uses only that card evidence: it promotes a
    first short-form mention to the full spoken name and, when the
    first window does not already say who the person is, inserts the
    card's Burmese introduction/role/relation as one spoken sentence.
    It never invents a name, role, or relationship.
    """
    scene_list = [
        dict(scene)
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    stats = {
        "full_name_first_mentions": 0,
        "introductions_inserted": 0,
        "introduced_identities": [],
        "introduced_scene_indexes": [],
    }
    if not scene_list:
        return scene_list, stats

    normalized_context = _normalize_story_context(story_context or {})
    normalized_map = _normalize_story_map(story_map)
    context_cards = normalized_context.get("character_cards") or []
    cards = _normalize_character_cards(
        list(context_cards) + list(normalized_map.get("character_cards") or [])
    )
    if not cards:
        return scene_list, stats

    protagonist_name, _gender, _pronoun, _merged = _resolve_protagonist_pronoun(
        protagonist=protagonist,
        story_map=story_map,
        story_context=story_context,
        scenes=scene_list,
    )
    protagonist_card = _find_character_card_for_name(cards, protagonist_name)
    protagonist_spoken_name = (
        _character_card_spoken_name(protagonist_card) or protagonist_name
    )

    def identity_keys(card) -> set:
        keys = set()
        for value in (
            _character_card_name_forms(card)
            + [card.get("source_name")]
            + list(card.get("aliases") or [])
        ):
            key = _normalize_burmese_text(value or "")
            if key:
                keys.add(key)
        return keys

    context_keys = set()
    if treat_context_as_introduced:
        # Direct later windows receive a context built from narration
        # the listener has already heard, so those people do not need
        # a fresh full introduction.  The worker instead passes the
        # *entire* script from its first group while its context was
        # built by analysing those same not-yet-voiced groups;
        # treating analysis knowledge as already-spoken introductions
        # would disable this pass exactly where it is needed.
        for context_card in context_cards:
            context_keys.update(identity_keys(context_card))
        for character in normalized_context.get("characters") or []:
            key = _normalize_burmese_text(character or "")
            if key:
                context_keys.add(key)

    def burmese_detail(value, forms) -> str:
        detail = _clean_story_text(value, 140)
        if (
            not detail
            or _tts_unsafe_script_chars(detail)
            or not any("\u1000" <= char <= "\u109f" for char in detail)
            or any(char in detail for char in "။?!")
        ):
            return ""
        for form in sorted(forms, key=len, reverse=True):
            if form and detail.startswith(form):
                detail = detail[len(form):].lstrip(" ကကတော့ဟာ")
        for suffix in ("ဖြစ်ပါတယ်", "ဖြစ်တယ်", "ဖြစ်သူ", "ပါ"):
            if detail.endswith(suffix):
                detail = detail[:-len(suffix)].rstrip()
                break
        return detail.strip()

    for card in cards:
        spoken_name = _character_card_spoken_name(card)
        if not spoken_name or _tts_unsafe_script_chars(spoken_name):
            continue
        if (
            protagonist_spoken_name
            and _normalize_burmese_text(spoken_name)
            == _normalize_burmese_text(protagonist_spoken_name)
        ):
            continue
        if identity_keys(card) & context_keys:
            continue
        forms = [
            form
            for form in _character_card_name_forms(card)
            if form and not _tts_unsafe_script_chars(form)
        ]
        if not forms:
            continue
        forms = sorted(set(forms), key=len, reverse=True)
        short_name = _character_card_short_name(card)

        first_location = None
        first_form = ""
        for scene_index, scene in enumerate(scene_list):
            sentences = _split_sentences(str(scene.get("burmese") or ""))
            for sentence_index, sentence in enumerate(sentences):
                matched = next(
                    (form for form in forms if form and form in sentence),
                    "",
                )
                if matched:
                    first_location = (scene_index, sentence_index)
                    first_form = matched
                    break
            if first_location is not None:
                break
        if first_location is None:
            continue

        scene_index, sentence_index = first_location
        sentences = _split_sentences(
            str(scene_list[scene_index].get("burmese") or "")
        )
        first_sentence = sentences[sentence_index] if sentence_index < len(sentences) else ""
        if (
            short_name
            and _normalize_burmese_text(short_name)
            != _normalize_burmese_text(spoken_name)
            and first_form == short_name
            and spoken_name not in first_sentence
        ):
            first_sentence = first_sentence.replace(short_name, spoken_name, 1)
            sentences[sentence_index] = first_sentence
            scene_list[scene_index]["burmese"] = "".join(sentences)
            stats["full_name_first_mentions"] += 1

        # Recompute the first-mention window after any full-name fix.
        sentences = _split_sentences(
            str(scene_list[scene_index].get("burmese") or "")
        )
        first_sentence = sentences[sentence_index] if sentence_index < len(sentences) else ""
        first_window = first_sentence
        if sentence_index + 1 < len(sentences):
            first_window += sentences[sentence_index + 1]

        introduction = _clean_story_text(card.get("introduction"), 240)
        candidate = ""
        if (
            introduction
            and not _tts_unsafe_script_chars(introduction)
            and any("\u1000" <= char <= "\u109f" for char in introduction)
            and any(form and form in introduction for form in forms)
        ):
            candidate = introduction
        else:
            role = burmese_detail(card.get("role"), forms)
            relation = burmese_detail(card.get("relation"), forms)
            details = []
            for detail in (role, relation):
                if detail and detail not in details:
                    details.append(detail)
            if len(details) >= 2:
                candidate = (
                    f"{spoken_name} ဆိုတာက {details[0]} ဖြစ်ပြီး "
                    f"{details[1]} ဖြစ်တယ်"
                )
            elif details:
                candidate = f"{spoken_name} ဆိုတာက {details[0]} ဖြစ်တယ်"
        if not candidate:
            continue
        candidate = _polish_text_for_speech(candidate).strip()
        if _pronoun:
            # A card introduction is narration by the protagonist;
            # a model can copy the opposite-gender self-pronoun into
            # the relation field even when the scenes are correct.
            candidate = _replace_wrong_narrator_pronoun(candidate, _pronoun)
        if (
            not candidate
            or len(candidate) > 260
            or _tts_unsafe_script_chars(candidate)
            or spoken_name not in candidate
        ):
            continue

        normalized_window = _normalize_burmese_text(first_window)
        normalized_candidate = _normalize_burmese_text(candidate)
        detail_fragments = []
        for value in (
            introduction,
            card.get("identity_anchor"),
            card.get("role"),
            card.get("relation"),
            card.get("visual_cue"),
        ):
            detail = burmese_detail(value, forms)
            if len(_normalize_burmese_text(detail)) >= 8:
                detail_fragments.append(_normalize_burmese_text(detail))
        relation_terms = (
            "အစ်ကို", "အစ်မ", "ညီ", "ညီမ", "အဖေ", "အမေ",
            "သား", "သမီး", "ခင်ပွန်း", "ဇနီး", "သူငယ်ချင်း",
            "ဆရာ", "တပည့်", "ခေါင်းဆောင်", "အဖွဲ့ဝင်",
        )
        detail_blob = _normalize_burmese_text(
            " ".join(
                str(card.get(key) or "")
                for key in (
                    "introduction",
                    "identity_anchor",
                    "role",
                    "relation",
                    "visual_cue",
                )
            )
        )
        reciprocal_intro = bool(
            any(form and form in first_window for form in forms)
            and any(term in first_window for term in relation_terms)
            and any(term in detail_blob for term in relation_terms)
        )
        already_introduced = bool(
            normalized_candidate in normalized_window
            or any(fragment in normalized_window for fragment in detail_fragments)
            or reciprocal_intro
        )
        if already_introduced:
            continue
        if normalized_candidate in _normalize_burmese_text(
            str(scene_list[scene_index].get("burmese") or "")
        ):
            continue
        insert_index = sentence_index
        if (
            scene_index == 0
            and sentence_index == 0
            and protagonist_spoken_name
            and protagonist_spoken_name in first_sentence
            and _pronoun
            and _pronoun in first_sentence
        ):
            # Never push another person's introduction ahead of the
            # protagonist-narrator's own opening identity.
            insert_index = 1
        sentences.insert(insert_index, candidate)
        scene_list[scene_index]["burmese"] = " ".join(
            sentence.strip() for sentence in sentences if sentence.strip()
        )
        stats["introductions_inserted"] += 1
        stats["introduced_identities"].append(spoken_name)
        stats["introduced_scene_indexes"].append(int(scene_index))

    return scene_list, stats


def _repair_ambiguous_sentence_actors(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
    protagonist: str = "",
) -> tuple:
    """Replace clear ``သူ/သူမ`` actor references with the locked name.

    Scene-opening repair alone missed the common production pattern
    inside a scene: a named person acts, then several following
    sentences drift into ``သူက`` while another person is also present.
    This pass only replaces an early particle-marked pronoun when the
    overlapping story beat or the immediately preceding narration
    identifies exactly one non-protagonist.  It does not guess across
    an actor switch, and quoted dialogue is never rewritten.
    """
    scene_list = [
        dict(scene)
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    stats = {
        "sentence_pronoun_replacements": 0,
        "repaired_sentence_refs": [],
    }
    if not scene_list:
        return scene_list, stats

    normalized_context = _normalize_story_context(story_context or {})
    normalized_map = _normalize_story_map(story_map)
    cards = _normalize_character_cards(
        list(normalized_context.get("character_cards") or [])
        + list(normalized_map.get("character_cards") or [])
    )
    if not cards:
        return scene_list, stats
    protagonist_name, _gender, protagonist_pronoun, _merged = (
        _resolve_protagonist_pronoun(
            protagonist=protagonist,
            story_map=story_map,
            story_context=story_context,
            scenes=scene_list,
        )
    )
    protagonist_card = _find_character_card_for_name(cards, protagonist_name)
    protagonist_spoken_name = (
        _character_card_spoken_name(protagonist_card) or protagonist_name
    )
    beats = [
        beat
        for beat in (normalized_map.get("beats") or [])
        if isinstance(beat, dict)
    ]

    def identities_in_text(value: str, *, extended: bool = False) -> set:
        identities = set()
        text = str(value or "")
        unquoted = _strip_quoted_speech(text)
        for card in cards:
            spoken_name = _character_card_spoken_name(card)
            if not spoken_name:
                continue
            forms = list(_character_card_name_forms(card))
            if extended:
                if card.get("source_name"):
                    forms.append(str(card["source_name"]))
                forms.extend(str(alias) for alias in (card.get("aliases") or []))
            is_protagonist = bool(
                protagonist_spoken_name
                and _normalize_burmese_text(spoken_name)
                == _normalize_burmese_text(protagonist_spoken_name)
            )
            if any(form and form in text for form in forms) or (
                is_protagonist
                and protagonist_pronoun
                and protagonist_pronoun in unquoted
            ):
                identities.add(spoken_name)
        return identities

    def beat_for_scene(scene: dict, scene_index: int) -> dict:
        if not beats:
            return {}
        try:
            scene_start = float(scene.get("start") or 0)
            scene_end = float(scene.get("end") or scene_start)
        except (TypeError, ValueError):
            scene_start = scene_end = 0.0
        best_beat = {}
        best_overlap = 0.0
        for beat in beats:
            try:
                beat_start = float(beat.get("start") or 0)
                beat_end = float(beat.get("end") or beat_start)
            except (TypeError, ValueError):
                continue
            overlap = min(scene_end, beat_end) - max(scene_start, beat_start)
            if overlap > best_overlap:
                best_overlap = overlap
                best_beat = beat
        if best_beat:
            return best_beat
        beat_index = min(
            len(beats) - 1,
            int(scene_index * len(beats) / max(1, len(scene_list))),
        )
        return beats[beat_index]

    markers = (
        ("သူမကို", "ကို"),
        ("သူ့ကို", "ကို"),
        ("သူမရဲ့", "ရဲ့"),
        ("သူ့ရဲ့", "ရဲ့"),
        ("သူမက", "က"),
        ("သူက", "က"),
    )
    transition_markers = (
        "တစ်ဖက်မှာ",
        "တစ်ဖက်မှာတော့",
        "နောက်တစ်နေရာ",
        "အခြားတစ်နေရာ",
        "အဲဒီအချိန်မှာပဲ",
        "ဒီအချိန်မှာပဲ",
    )
    seen_identities = {
        _character_card_spoken_name(card)
        for card in (normalized_context.get("character_cards") or [])
        if _character_card_spoken_name(card)
    }
    previous_nonprotagonist_identities = set()
    recent_identity_sets = []

    for scene_index, scene in enumerate(scene_list):
        beat = beat_for_scene(scene, scene_index)
        beat_blob = " ".join(
            str(beat.get(key) or "")
            for key in (
                "beat",
                "trigger",
                "dialogue",
                "reaction",
                "result",
                "visible_text",
                "why_it_matters",
            )
        )
        beat_nonprotagonist = {
            identity
            for identity in identities_in_text(beat_blob, extended=True)
            if _normalize_burmese_text(identity)
            != _normalize_burmese_text(protagonist_spoken_name)
        }
        sentences = _split_sentences(str(scene.get("burmese") or ""))
        changed_scene = False
        for sentence_index, sentence in enumerate(sentences):
            identities = identities_in_text(sentence)
            nonprotagonist_identities = {
                identity
                for identity in identities
                if _normalize_burmese_text(identity)
                != _normalize_burmese_text(protagonist_spoken_name)
            }
            unquoted = _strip_quoted_speech(sentence)
            has_ambiguous_marker = any(
                0 <= unquoted.find(marker) <= 90
                for marker, _particle in markers
            )
            if has_ambiguous_marker and not nonprotagonist_identities:
                candidate = ""
                if len(beat_nonprotagonist) == 1:
                    candidate = next(iter(beat_nonprotagonist))
                elif len(previous_nonprotagonist_identities) == 1:
                    recent_union = set()
                    for identity_set in recent_identity_sets[-3:]:
                        recent_union.update(identity_set)
                    has_transition = any(
                        marker in unquoted[:60]
                        for marker in transition_markers
                    )
                    if len(recent_union) == 1 and not has_transition:
                        candidate = next(
                            iter(previous_nonprotagonist_identities)
                        )
                if candidate:
                    candidate_card = _find_character_card_for_name(
                        cards, candidate
                    )
                    candidate_reference = (
                        _character_card_short_name(candidate_card)
                        if candidate in seen_identities
                        else _character_card_spoken_name(candidate_card)
                        or candidate
                    )
                    if candidate_reference and not _tts_unsafe_script_chars(
                        candidate_reference
                    ):
                        replaced = False

                        def replace_marker(chunk: str) -> str:
                            nonlocal replaced
                            if replaced:
                                return chunk
                            best = None
                            for marker, particle in markers:
                                position = chunk.find(marker)
                                if position < 0 or position > 90:
                                    continue
                                if best is None or position < best[0] or (
                                    position == best[0]
                                    and len(marker) > len(best[1])
                                ):
                                    best = (position, marker, particle)
                            if best is None:
                                return chunk
                            position, marker, particle = best
                            replaced = True
                            return (
                                chunk[:position]
                                + candidate_reference
                                + particle
                                + chunk[position + len(marker):]
                            )

                        repaired_sentence = _map_unquoted_text(
                            sentence, replace_marker
                        )
                        if replaced and repaired_sentence != sentence:
                            sentences[sentence_index] = repaired_sentence
                            sentence = repaired_sentence
                            changed_scene = True
                            stats["sentence_pronoun_replacements"] += 1
                            stats["repaired_sentence_refs"].append(
                                f"{scene_index}:{sentence_index}"
                            )
                            identities = identities_in_text(sentence)
                            nonprotagonist_identities = {
                                identity
                                for identity in identities
                                if _normalize_burmese_text(identity)
                                != _normalize_burmese_text(
                                    protagonist_spoken_name
                                )
                            }
            if nonprotagonist_identities:
                previous_nonprotagonist_identities = set(
                    nonprotagonist_identities
                )
                recent_identity_sets.append(set(nonprotagonist_identities))
                if len(recent_identity_sets) > 6:
                    del recent_identity_sets[:-6]
                seen_identities.update(nonprotagonist_identities)
        if changed_scene:
            scene["burmese"] = "".join(sentences)

    return scene_list, stats


def _normalize_direct_script_payload(data, *, chunk_duration: float = 0.0) -> dict:
    """Normalize Gemini scene aliases/timings into the renderer's contract."""
    if isinstance(data, str):
        try:
            data = _parse_gemini_json_text(data)
        except Exception:
            data = {}

    raw_scenes = _find_direct_scene_list(data)
    scenes = []
    for item in raw_scenes or []:
        text = _scene_text_from_mapping(item)
        if not text:
            continue
        scene = dict(item) if isinstance(item, dict) else {}
        start = _direct_float_or_none(
            scene.get("start", scene.get("start_time", scene.get("start_seconds")))
        )
        end = _direct_float_or_none(
            scene.get("end", scene.get("end_time", scene.get("end_seconds")))
        )
        scene.update({"start": start, "end": end, "burmese": text})
        scenes.append(scene)

    duration = max(0.0, float(chunk_duration or 0))
    if scenes and duration > 0:
        numeric_starts = [
            float(scene["start"])
            for scene in scenes
            if scene.get("start") is not None
        ]
        numeric_ends = [
            float(scene["end"])
            for scene in scenes
            if scene.get("end") is not None
        ]
        if numeric_starts and numeric_ends:
            min_start = min(numeric_starts)
            max_end = max(numeric_ends)
            # A later window's model sometimes answers with *absolute*
            # source timestamps (240-353) even though the uploaded
            # chunk itself is only 113s long.  Clamping those values
            # first would crush every scene against the chunk end and
            # make the edit unusable; subtract the window offset so
            # relative scene order/spans survive.
            if min_start >= duration * 0.95 and max_end > duration:
                for scene in scenes:
                    if scene.get("start") is not None:
                        scene["start"] = max(0.0, float(scene["start"]) - min_start)
                    if scene.get("end") is not None:
                        scene["end"] = max(0.0, float(scene["end"]) - min_start)
    if scenes:
        step = duration / len(scenes) if duration > 0 else 1.0
        for index, scene in enumerate(scenes):
            start = scene.get("start")
            end = scene.get("end")
            if start is None:
                start = step * index if duration > 0 else float(index)
            # Preserve model-provided timings here; sort_scenes() puts them
            # in chronological order immediately after normalization.
            start = max(0.0, float(start))
            if duration > 0:
                start = min(start, max(0.0, duration - 0.01))
            if end is None or float(end) <= start:
                end = min(duration, start + step) if duration > 0 else start + 1.0
            if duration > 0:
                end = min(duration, float(end))
            if float(end) <= start:
                end = min(duration, start + 0.01) if duration > 0 else start + 0.01
            scene["start"] = round(float(start), 3)
            scene["end"] = round(float(end), 3)

    if scenes and duration > 0:
        # Repair degenerate model timings before they can reach the
        # alignment plan: duplicate or reversed starts would leave a
        # scene with *zero* available footage, which renders as one
        # frozen frame under its whole narration.  Sort into story
        # order and guarantee strictly increasing starts (every
        # scene keeps a minimum real span) with ends contained
        # within [start, next start].
        scenes.sort(
            key=lambda s: (
                float(s.get("start") or 0),
                float(s.get("end") or 0),
            )
        )
        count = len(scenes)
        min_span = max(0.25, min(1.0, duration / (2.0 * count)))
        cursor = 0.0
        for scene in scenes:
            start = max(float(scene.get("start") or 0), cursor)
            start = min(start, max(0.0, duration - min_span))
            scene["start"] = round(start, 3)
            cursor = start + min_span
        cursor = duration
        for scene in reversed(scenes):
            start = min(
                float(scene.get("start") or 0),
                max(0.0, cursor - min_span),
            )
            scene["start"] = round(max(0.0, start), 3)
            cursor = float(scene["start"])
        for index, scene in enumerate(scenes):
            start = float(scene["start"])
            limit = (
                float(scenes[index + 1]["start"])
                if index + 1 < count
                else duration
            )
            end = float(scene.get("end") or limit)
            end = min(max(end, min(limit, start + min_span)), limit)
            scene["end"] = round(end, 3)

    raw_cuts = _find_direct_payload_value(data, ("cuts", "cut_scenes")) or []
    cuts = []
    if isinstance(raw_cuts, list):
        for item in raw_cuts:
            if not isinstance(item, dict):
                continue
            start = _direct_float_or_none(
                item.get("start", item.get("start_time", item.get("start_seconds")))
            )
            end = _direct_float_or_none(
                item.get("end", item.get("end_time", item.get("end_seconds")))
            )
            if start is None or end is None or float(end) <= float(start):
                continue
            cut = dict(item)
            cut.update({"start": float(start), "end": float(end)})
            cuts.append(cut)

    protagonist_value = _find_direct_payload_value(
        data, ("protagonist", "main_character", "hero", "heroine")
    )
    protagonist = _clean_protagonist_name(protagonist_value)
    story_map = _normalize_story_map(
        _find_direct_payload_value(
            data,
            ("story_map", "story_bible", "story_plan"),
        ),
        chunk_duration=duration,
    )
    protagonist_gender, protagonist_pronoun = _protagonist_gender_and_pronoun(
        data if isinstance(data, dict) else {},
        story_map,
        protagonist=protagonist,
        character_cards=story_map.get("character_cards") or [],
    )
    if not protagonist_pronoun:
        protagonist_pronoun = _dominant_narrator_pronoun(scenes)
        protagonist_gender = _gender_from_pronoun(protagonist_pronoun)
    if protagonist_gender:
        story_map["protagonist_gender"] = protagonist_gender
        protagonist_card = _find_character_card_for_name(
            story_map.get("character_cards") or [],
            protagonist,
        )
        if protagonist_card and not protagonist_card.get("gender"):
            protagonist_card["gender"] = protagonist_gender
    if protagonist_pronoun:
        story_map["protagonist_pronoun"] = protagonist_pronoun
    return {
        "scenes": scenes,
        "cuts": cuts,
        "protagonist": protagonist,
        "protagonist_gender": protagonist_gender,
        "protagonist_pronoun": protagonist_pronoun,
        "narrator_perspective": NARRATOR_PERSPECTIVE,
        "story_map": story_map,
    }


async def extract_story_summary(
    scenes: list,
    client,
    story_map: dict = None,
) -> dict:
    """Build a continuity bible for the next window, not just a blurb.

    A two/three-line summary loses exactly what a listener needs to
    follow the next two minutes: who everyone is, why they acted,
    what changed, and what is still unresolved.  The returned dict
    is normalized so older callers can keep using ``characters`` as
    names while newer prompts also receive character cards, the
    ordered beat chain, the current goal/conflict and open threads.
    """
    scene_texts = [
        str(scene.get("burmese") or "").strip()
        for scene in (scenes or [])
        if isinstance(scene, dict) and str(scene.get("burmese") or "").strip()
    ]
    if not scene_texts:
        return _normalize_story_context({})
    all_text = "\n".join(scene_texts)
    normalized_map = _normalize_story_map(story_map)
    map_json = json.dumps(normalized_map, ensure_ascii=False) if normalized_map else "{}"
    prompt = f"""
အောက်ပါ မြန်မာဇာတ်လမ်းအပိုင်းကို ဖတ်ပြီး နောက်အပိုင်းရေးရာတွင် မှတ်ထားရမည့် continuity bible ထုတ်ပေးပါ။
မှတ်ချက် — Narration narrator မှာ အဓိကဇာတ်ကောင်ကိုယ်တိုင်ဖြစ်သည်။ Summary metadata ထဲ protagonist spoken_name, protagonist_gender နဲ့ locked protagonist_pronoun ကို script/story_map က အတည်ပြုသလောက် ဆက်ထိန်းပြီး မသေချာရင် ကွက်လပ်ထားပါ။
Cast Lock ကို မပြောင်းပါနှင့် — ဇာတ်ကောင်တစ်ဦးစီအတွက် script/story_map မှာ သုံးထားပြီးသား full spoken_name, approved short_name, introduction, identity_anchor, name_evidence_text နဲ့ name_reveal_bridge ကိုသာ ဆက်ထိန်းပါ။ မူရင်းအမည် သို့မဟုတ် variant ကို aliases မှာသာ ထားပါ။
မသေချာသော ဆက်နွယ်မှု၊ ရည်ရွယ်ချက်နှင့် အမည်ကို မတီထွင်ပါနှင့်။ Narration မှာ ပြောရမည့်အမည်များကို မြန်မာအသံထွက်ဖြင့်သာ ရေးပါ။
ဇာတ်ကောင်တစ်ဦးချင်းစီအတွက် ဘယ်သူလဲ၊ အဓိကဇာတ်ကောင်/အခြားသူနဲ့ ဘယ်လို ဆက်နွယ်လဲ၊ ပထမဆုံးမိတ်ဆက်ခဲ့တဲ့ မြန်မာစာကြောင်း (introduction)၊ ပြန်ပေါ်လာရင် အမှတ်ရစေမယ့် စာကြောင်းတို (identity_anchor)၊ နောက်ပိုင်း နေ့တိုင်းခေါ်ပုံ (short_name; source သုံးထားမှသာ)၊ အမည်အတည်ပြုစာသား (name_evidence_text)၊ label ကနေ အမည်အစစ်ပြောင်းထားလျှင် bridge (name_reveal_bridge)၊ လက်ရှိလိုချင်တာ (goal) နဲ့ ဘာကြောင့်လဲ (motivation)၊ အမည်ကို subtitle/name-card/dialogue/visual label ဘယ်ကရလဲနှင့် မြင်မှတ်ချက်ကို ရှင်းပါ။
အဓိကပြဿနာကို ရေးရာမှာ ဘယ်သူက ဘာကြောင့် ဘာကို အတိအကျ တောင်း/ဖိအားပေးနေလဲနဲ့ မလိုက်နာ/မအောင်မြင်ရင် ဘာဆုံးရှုံးနိုင်လဲ (conflict_stakes) ကိုပါ script/map ထဲ တကယ်ပါသလောက်သာ မှတ်ပါ။ မဖြေရှင်းရသေးတဲ့ အဓိကမေးခွန်း (central_question) ကိုလည်း တစ်ကြောင်းသိမ်းပါ။
Story beats များကို အစဉ်အတိုင်း၊ ဖြစ်ရပ်အကြောင်းရင်း → စကားပြော/လုပ်ဆောင်ချက် → တုံ့ပြန်မှု/ဆုံးဖြတ်ချက် → အကျိုးဆက် ပုံစံရအောင် တိုတိုရေးပါ။
ဇာတ်လမ်းထဲက system/rank/quality/skill/level/title/အဖွဲ့/နေရာ/ပစ္စည်းအခေါ်တွေကို `terms` မှာ spoken_term တစ်မျိုးတည်း၊ source_term, ဒီဇာတ်လမ်းထဲ အမှန်အဓိပ္ပာယ်/လုပ်ဆောင်ချက်, first_explanation နဲ့ ထိန်းပါ။ အဓိပ္ပာယ်ကို genre အလေ့အထကနေ မှန်းမဖွင့်ရဘူး။ အရေးကြီးတဲ့ name card/system Panel/document လို ဖန်သားပြင်စာရဲ့ မြန်မာအဓိပ္ပာယ်ကိုလည်း important_facts ထဲ မမေ့အောင် ထိန်းပါ။
ယခု script မှ အတည်ပြုထားပြီး story_map (ရှိလျှင်) — အမှားမပါအောင် အခြေခံပြီး ခိုင်မာသောအချက်များကိုသာ ဆက်ထိန်းပါ:
{map_json}

Script:
{all_text}

Return JSON:
{{"characters": ["spoken_name များ"], "character_cards": [{{"spoken_name": "ပထမဆုံးမိတ်ဆက်မှာ သုံးရမည့် အမည်အပြည့် သို့မဟုတ် label", "source_name": "မူရင်းအမည် (ရှိလျှင်)", "gender": "male|female| (source က သိနိုင်လျှင်သာ; မသေချာရင် ဗလာ)", "role": "ဘယ်သူလဲ", "relation": "အဓိကဇာတ်ကောင်/အခြားသူနဲ့ ဆက်နွယ်ပုံ", "introduction": "ပထမဆုံးမိတ်ဆက်ရန် မြန်မာစာကြောင်း (spoken_name + အခန်းကဏ္ဍ + ဆက်နွယ်ပုံ/အဖွဲ့/နေရာ)", "identity_anchor": "ပြန်ပေါ်လာတိုင်း အမှတ်ရစေရန် တိုတဲ့ မြန်မာစာကြောင်း (spoken_name + အခန်းကဏ္ဍ/ဆက်နွယ်ပုံ)", "short_name": "နောက်ပိုင်း နေ့တိုင်းပြန်ခေါ်မယ့် တိုပြီး သဘာဝကျတဲ့ အမည်ပုံစံ (source သုံးထားတဲ့ short form သာ; မရှိရင် ဗလာ)", "name_evidence_text": "အမည်ကို အတည်ပြုပေးတဲ့ subtitle/name-card/dialogue စာသား အတိအကျ", "name_reveal_bridge": "အရင် label ကနေ အမည်အစစ်သို့ ပြောင်းချိန် တစ်ကြိမ်တည်းသုံးမယ့် မြန်မာစာကြောင်း (reveal ရှိလျှင်)", "goal": "လက်ရှိ လိုချင်တာ", "motivation": "ဘာကြောင့် လိုချင်/လုပ်ရတာလဲ", "aliases": ["မူရင်း/variant/အဟောင်း label"], "name_source": "subtitle|on_screen|dialogue|visual_label", "confidence": "confirmed|descriptive|uncertain", "visual_cue": "မျက်မြင်မှတ်ချက်"}}], "protagonist": "အဓိကဇာတ်ကောင်၏ spoken_name", "protagonist_gender": "male|female| (source က သိနိုင်လျှင်သာ)", "protagonist_pronoun": "ကျွန်တော်|ကျွန်မ| (gender သိလျှင်သာ)", "narrator_perspective": "first_person_protagonist", "summary": "အကြောင်းရင်း၊ ဆုံးဖြတ်ချက်၊ အကျိုးဆက်ပါသော အစဉ်လိုက် အကျဉ်း ငါးကြောင်းမှ ရှစ်ကြောင်းအထိ", "story_beats": ["အစဉ်လိုက်အရေးကြီးဖြစ်ရပ်များ"], "current_goal": "လက်ရှိရည်မှန်းချက်", "current_conflict": "လက်ရှိအဓိကပြဿနာ", "conflict_stakes": "မလိုက်နာ/မအောင်မြင်ရင် ဘာဆုံးရှုံးနိုင်လဲ", "central_question": "မဖြေရှင်းရသေးတဲ့ အဓိကမေးခွန်း", "terms": [{{"spoken_term": "Narration မှာ အမြဲသုံးရမယ့် မြန်မာအခေါ်တစ်မျိုးတည်း", "source_term": "မူရင်းအခေါ်/ဖန်သားပြင်စာသား", "meaning": "ဒီဇာတ်လမ်းထဲက source အတည်ပြုနိုင်တဲ့ အဓိပ္ပာယ်/လုပ်ဆောင်ချက်", "first_explanation": "ပထမဆုံးအကြိမ် ပြောရမယ့် ရှင်းလင်းတဲ့ မြန်မာရှင်းပြချက်", "category": "system|rank|skill|level|title|organization|place|item|rule", "evidence_source": "subtitle|on_screen|dialogue|visual_label", "aliases": ["မသုံးရန် variant"]}}], "open_threads": ["မဖြေရှင်းရသေးသည့်အရာများ"], "important_facts": ["နောက်ပိုင်း မမေ့ရမည့်အချက်များ"], "setting": "လက်ရှိနေရာ/အခြေအနေ", "last_scene": "နောက်ဆုံးအခြေအနေ"}}
    """.strip()
    try:
        data = await _generate_direct_gemini_json(
            client,
            prompt,
            purpose="story summary",
            max_output_tokens=8192,
        )
        if not isinstance(data, dict):
            raise ValueError("summary JSON is not an object")
        summary_context = _normalize_story_context(data)
        map_context = _story_context_from_story_map(
            normalized_map,
            last_scene=scene_texts[-1],
        )
        merged = _merge_story_contexts(map_context, summary_context)
        return merged
    except Exception as e:
        logger.warning(f"Summary error: {e}")
        fallback = _normalize_story_context(
            {
                "characters": [],
                "protagonist": "",
                "narrator_perspective": NARRATOR_PERSPECTIVE,
                "summary": all_text[-1200:],
                "last_scene": scene_texts[-1],
            },
            scenes=scenes,
            derive_beats=True,
        )
        merged = _merge_story_contexts(
            _story_context_from_story_map(
                normalized_map,
                last_scene=scene_texts[-1],
            ),
            fallback,
        )
        return merged


def _with_required_coverage(settings: dict = None) -> dict:
    """Return job settings with product-wide required values applied.

    A saved/stale coverage value below 90 must never make an individual
    source produce a short recap.  The source is also always partitioned
    into fixed two-minute parts, regardless of a stale 3/5/10-minute
    setting saved by an older bot version.
    """
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    try:
        coverage = float(s.get("coverage") or MINIMUM_SCRIPT_COVERAGE_PERCENT)
    except (TypeError, ValueError):
        coverage = float(MINIMUM_SCRIPT_COVERAGE_PERCENT)
    coverage = max(float(MINIMUM_SCRIPT_COVERAGE_PERCENT), min(100.0, coverage))
    s["coverage"] = int(coverage) if coverage.is_integer() else coverage
    s["chunk"] = SOURCE_SEGMENT_SECONDS
    s["pov"] = "first"
    try:
        if float(s.get("rate") or 0) in (5.5, 7.5):
            s["rate"] = DEFAULT_SETTINGS["rate"]
    except (TypeError, ValueError):
        s["rate"] = DEFAULT_SETTINGS["rate"]
    return s


def _settings_coverage_ratio(settings: dict = None) -> float:
    s = _with_required_coverage(settings)
    return float(s["coverage"]) / 100.0


def _settings_script_rate(settings: dict = None) -> float:
    """Chars/second used to size scripts (chars = seconds x rate).

    The *learned* rate for the voice that will actually speak wins, so
    each voice is sized at its own measured speed (Edge Thiha measures
    ~18-20 chars/s in production; Gemini TTS seeds at 10) instead of one
    shared estimate that measured calibration would then have to shred
    or pad.  An explicitly changed 🗣️ setting (anything
    other than the shipped default) is still honoured as a manual
    override -- that is the user deliberately asking for a different
    reading speed.
    """
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    try:
        configured = float(s.get("rate") or 0)
    except (TypeError, ValueError):
        configured = 0.0
    learned = learned_chars_per_second()
    if configured <= 0:
        return learned
    if abs(configured - float(DEFAULT_SETTINGS.get("rate") or 0)) < 1e-9:
        return learned
    return configured


def _minimum_script_chars(target_chars: int) -> int:
    return int(math.ceil(max(0, int(target_chars or 0)) * SCRIPT_MIN_CHAR_RATIO))


def _settings_speed(settings: dict = None) -> float:
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    try:
        speed = float(s.get("speed") or 1.0)
    except (TypeError, ValueError):
        speed = 1.0
    return speed if speed > 0 else 1.0


def _target_final_seconds(source_duration: float, settings: dict = None) -> float:
    """Actual final-video seconds requested for a source duration."""
    return max(0.0, float(source_duration or 0)) * _settings_coverage_ratio(settings)


def _final_duration_tolerance_seconds(source_duration: float) -> float:
    source = max(0.0, float(source_duration or 0))
    return max(
        FINAL_DURATION_TOLERANCE_MIN_SECONDS,
        source * FINAL_DURATION_TOLERANCE_RATIO,
    )


def _final_duration_window(source_duration: float, settings: dict = None) -> tuple:
    target = _target_final_seconds(source_duration, settings)
    tolerance = _final_duration_tolerance_seconds(source_duration)
    return target, max(0.0, target - tolerance), target + tolerance


def _duration_is_on_target(
    actual_seconds: float,
    source_duration: float,
    settings: dict = None,
) -> bool:
    if float(source_duration or 0) <= 0:
        return False
    _, low, high = _final_duration_window(source_duration, settings)
    return low <= float(actual_seconds or 0) <= high


def _duration_meets_minimum(
    actual_seconds: float,
    source_duration: float,
    settings: dict = None,
) -> bool:
    """True unless the narration is *short* of the target window.

    User rule: finished speech is never cut back to fit the 90%
    target -- when the narration comes out long (but still inside
    the source's own length) it is kept whole.  Only "short"
    fails here: a too-short recap is a summary, which the user
    rejects just as strongly, so expansion/retry/refusal on the
    low side stays strict.  The one hard ceiling is the source
    duration itself (see ``_duration_exceeds_source``): a final
    video must never be longer than the original.
    """
    if float(source_duration or 0) <= 0:
        return False
    _, low, _high = _final_duration_window(source_duration, settings)
    return float(actual_seconds or 0) >= low


def _source_duration_ceiling(source_duration: float) -> float:
    """Longest acceptable final for a source: the source itself plus
    a hair of container/fade rounding tolerance."""
    source = max(0.0, float(source_duration or 0))
    return source + max(2.0, source * 0.005)


def _duration_exceeds_source(
    actual_seconds: float,
    source_duration: float,
) -> bool:
    """True when a result runs *longer than the original video*.

    The recap may sit anywhere between the 90% target and the
    source's own length, but it must never exceed the source:
    the alignment renderer would have to invent footage (freeze
    frames) and the user explicitly rejects a final that is
    longer than the video they sent.  A hair of tolerance covers
    container/fade rounding only.
    """
    source = float(source_duration or 0)
    if source <= 0:
        return False
    return float(actual_seconds or 0) > _source_duration_ceiling(source)


def _duration_within_limits(
    actual_seconds: float,
    source_duration: float,
    settings: dict = None,
) -> bool:
    """Final-delivery rule: at/above the 90% floor, never over source."""
    return _duration_meets_minimum(
        actual_seconds, source_duration, settings
    ) and not _duration_exceeds_source(actual_seconds, source_duration)


def _duration_status(actual_seconds: float, source_duration: float, settings: dict = None) -> str:
    if float(source_duration or 0) <= 0:
        return "unknown"
    _, low, high = _final_duration_window(source_duration, settings)
    actual = float(actual_seconds or 0)
    if actual < low:
        return "short"
    if actual > high:
        return "long"
    return "on_target"


def _settings_pause_seconds(settings: dict = None) -> float:
    s = {**DEFAULT_SETTINGS, **(settings or {})}
    try:
        return max(0.0, float(s.get("pause") or 0))
    except (TypeError, ValueError):
        return PAUSE_AFTER_SCENE


def _clip_array(clip) -> np.ndarray:
    try:
        return np.asarray(clip if clip is not None else [], dtype=np.float32).reshape(-1)
    except Exception:
        return np.zeros(0, dtype=np.float32)


def _clip_is_silent(clip) -> bool:
    arr = _clip_array(clip)
    return bool(arr.size == 0 or float(np.max(np.abs(arr))) < 0.001)


def _narration_measurements(scenes: list, clips: list, settings: dict = None) -> dict:
    """Measure actual post-TTS duration and this job's real chars/second."""
    scene_list = list(scenes or [])
    clip_list = list(clips or [])
    pause_seconds = _settings_pause_seconds(settings)
    speech_seconds = 0.0
    spoken_chars = 0
    spoken_seconds = 0.0
    silent_count = 0
    for index, clip in enumerate(clip_list):
        arr = _clip_array(clip)
        seconds = float(arr.size) / SAMPLE_RATE if SAMPLE_RATE else 0.0
        speech_seconds += seconds
        if _clip_is_silent(arr):
            silent_count += 1
            continue
        text = ""
        if index < len(scene_list) and isinstance(scene_list[index], dict):
            text = str(scene_list[index].get("burmese") or "").strip()
        if text and seconds > 0:
            spoken_chars += len(text)
            spoken_seconds += seconds
    pause_total = pause_seconds * max(0, len(scene_list) - 1)
    measured_rate = (spoken_chars / spoken_seconds) if spoken_seconds > 0 else 0.0
    if measured_rate <= 0:
        measured_rate = _settings_script_rate(settings) * _settings_speed(settings)
    # Effective rate over *all* produced audio (including any quiet
    # or silent slices and pauses inside the synthesized audio).
    # Calibration must use this one: the spoken-only rate above
    # inflates whenever some clips measure as silent, which once
    # made the "too long" trim compute a desired char count HIGHER
    # than the current script -- calibration stalled and refused a
    # perfectly fixable 120s narration (target 113s).
    total_script_chars = script_total_chars(scene_list)
    effective_rate = (
        (total_script_chars / speech_seconds) if speech_seconds > 0 else 0.0
    )
    measurements = {
        "speech_seconds": round(float(speech_seconds), 6),
        "pause_seconds": round(float(pause_seconds), 6),
        "pause_total_seconds": round(float(pause_total), 6),
        "narration_seconds": round(float(speech_seconds + pause_total), 6),
        "silent_count": int(silent_count),
        "measured_chars_per_second": round(float(measured_rate), 6),
        "effective_chars_per_second": round(
            float(effective_rate or measured_rate), 6
        ),
        "spoken_chars_measured": int(spoken_chars),
    }
    # Every measurement of real TTS audio teaches the process-wide
    # script-length rate, so the next window/next job is sized at the
    # voice's true speaking rate instead of a hard-coded guess.
    measurements["learned_chars_per_second"] = round(
        record_narration_rate(measurements), 4
    )
    return measurements


def _calibration_desired_total_chars(
    measurements: dict,
    current_chars: int,
    target_final_seconds: float,
    *,
    expand: bool,
) -> int:
    """Char total that should land narration on the duration target.

    Derived from the *effective* rate (all script chars over all
    produced speech seconds), so a "long" narration always yields a
    desired total below the current one and trimming converges.
    """
    m = measurements or {}
    current = int(current_chars or 0)
    pause_total = float(m.get("pause_total_seconds") or 0)
    desired_speech = max(0.1, float(target_final_seconds or 0) - pause_total)
    speech_seconds = float(m.get("speech_seconds") or 0)
    rate = 0.0
    if speech_seconds > 0 and current > 0:
        rate = current / speech_seconds
    if rate <= 0:
        rate = float(m.get("measured_chars_per_second") or 0)
    if rate <= 0:
        return current
    if expand:
        return int(math.ceil(desired_speech * rate * 1.01))
    return int(math.floor(desired_speech * rate * 0.99))


def script_target_chars(chunk_dur: float, settings: dict = None) -> int:
    """Initial character estimate for the requested final duration.

    Voice speed is included so a faster voice needs more text to reach the
    same actual final duration.  The estimate is later corrected using the
    measured TTS rate for this exact job/voice.
    """
    ratio = _settings_coverage_ratio(settings)
    rate = _settings_script_rate(settings)
    speed = _settings_speed(settings)
    return int(max(0.0, float(chunk_dur or 0)) * ratio * rate * speed)


def script_total_chars(scenes: list) -> int:
    return sum(len((s.get("burmese") or "").strip()) for s in scenes if isinstance(s, dict))


def sort_scenes(scenes: list) -> list:
    def _start(s):
        try:
            return float(s.get("start", 0) or 0)
        except (TypeError, ValueError, AttributeError):
            return 0.0
    valid = [s for s in scenes if isinstance(s, dict) and (s.get("burmese") or "").strip()]
    return sorted(valid, key=_start)


# Burmese sentence terminators.  A spoken recap may only ever lose whole
# sentences: a mid-sentence cut leaves a dangling clause that the TTS
# reads out as broken, chopped speech (the v5.14 report: 341s narration
# shredded down to 112s).
SCRIPT_SENTENCE_END_CHARS = "။!?…"


def _split_sentences(text: str) -> list:
    """Split text into whole sentences, keeping their terminators."""
    value = str(text or "").strip()
    if not value:
        return []
    spans = []
    start = 0
    index = 0
    length = len(value)
    while index < length:
        if value[index] in SCRIPT_SENTENCE_END_CHARS:
            end = index + 1
            # eat repeated terminators ("။။") and the spaces after them
            while end < length and (
                value[end] in SCRIPT_SENTENCE_END_CHARS or value[end].isspace()
            ):
                end += 1
            chunk = value[start:end]
            if chunk.strip():
                spans.append(chunk)
            start = end
            index = end
        else:
            index += 1
    tail = value[start:]
    if tail.strip():
        spans.append(tail)
    return spans


def _text_is_sentence_structured(text: str) -> bool:
    """True when the text has at least one sentence terminator."""
    return any(ch in SCRIPT_SENTENCE_END_CHARS for ch in str(text or ""))


# Burmese combining marks: a cut that ends on one of these leaves a
# dangling mark that the TTS reads as a broken syllable.
_BURMESE_TRAILING_JUNK = set(
    # Dependent vowels (U+102B-U+1032) and medials (U+103B-U+103E) can
    # never end a Burmese word, so a cut that stops on one leaves a
    # broken syllable for the TTS.  Word-final marks that ARE legitimate
    # -- asat \u103a ("\u1000\u103a"), dot below \u1037, visarga \u1038 -- are
    # deliberately absent: "\u1000\u103b\u103d\u1014\u103a\u1010\u1031\u102c\u103a" ends on \u103a and is a
    # perfectly good word.
    "\u102b\u102c\u102d\u102e\u102f\u1030\u1031\u1032"
    "\u103b\u103c\u103d\u103e"
)


def _strip_trailing_burmese_junk(text: str) -> str:
    """Drop trailing combining marks / spaces left by a hard cut.

    A cut that stops right after a dependent vowel or tone mark leaves a
    dangling mark that the TTS reads as a broken syllable.
    """
    value = str(text or "").rstrip()
    while value and value[-1] in _BURMESE_TRAILING_JUNK:
        value = value[:-1].rstrip()
    return value


def _word_boundary_prefixes(text: str):
    """Yield shorter prefixes of ``text`` cut only at spaces / «၊»."""
    value = str(text or "").strip()
    if not value:
        return
    seen = set()
    for index, char in enumerate(value):
        if char not in " ၊":
            continue
        prefix = _strip_trailing_burmese_junk(value[:index])
        if not prefix or prefix in seen:
            continue
        seen.add(prefix)
        yield prefix


def trim_scenes_proportionally(scenes: list, desired_total_chars: int) -> list:
    """Shorten the script only at sentence boundaries.

    Used after measured TTS shows the narration is too long.  Each step
    removes one whole trailing sentence -- choosing the scene whose
    trailing sentence comes closest to the exact excess, so the script
    lands on the target instead of being rounded down wildly -- and a
    scene whose single sentence is still too long is dropped whole rather
    than chopped.  The v5.14 report was narration shredded proportionally
    through the middle of sentences, which the TTS read as broken, chopped
    speech.  Text with no sentence terminator at all (a punctuation-free
    model reply) falls back to a word-boundary character cut.

    With the learned script-length rate the script now arrives at (or just
    above) the requested size, so this is a small correction -- usually
    dropping the last sentence of a few scenes -- instead of deleting two
    thirds of the narration.

    v5.18: whole sentences are far too coarse to hit a ±2% duration
    window (one 26-character Burmese sentence is ~12 seconds of speech),
    which is why calibration used to jump from "long" to "short" and back
    and then refuse a fixable 124s narration of a 125.5s window.  Trimming
    therefore runs in two phases: whole sentences/scenes first, but never
    past the requested budget, and then the few remaining characters are
    taken out of the *tail* of the last scenes at a word boundary.
    """
    trimmed = [dict(s) for s in (scenes or []) if isinstance(s, dict)]
    desired = max(0, int(desired_total_chars or 0))
    total = script_total_chars(trimmed)
    if not trimmed or desired <= 0 or total <= desired:
        return trimmed

    max_attempts = 20 + 6 * sum(
        len(_split_sentences(scene.get("burmese") or "")) for scene in trimmed
    )
    attempts = 0
    # Phase 1 -- remove whole trailing sentences (or whole single-sentence
    # scenes), but never below the requested budget.  Undershooting is
    # what used to cost an expensive Gemini top-up call and made the
    # calibration oscillate long -> short -> long.
    while total > desired and attempts < max_attempts:
        attempts += 1
        excess = total - desired
        best = None  # (left-over excess, scene index, new text)
        for index, scene in enumerate(trimmed):
            current = str(scene.get("burmese") or "").strip()
            if not current:
                continue
            sentences = _split_sentences(current)
            if len(sentences) > 1:
                shortened = "".join(sentences[:-1]).strip()
            else:
                # One whole sentence that cannot be split: remove the
                # scene instead of shipping a half sentence.
                shortened = ""
            if shortened == current:
                continue
            removed = len(current) - len(shortened)
            if removed > excess:
                # Removing this unit would land *under* the budget by more
                # than phase 2 can add back (it cannot add at all), and an
                # undershoot costs a whole Gemini top-up call and made the
                # old calibration oscillate long -> short -> long.  Leave
                # the remainder to the word-boundary phase.
                continue
            distance = excess - removed
            if best is None or distance < best[0]:
                best = (distance, index, shortened)
        if best is None:
            break
        # Only take a step that actually gets closer to the budget:
        # removing a unit that is much larger than what is left to remove
        # would overshoot by seconds of speech and start the long/short
        # oscillation this phase exists to avoid.
        if best[0] >= abs(total - desired):
            break
        trimmed[best[1]]["burmese"] = best[2]
        total = script_total_chars(trimmed)

    # Phase 2 -- the remaining few characters, taken out of the tail of
    # the last scenes at a word boundary.  A ±2% window is only a handful
    # of characters wide, so this phase is what actually makes the
    # measured duration land on target.  Every word-boundary cut of the
    # last few scenes is scored and the *closest* one wins, so the script
    # is not pushed below the budget (an undershoot costs an expensive
    # Gemini top-up and used to make calibration oscillate).
    if total > desired:
        # "Leave the text alone" is itself a candidate: if no word cut
        # lands closer to the budget, keeping the few extra characters
        # (a fraction of a second of speech) is the better trade.
        best = (abs(total - desired), None, None)
        checked = 0
        for index in range(len(trimmed) - 1, -1, -1):
            current = str(trimmed[index].get("burmese") or "").strip()
            if not current:
                continue
            checked += 1
            if checked > 3:
                break
            min_keep = max(8, int(len(current) * 0.4))
            for candidate in _word_boundary_prefixes(current):
                if not candidate or len(candidate) >= len(current):
                    continue
                if len(candidate) < min_keep:
                    continue
                new_total = total - (len(current) - len(candidate))
                distance = abs(new_total - desired)
                if best is None or distance < best[0]:
                    best = (distance, index, candidate)
        if best[1] is not None:
            text = str(best[2] or "").strip()
            if text and text[-1] not in SCRIPT_SENTENCE_END_CHARS:
                text = text + "။"
            trimmed[best[1]]["burmese"] = text

    kept = [scene for scene in trimmed if str(scene.get("burmese") or "").strip()]
    if not kept:
        # Never trim the narration away entirely (an over-aggressive
        # desired_total_chars must not yield silence): keep the opening
        # scene's first whole sentence, which carries the protagonist's
        # first person.
        for scene in trimmed:
            sentences = _split_sentences(str(scene.get("burmese") or ""))
            if sentences:
                fallback = dict(scene)
                fallback["burmese"] = sentences[0].strip()
                kept = [fallback]
                break
    return kept


def _trim_scenes_for_duration(
    scenes: list,
    measurements: dict,
    target_seconds: float,
    *,
    tolerance_seconds: float = 0.0,
) -> list:
    """Shorten the script so *the measured rate* lands on the target.

    The character budget is derived from this job's measured
    chars/second, so a character-accurate trim is a duration-accurate
    trim.  Trimming itself cuts whole trailing sentences first and then
    the last few characters at a word boundary (see
    ``trim_scenes_proportionally``), which is what makes a ±3% window
    reachable at all: one whole Burmese sentence is 10-15 seconds of
    speech, so sentence-only trimming used to jump from "long" straight
    to "short" (production: 124.2s narration, target 113s, no
    convergence, job refused after three attempts).

    ``tolerance_seconds`` is accepted for callers that want to document
    the window they are aiming at; the budget targets its centre.
    """
    current = [dict(scene) for scene in (scenes or []) if isinstance(scene, dict)]
    if not current:
        return current
    m = measurements or {}
    rate = float(m.get("effective_chars_per_second") or 0)
    pause = float(m.get("pause_seconds") or 0)
    target = float(target_seconds or 0)
    if rate <= 0 or target <= 0:
        return current
    palette = pause * max(0, len(current) - 1)
    desired_chars = int(
        max(1, round(max(0.1, target - palette) * rate))
    )
    return trim_scenes_proportionally(current, desired_chars)


def trim_scenes_to_target(scenes: list, target_chars: int) -> list:
    """Cap an initially over-long script without deleting its ending.

    The cap is the 1.05x allowance, not the target itself: the first
    prompt deliberately asks for ~15% extra text (models undershoot
    character counts), and trimming all the way down to the target here
    would needlessly land the narration *short*, which costs an expensive
    Gemini video call to expand it.  A few percent long is corrected for
    free by the measured-duration trim after TTS.
    """
    limit = int(max(0, int(target_chars or 0)) * SCRIPT_MAX_RATIO)
    if script_total_chars(scenes) <= limit:
        return scenes
    return trim_scenes_proportionally(scenes, limit)


# A single spoken sentence much beyond this turns into a breathless
# run-on when the TTS reads it (production scripts arrived with
# mega-sentences chained by "၊" for a whole scene).  The polish pass
# below breaks only those runaways, at their own clause commas.
_SPEECH_MAX_SENTENCE_CHARS = 150


_BURMESE_DIGIT_WORDS = (
    "သုည", "တစ်", "နှစ်", "သုံး", "လေး",
    "ငါး", "ခြောက်", "ခုနစ်", "ရှစ်", "ကိုး",
)
_BURMESE_NUMBER_PLACES = (
    (10_000_000, "ကုဋေ"),
    (1_000_000, "သန်း"),
    (100_000, "သိန်း"),
    (10_000, "သောင်း"),
    (1_000, "ထောင်"),
    (100, "ရာ"),
    (10, "ဆယ်"),
)
_MYANMAR_DIGIT_MAP = str.maketrans("၀၁၂၃၄၅၆၇၈၉", "0123456789")
_SPOKEN_NUMBER_RE = re.compile(r"(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?")
_TTS_UNSAFE_SCRIPT_RE = re.compile(
    r"[A-Za-z\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]"
)
_TTS_UNSAFE_TOKEN_RE = re.compile(
    r"[A-Za-z]+(?:[-'][A-Za-z]+)*|[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]+"
)


def _tts_unsafe_script_chars(text: str) -> int:
    """Count letters the Burmese narration voices cannot speak safely."""
    return len(_TTS_UNSAFE_SCRIPT_RE.findall(str(text or "")))


def _tts_unsafe_tokens(text: str) -> list:
    """Foreign-script runs left in narration, for actionable QA."""

    return _TTS_UNSAFE_TOKEN_RE.findall(str(text or ""))


def _tts_unsafe_scene_indexes(scenes: list) -> list:
    """Scene indexes whose spoken text still contains foreign script."""

    indexes = []
    for index, scene in enumerate(scenes or []):
        if _tts_unsafe_script_chars(_scene_text_for_pov(scene)):
            indexes.append(index)
    return indexes


# Chinese subtitles and model story maps routinely mix Simplified and
# Traditional spellings of the same name (杨伟 / 楊偉, 九州学院长老 /
# 九州學院長老). Exact-string ledger matching therefore missed the very
# tokens it knew. This deliberately small character table only expands
# a *known* ledger/token form to its other common spelling; it never
# translates or guesses a whole word by itself.
_CJK_VARIANT_PAIRS = (
    ("杨", "楊"), ("伟", "偉"), ("学", "學"), ("长", "長"),
    ("关", "關"), ("闭", "閉"), ("间", "間"), ("灵", "靈"),
    ("讳", "諱"), ("强", "強"), ("么", "麼"), ("们", "們"),
    ("这", "這"), ("个", "個"), ("时", "時"), ("还", "還"),
    ("来", "來"), ("国", "國"), ("龙", "龍"), ("凤", "鳳"),
    ("云", "雲"), ("风", "風"), ("电", "電"), ("声", "聲"),
    ("气", "氣"), ("门", "門"), ("开", "開"), ("进", "進"),
    ("远", "遠"), ("运", "運"), ("动", "動"), ("战", "戰"),
    ("场", "場"), ("点", "點"), ("实", "實"), ("现", "現"),
    ("发", "發"), ("会", "會"), ("对", "對"), ("说", "說"),
    ("话", "話"), ("语", "語"), ("问", "問"), ("题", "題"),
    ("应", "應"), ("变", "變"), ("样", "樣"), ("东", "東"),
    ("车", "車"), ("马", "馬"), ("鸟", "鳥"), ("鱼", "魚"),
    ("书", "書"), ("画", "畫"), ("写", "寫"), ("读", "讀"),
    ("听", "聽"), ("见", "見"), ("观", "觀"), ("觉", "覺"),
    ("亲", "親"), ("爱", "愛"), ("乐", "樂"), ("欢", "歡"),
    ("庆", "慶"), ("兴", "興"), ("军", "軍"), ("农", "農"),
    ("医", "醫"), ("药", "藥"), ("师", "師"), ("贵", "貴"),
    ("宾", "賓"), ("钱", "錢"), ("银", "銀"), ("铁", "鐵"),
    ("铜", "銅"), ("钢", "鋼"), ("钟", "鐘"), ("针", "針"),
    ("权", "權"), ("势", "勢"), ("号", "號"), ("称", "稱"),
    ("历", "歷"), ("经", "經"), ("统", "統"), ("领", "領"),
    ("导", "導"), ("团", "團"), ("队", "隊"), ("员", "員"),
    ("级", "級"), ("阶", "階"), ("层", "層"),
)
_CJK_VARIANT_MAP = {}
for _simplified, _traditional in _CJK_VARIANT_PAIRS:
    _CJK_VARIANT_MAP[_simplified] = _traditional
    _CJK_VARIANT_MAP[_traditional] = _simplified


def _cjk_variant_forms(value) -> list:
    """Common Simplified/Traditional spellings of one exact CJK form."""

    text = str(value or "")
    forms = {text}
    for char in text:
        variant = _CJK_VARIANT_MAP.get(char)
        if not variant or variant == char:
            continue
        expanded = set()
        for form in forms:
            expanded.add(form.replace(char, variant))
        forms.update(expanded)
        if len(forms) >= 32:
            break
    return sorted(forms, key=lambda item: (item != text, item))


def _tts_unsafe_token_contexts(
    scenes: list,
    tokens=None,
    *,
    limit: int = 32,
) -> list:
    """Unique foreign tokens with one short spoken context for repair."""

    scene_texts = [_scene_text_for_pov(scene) for scene in (scenes or [])]
    requested = []
    for token in tokens or []:
        clean = str(token or "").strip()
        if clean and clean not in requested:
            requested.append(clean)
    if not requested:
        for text in scene_texts:
            for token in _tts_unsafe_tokens(text):
                if token not in requested:
                    requested.append(token)

    contexts = []
    for token in requested[: max(0, int(limit or 0))]:
        context = ""
        scene_index = None
        for index, text in enumerate(scene_texts):
            if token not in text:
                continue
            scene_index = index
            context = next(
                (
                    sentence.strip()
                    for sentence in _split_sentences(text)
                    if token in sentence
                ),
                text,
            )
            break
        contexts.append(
            {
                "source": token,
                "scene_index": scene_index,
                "context": _clean_story_text(context, 260),
            }
        )
    return contexts


def _tts_token_repair_prompt(
    scenes: list,
    story_map: dict = None,
    story_context: dict = None,
    *,
    protagonist: str = "",
    tokens=None,
) -> str:
    """Ask only for a source-token -> Burmese-speech mapping.

    Rewriting whole scenes proved unreliable for this narrow job: a
    weak fallback model copied the Chinese names straight back,
    especially when the story map itself (incorrectly) used them as
    ``spoken_name``. A mapping is a much smaller, checkable task;
    local code then performs the replacements deterministically, so
    scene content, POV, order and length cannot drift.
    """

    contexts = _tts_unsafe_token_contexts(scenes, tokens)
    normalized_map = _normalize_story_map(story_map)
    normalized_context = _normalize_story_context(story_context or {})
    cards = _normalize_character_cards(
        list(normalized_context.get("character_cards") or [])
        + list(normalized_map.get("character_cards") or [])
    )
    ledger = {
        "protagonist_source_form": protagonist,
        "character_cards": [
            {
                "spoken_name": _character_card_spoken_name(card),
                "short_name": _character_card_short_name(card),
                "source_name": card.get("source_name") or "",
                "aliases": card.get("aliases") or [],
                "role": card.get("role") or "",
                "relation": card.get("relation") or "",
                "identity_anchor": card.get("identity_anchor") or "",
                "visual_cue": card.get("visual_cue") or "",
            }
            for card in cards
        ],
        "terms": _normalize_story_terms(
            list(normalized_context.get("terms") or [])
            + list(normalized_map.get("terms") or [])
        ),
        "visible_texts": normalized_map.get("visible_texts") or [],
    }
    return f"""
TTS FOREIGN-SCRIPT TOKEN REPAIR ONLY — scene တွေကို ပြန်မရေးပါနှင့်။ အောက်ပါ source token တစ်ခုစီအတွက် Burmese TTS ဖတ်နိုင်တဲ့ မြန်မာအက္ခရာသီးသန့် အစားထိုးပုံစံသာ ပြန်ပေးပါ။

စည်းကမ်းများ:
- Token အားလုံးကို တစ်ကြိမ်စီ အတိအကျထည့်ပါ။ `source` ကို မူရင်းအတိုင်း ကူးပါ။
- `burmese` ထဲမှာ မြန်မာအက္ခရာနဲ့ space သာရှိရမည်။ အင်္ဂလိပ်/တရုတ်/ကိုရီးယား/ဂျပန်စာလုံး၊ ဂဏန်း၊ parenthesis၊ ရှင်းလင်းချက်စာသား လုံးဝမထည့်ရ။
- လူ/နေရာ/အဖွဲ့အမည်ဆိုလျှင် မူရင်းအသံကို သဘာဝကျတဲ့ မြန်မာအသံထွက်နဲ့ ရေးပါ။ Card ထဲမှာ Burmese spoken_name/short_name အမှန်ရှိလျှင် အဲဒီပုံစံအတိအကျကိုသာ သုံးပါ။
- Story map ထဲက `spoken_name` ကိုယ်တိုင်က နိုင်ငံခြားစာလုံးဖြစ်နေလျှင် အဲဒါ locked spoken form မဟုတ်ပါ — evidence သာဖြစ်သည်။ Burmese transliteration အသစ်ကို lock လုပ်ပါ။
- အမည်နဲ့ ရာထူး/အဖွဲ့ ပေါင်းထားတဲ့ token ဆိုလျှင် အမည်ကို အသံထွက်ရေးပြီး ရာထူး/အဖွဲ့ကို မြန်မာအဓိပ္ပာယ်နဲ့ သဘာဝကျကျ ပေါင်းရေးပါ။
- သာမန်နာမ်၊ စွမ်းအား၊ အခမ်းအနား၊ စည်းမျဉ်းနဲ့ စာကြောင်းတိုဆိုလျှင် အဓိပ္ပာယ်ကို တိုပြီး ဝါကျထဲ သဘာဝကျကျ အစားထိုးနိုင်တဲ့ မြန်မာနာမ်စကားစုနဲ့ ပြန်ပါ။
- နတ်ဘုရား/ဒဏ္ဍာရီ ဘွဲ့အမည်ဆိုလျှင် အသံထွက်ကိုရေးပါ။ အဓိပ္ပာယ်က နားလည်မှုအတွက် မရှိမဖြစ်ဆိုလျှင် အသံထွက်နောက် မြန်မာဘွဲ့အဓိပ္ပာယ်တိုတိုကိုသာ ပေါင်းပါ။
- Token ကို မဖျက်ပါနှင့်၊ ဝါကျအသစ် မဖန်တီးပါနှင့်၊ source အတိုင်း ပြန်မပေးပါနှင့်။

Cast/term ledger (foreign forms are evidence only):
{json.dumps(ledger, ensure_ascii=False)}

Tokens and spoken contexts:
{json.dumps(contexts, ensure_ascii=False)}

JSON ကိုသာပြန်ပေးပါ:
{{"replacements": [{{"source": "မူရင်း token အတိအကျ", "burmese": "မြန်မာအက္ခရာသီးသန့် အစားထိုးပုံစံ"}}]}}
""".strip()


def _parse_tts_token_replacements(data, allowed_tokens) -> dict:
    """Parse and validate a token-mapping response."""

    try:
        parsed = _parse_gemini_json_text(data)
    except Exception:
        parsed = data
    allowed = []
    for token in allowed_tokens or []:
        clean = str(token or "").strip()
        if clean and clean not in allowed:
            allowed.append(clean)
    allowed_set = set(allowed)

    def canonical_source(value) -> str:
        source = str(value or "").strip().strip("\"'“”‘’")
        if source in allowed_set:
            return source
        for form in _cjk_variant_forms(source):
            if form in allowed_set:
                return form
        return ""

    candidates = []
    if isinstance(parsed, list):
        candidates.extend(parsed)
    elif isinstance(parsed, dict):
        for key in (
            "replacements",
            "token_replacements",
            "translations",
            "tokens",
            "items",
        ):
            value = parsed.get(key)
            if isinstance(value, list):
                candidates.extend(value)
            elif isinstance(value, dict):
                candidates.extend(
                    {"source": source, "burmese": target}
                    for source, target in value.items()
                )
        if not candidates:
            candidates.extend(
                {"source": source, "burmese": target}
                for source, target in parsed.items()
                if isinstance(target, str)
            )

    replacements = {}
    for item in candidates:
        if not isinstance(item, dict):
            continue
        source_value = ""
        for key in ("source", "token", "original", "source_text", "text"):
            if item.get(key):
                source_value = item.get(key)
                break
        source = canonical_source(source_value)
        if not source or source in replacements:
            continue
        target_value = ""
        for key in (
            "burmese",
            "replacement",
            "spoken",
            "spoken_form",
            "transliteration",
            "translation",
            "target",
        ):
            if item.get(key):
                target_value = item.get(key)
                break
        target = _tts_safe_spoken_form(target_value, limit=180)
        target = target.strip(" \"'“”‘’()[]{}")
        if target and target != source:
            replacements[source] = target
    return replacements


def _apply_tts_token_replacements(
    scenes: list,
    replacements: dict,
    story_map: dict = None,
    story_context: dict = None,
) -> dict:
    """Apply a validated token mapping and lock Burmese name forms."""

    stats = {
        "replacements": 0,
        "replaced_tokens": [],
        "locked_tokens": {},
        "remaining_unsafe_chars": 0,
        "remaining_tokens": [],
    }
    clean_replacements = {}
    conflicting = set()
    for raw_source, raw_target in (replacements or {}).items():
        source = _clean_story_text(raw_source, 180)
        target = _tts_safe_spoken_form(raw_target, limit=180)
        if not source or not target or source == target:
            continue
        if not _tts_unsafe_script_chars(source):
            continue
        for form in _cjk_variant_forms(source):
            previous = clean_replacements.get(form)
            if previous is not None and previous != target:
                conflicting.add(form)
            else:
                clean_replacements[form] = target
    for form in conflicting:
        clean_replacements.pop(form, None)

    def collect_remaining():
        remaining = []
        total = 0
        for scene in scenes or []:
            text = _scene_text_for_pov(scene)
            total += int(_tts_unsafe_script_chars(text))
            for token in _tts_unsafe_tokens(text):
                if token not in remaining:
                    remaining.append(token)
        stats["remaining_unsafe_chars"] = int(total)
        stats["remaining_tokens"] = remaining[:16]

    if not clean_replacements:
        collect_remaining()
        return stats

    def values_match(left, right) -> bool:
        clean_left = str(left or "").strip()
        clean_right = str(right or "").strip()
        if not clean_left or not clean_right:
            return False
        return bool(
            set(_cjk_variant_forms(clean_left))
            & set(_cjk_variant_forms(clean_right))
        )

    def lock_container(container):
        if not isinstance(container, dict):
            return
        for source, target in clean_replacements.items():
            for key in ("protagonist", "main_character"):
                if values_match(container.get(key), source):
                    container[key] = target
            characters = container.get("characters")
            if isinstance(characters, list):
                container["characters"] = [
                    target
                    if isinstance(item, str) and values_match(item, source)
                    else item
                    for item in characters
                ]
            for list_key in ("character_cards", "characters"):
                for card in container.get(list_key) or []:
                    if not isinstance(card, dict):
                        continue
                    old_spoken = _character_card_spoken_name(card)
                    old_short = _character_card_short_name(card)
                    forms = [
                        old_spoken,
                        old_short,
                        card.get("source_name"),
                        *(card.get("aliases") or []),
                    ]
                    if not any(values_match(form, source) for form in forms):
                        continue
                    if old_spoken and _tts_unsafe_script_chars(old_spoken):
                        card["spoken_name"] = target
                        card["name"] = target
                        if not card.get("source_name"):
                            card["source_name"] = source
                    if (
                        old_short
                        and _tts_unsafe_script_chars(old_short)
                        and values_match(old_short, source)
                        and _normalize_burmese_text(old_short)
                        != _normalize_burmese_text(old_spoken)
                    ):
                        card["short_name"] = target
                    aliases = [
                        str(alias)
                        for alias in (card.get("aliases") or [])
                        if str(alias).strip()
                    ]
                    if source not in aliases and source != target:
                        aliases.append(source)
                    card["aliases"] = aliases[:8]
            for list_key in ("terms", "glossary", "world_terms", "key_terms"):
                for term in container.get(list_key) or []:
                    if not isinstance(term, dict):
                        continue
                    forms = [
                        term.get("spoken_term"),
                        term.get("source_term"),
                        *(term.get("aliases") or []),
                    ]
                    if not any(values_match(form, source) for form in forms):
                        continue
                    old_spoken = str(term.get("spoken_term") or "")
                    if old_spoken and _tts_unsafe_script_chars(old_spoken):
                        term["spoken_term"] = target
                        if not term.get("source_term"):
                            term["source_term"] = source

    lock_container(story_map)
    lock_container(story_context)

    replaced_tokens = []
    for scene in scenes or []:
        if not isinstance(scene, dict):
            continue
        original = str(scene.get("burmese") or "")
        updated = original
        for source, target in sorted(
            clean_replacements.items(),
            key=lambda item: len(item[0]),
            reverse=True,
        ):
            if source not in updated:
                continue
            if all(ord(char) < 128 for char in source):
                pattern = (
                    r"(?<![A-Za-z])" + re.escape(source) + r"(?![A-Za-z])"
                )
                updated, count = re.subn(pattern, target, updated)
            else:
                count = updated.count(source)
                updated = updated.replace(source, target)
            if count:
                stats["replacements"] += int(count)
                if source not in replaced_tokens:
                    replaced_tokens.append(source)
                stats["locked_tokens"][source] = target
        if updated != original:
            scene["burmese"] = updated

    stats["replaced_tokens"] = replaced_tokens[:16]
    collect_remaining()
    return stats


def _professional_repair_scene_indexes(metrics: dict) -> list:
    """Scenes behind severe actor/dialogue-identity gate failures."""

    metrics = metrics if isinstance(metrics, dict) else {}
    scene_count = int(metrics.get("scene_count") or 0)
    if scene_count < 4:
        return []
    severe_scene_threshold = max(3, math.ceil(scene_count / 3))
    indexes = set()

    def add_indexes(values):
        for value in values or []:
            try:
                index = int(value)
            except (TypeError, ValueError):
                continue
            if 0 <= index < scene_count:
                indexes.add(index)

    actor_indexes = metrics.get("actor_unclear_scene_opening_indexes") or []
    if len(actor_indexes) >= severe_scene_threshold:
        add_indexes(actor_indexes)
    unnamed_indexes = list(metrics.get("unnamed_actor_scene_indexes") or [])
    unnamed_indexes.extend(metrics.get("unnamed_scene_opening_indexes") or [])
    if int(metrics.get("unnamed_actor_scenes") or 0) >= severe_scene_threshold:
        add_indexes(unnamed_indexes)
    for refs_key in (
        "ambiguous_pronoun_sentence_refs",
        "unattributed_dialogue_sentence_refs",
    ):
        refs = metrics.get(refs_key) or []
        if len(refs) < 3:
            continue
        for ref in refs:
            add_indexes([str(ref or "").split(":", 1)[0]])
    return sorted(indexes)


def _burmese_number_words(value) -> str:
    """Render an integer as spoken Burmese words.

    15 -> တစ်ဆယ့်ငါး, 250 -> နှစ်ရာ့ငါးဆယ်,
    1234 -> တစ်ထောင့်နှစ်ရာ့သုံးဆယ့်လေး, 2000000 -> နှစ်သန်း.
    """
    try:
        number = int(value)
    except (TypeError, ValueError):
        return str(value or "")
    if number < 0:
        return "အနုတ်" + _burmese_number_words(-number)
    if number == 0:
        return _BURMESE_DIGIT_WORDS[0]
    parts = []
    remainder = number
    for place, name in _BURMESE_NUMBER_PLACES:
        if remainder >= place:
            digit = remainder // place
            if digit > 9:
                # Beyond 9x10^7: read digit by digit rather than
                # inventing a wrong place name.
                return "".join(
                    _BURMESE_DIGIT_WORDS[int(ch)] for ch in str(number)
                )
            parts.append((f"{_BURMESE_DIGIT_WORDS[digit]}{name}", place))
            remainder -= digit * place
    if remainder:
        parts.append((_BURMESE_DIGIT_WORDS[remainder], 1))
    spoken = ""
    for index, (part_text, place) in enumerate(parts):
        spoken += part_text
        # Places up to ထောင် take a linking ့ before what follows
        # (တစ်ဆယ့်ငါး, နှစ်ရာ့ငါးဆယ်); သောင်း and above do not.
        if index + 1 < len(parts) and place <= 1000:
            spoken += "့"
    return spoken


def _spoken_numbers(text: str) -> str:
    """Replace ASCII/Myanmar digit runs with Burmese number words.

    TTS voices mispronounce or skip digit strings, and a raw
    "50%" or "1234" inside narration breaks the natural spoken
    flow. The script prompts forbid digits outright; this is the
    deterministic safety net for any that slip through.
    """
    value = str(text or "").translate(_MYANMAR_DIGIT_MAP)

    def _replace(match) -> str:
        token = match.group(0)
        percent = token.endswith("%")
        if percent:
            token = token[:-1]
        token = token.replace(",", "")
        try:
            if "." in token:
                whole, fraction = token.split(".", 1)
                words = _burmese_number_words(int(whole)) + "ပွိုင့်" + "".join(
                    _BURMESE_DIGIT_WORDS[int(ch)]
                    for ch in fraction
                    if ch.isdigit()
                )
            else:
                words = _burmese_number_words(int(token))
        except (TypeError, ValueError):
            return match.group(0)
        return words + ("ရာခိုင်နှုန်း" if percent else "")

    return _SPOKEN_NUMBER_RE.sub(_replace, value)


