def _map_unquoted_text(text: str, mapper) -> str:
    """Apply ``mapper`` only outside quoted direct-speech spans."""

    value = str(text or "")
    spans = []
    for pattern in _QUOTED_SPEECH_PATTERNS:
        spans.extend(
            (match.start(), match.end()) for match in pattern.finditer(value)
        )
    if not spans:
        return mapper(value)
    merged = []
    for start, end in sorted(spans):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    pieces = []
    cursor = 0
    for start, end in merged:
        if start > cursor:
            pieces.append(mapper(value[cursor:start]))
        pieces.append(value[start:end])
        cursor = max(cursor, end)
    if cursor < len(value):
        pieces.append(mapper(value[cursor:]))
    return "".join(pieces)


def _convert_sentence_final_register(body: str) -> str:
    value = str(body or "").rstrip()
    for old, new in sorted(
        _WRITTEN_REGISTER_SUFFIXES,
        key=lambda item: len(item[0]),
        reverse=True,
    ):
        if value.endswith(old):
            return value[:-len(old)] + new
    return value


def _convert_written_register_chunk(chunk: str) -> str:
    """Convert safe written-Burmese narration endings to spoken forms.

    This is intentionally conservative: it changes unambiguous formal
    sentence endings and a small phrase list, while leaving names, quoted
    dialogue and constructions that need real rewriting to the story
    editor.  It is the deterministic floor beneath the prompts; a script
    no longer reaches TTS still saying a formal book ending just because
    the model ignored the spoken-style instruction.
    """

    raw_chunk = str(chunk or "")
    if not raw_chunk.strip():
        return raw_chunk
    leading = raw_chunk[:len(raw_chunk) - len(raw_chunk.lstrip())]
    trailing = raw_chunk[len(raw_chunk.rstrip()):]
    pieces = []
    for raw_sentence in _split_sentences(raw_chunk):
        sentence = " ".join(str(raw_sentence or "").split())
        if not sentence:
            continue
        terminator = ""
        body = sentence
        while body and body[-1] in SCRIPT_SENTENCE_END_CHARS:
            terminator = body[-1] + terminator
            body = body[:-1].rstrip()
        for old, new in _WRITTEN_REGISTER_PHRASES:
            body = body.replace(old, new)
        body = re.sub(r"စဉ်(?=(?:\s|[၊။!?…]|$))", "တုန်း", body)
        if terminator:
            body = _convert_sentence_final_register(body)
        pieces.append(body + terminator)
    return leading + " ".join(pieces) + trailing


def _remove_adjacent_repeated_clauses(sentence: str) -> str:
    """Drop a clause repeated immediately inside the same sentence.

    Sentence-level dedupe cannot see ``X လုပ်တယ်၊ X လုပ်တယ်။`` because
    it is one spoken sentence.  This only removes an adjacent clause
    whose normalized wording is effectively the same; ordinary
    Burmese clause chaining and explicitly marked repeated actions
    are untouched.
    """
    import difflib

    value = " ".join(str(sentence or "").split()).strip()
    if "၊" not in value:
        return value
    terminator = ""
    body = value
    while body and body[-1] in SCRIPT_SENTENCE_END_CHARS:
        terminator = body[-1] + terminator
        body = body[:-1].rstrip()
    clauses = [clause.strip() for clause in body.split("၊") if clause.strip()]
    if len(clauses) < 2:
        return value
    kept = []
    kept_keys = []
    for clause in clauses:
        key = _near_duplicate_key(clause)
        duplicate = False
        if kept_keys and len(key) >= 14 and not any(
            "".join(_normalize_burmese_text(marker).split()) in key
            for marker in _DEDUPE_EXPLICIT_REPEAT_MARKERS
        ):
            previous_key = kept_keys[-1]
            if key == previous_key:
                duplicate = True
            elif min(len(key), len(previous_key)) >= 18:
                left_grams = _character_ngrams(previous_key, 3)
                right_grams = _character_ngrams(key, 3)
                containment = (
                    len(left_grams & right_grams)
                    / min(len(left_grams), len(right_grams))
                    if left_grams and right_grams
                    else 0.0
                )
                sequence_ratio = difflib.SequenceMatcher(
                    None, previous_key, key, autojunk=False
                ).ratio()
                duplicate = bool(
                    containment >= 0.74 and sequence_ratio >= 0.88
                )
        if duplicate:
            continue
        kept.append(clause)
        kept_keys.append(key)
    if len(kept) == len(clauses):
        return value
    return "၊ ".join(kept) + terminator


def _polish_text_for_speech(text: str) -> str:
    """Make one scene's text easier for the TTS voice to speak naturally.

    - digit runs are spelled out as Burmese number words (the
      voice cannot be trusted with raw "1234" or "90%");
    - safe written-Burmese narration endings outside quotes become
      spoken endings, so the voice does not sound like a book;
    - whitespace runs collapse to single spaces;
    - a runaway "sentence" longer than ``_SPEECH_MAX_SENTENCE_CHARS``
      that is chained with Burmese clause commas (၊) is re-grouped
      into shorter sentences ending in ။ (natural breath points);
    - a final fragment with no terminator gains a closing ။ so the
      voice lands instead of trailing off mid-thought.
    """
    spoken_source = _map_unquoted_text(
        _spoken_numbers(text),
        _convert_written_register_chunk,
    )
    polished_sentences = []
    for raw_sentence in _split_sentences(spoken_source):
        sentence = _remove_adjacent_repeated_clauses(
            " ".join(str(raw_sentence or "").split())
        )
        if not sentence:
            continue
        if len(sentence) > _SPEECH_MAX_SENTENCE_CHARS and "၊" in sentence:
            terminator = ""
            body = sentence
            while body and body[-1] in SCRIPT_SENTENCE_END_CHARS:
                terminator = body[-1] + terminator
                body = body[:-1].rstrip()
            clauses = [c.strip() for c in body.split("၊") if c.strip()]
            groups = []
            current = ""
            for clause in clauses:
                candidate = f"{current}၊ {clause}" if current else clause
                if current and len(candidate) > _SPEECH_MAX_SENTENCE_CHARS:
                    groups.append(current)
                    current = clause
                else:
                    current = candidate
            if current:
                groups.append(current)
            for index, group in enumerate(groups):
                ending = terminator if index == len(groups) - 1 and terminator else "။"
                polished_sentences.append(group + ending)
        else:
            polished_sentences.append(sentence)
    result = " ".join(polished_sentences).strip()
    if result and result[-1] not in SCRIPT_SENTENCE_END_CHARS:
        if result[-1] not in "\"'”’»›」』〉》":
            result = _convert_sentence_final_register(result)
        result += "။"
    return result


def _polish_scenes_for_speech(scenes: list) -> list:
    polished = []
    for scene in scenes or []:
        if not isinstance(scene, dict):
            continue
        text = _polish_text_for_speech(str(scene.get("burmese") or ""))
        if text:
            polished.append({**scene, "burmese": text})
    return polished


def _cap_scenes_to_source(
    scenes: list,
    source_seconds: float,
    settings: dict = None,
    *,
    minimum_chars: int = 0,
    cap_ratio: float = 0.95,
) -> list:
    """Pre-TTS insurance so the narration cannot outrun the source.

    If the script is *predicted* (at the learned speaking rate) to
    run past ``cap_ratio`` of the source window, whole sentences
    are trimmed before any audio exists -- no finished speech is
    ever harmed by this pass.  The 90% sizing target already aims
    lower; this only catches rate drift (e.g. a script written
    while the learned rate was still a cold-start guess).  The
    validated minimum is a hard floor: the cap never turns a full
    retelling into a summary.
    """
    scene_list = [s for s in (scenes or []) if isinstance(s, dict)]
    source = float(source_seconds or 0)
    if not scene_list or source <= 0:
        return scenes
    rate = _settings_script_rate(settings) * _settings_speed(settings)
    if rate <= 0:
        return scenes
    pause_total = _settings_pause_seconds(settings) * max(0, len(scene_list) - 1)
    budget_seconds = max(0.1, source * float(cap_ratio or 0.95) - pause_total)
    cap_chars = max(int(minimum_chars or 0), int(budget_seconds * rate))
    if script_total_chars(scene_list) <= cap_chars:
        return scenes
    logger.info(
        "Pre-TTS duration cap: %s chars predicted past %.0f%% of %.1fs "
        "source at %.1f chars/s; trimming to %s chars before synthesis",
        script_total_chars(scene_list),
        float(cap_ratio or 0.95) * 100,
        source,
        rate,
        cap_chars,
    )
    return sort_scenes(trim_scenes_proportionally(scene_list, cap_chars))


def _shave_scenes_to_seconds(
    scenes: list, measurements: dict, target_seconds: float, *, sort_result: bool = True
) -> tuple:
    """Trim whole sentences so measured-rate narration fits a ceiling.

    Returns ``(scenes, changed)``.  Only ever used to pull a
    narration that *exceeds its own source video* back under it --
    narration between the 90% target and the source length is kept
    whole (user rule).  Worker callers keep their group order
    (``sort_result=False``) so clip/group alignment is untouched.
    """
    scene_list = [s for s in (scenes or []) if isinstance(s, dict)]
    if not scene_list:
        return scenes, False
    before = script_total_chars(scene_list)
    trimmed = _trim_scenes_for_duration(
        scene_list, measurements, float(target_seconds or 0)
    )
    if not trimmed or script_total_chars(trimmed) >= before:
        return scenes, False
    return (sort_scenes(trimmed) if sort_result else trimmed), True


def _dedupe_key(sentence: str) -> str:
    """Comparison key for repeat detection (spacing/punctuation-free)."""
    key = _normalize_burmese_text(sentence)
    key = "".join(ch for ch in key if not ch.isspace())
    return key.strip("။!?…၊\"'«»“”‘’")


